def parse_link(value):
    """'[[SPUD-001/Kestrel]]' -> 'SPUD-001/Kestrel'; '' -> None."""
    if not value:
        return None
    m = re.fullmatch(r"\[\[([^\]|]+)(?:\|[^\]]*)?\]\]", value.strip())
    if not m:
        raise SpudError(EXIT_ERROR, "not a wikilink: %r" % value)
    return m.group(1)


def store_prose_if_needed(con, entity, entity_id, section, text, rendered_from_rows):
    """Keep the file's prose only where the rows cannot regenerate it."""
    if normalize_markdown(text) == normalize_markdown(rendered_from_rows):
        con.execute("DELETE FROM imported_sections WHERE entity = ? AND entity_id = ? AND section = ?", (entity, entity_id, section))
        return False
    table = SECTION_TABLES.get(section)
    through = con.execute("SELECT COALESCE(MAX(id), 0) FROM %s" % table).fetchone()[0] if table else 0
    con.execute(
        "INSERT INTO imported_sections (entity, entity_id, section, body, through_id) VALUES (?, ?, ?, ?, ?)"
        " ON CONFLICT(entity, entity_id, section) DO UPDATE SET body = excluded.body, through_id = excluded.through_id",
        (entity, entity_id, section, text, through),
    )
    return True


def ticket_layout(fm_keys, section_names):
    layout = {}
    if fm_keys != TICKET_FM_KEYS:
        layout["fm_keys"] = fm_keys
    if section_names != TICKET_SECTIONS:
        layout["sections"] = section_names
    return layout or None


def member_layout(section_names, blocked):
    default = [n for n in MEMBER_SECTIONS if n != "Blocked" or blocked is not None]
    return {"sections": section_names} if section_names != default else None


def require_keys(fm, keys, path):
    for key in keys:
        if key not in fm:
            raise SpudError(EXIT_ERROR, "%s: frontmatter lacks %s" % (path, key))


def import_ticket_file(ctx, con, at, path, rel):
    doc = split_document(path.read_text(encoding="utf-8"))
    fm = doc["frontmatter"]
    require_keys(fm, ["id", "title", "priority", "status", "origin", "created", "tags"], rel)
    key = fm["id"]
    m = re.fullmatch(r"([A-Z][A-Z0-9]*)-(\d+)", key)
    if not m:
        raise SpudError(EXIT_ERROR, "%s: id %r is not <PREFIX>-<number>" % (rel, key))
    project = con.execute("SELECT * FROM projects WHERE ticket_prefix = ?", (m.group(1),)).fetchone()
    if project is None:
        raise SpudError(EXIT_ERROR, "%s: no project has ticket prefix %s" % (rel, m.group(1)))
    if con.execute("SELECT 1 FROM tickets WHERE key = ?", (key,)).fetchone():
        raise SpudError(EXIT_ERROR, "%s is already in the ledger (imported before); `spud import --file` accepts edits to a rendered file" % key)
    if fm["priority"] not in PRIORITIES or fm["status"] not in TICKET_STATUSES or fm["origin"] not in ("eric", "proposal"):
        raise SpudError(EXIT_ERROR, "%s: priority, status or origin outside the schema's values" % rel)
    heading = None
    if doc["heading"]:
        tail = doc["heading"].split(" — ", 1)
        tail = tail[1] if len(tail) == 2 else doc["heading"]
        if tail != fm["title"]:
            heading = tail
    if doc["preamble"]:
        raise SpudError(EXIT_ERROR, "%s: text between the heading and the first section cannot be imported" % rel)
    names = [n for n, _ in doc["sections"]]
    if len(set(names)) != len(names):
        raise SpudError(EXIT_ERROR, "%s: a section repeats" % rel)
    sections = dict(doc["sections"])
    tags = fm["tags"] if isinstance(fm["tags"], list) else [fm["tags"]]
    t = insert_ticket(
        con, at, "import", project, fm["title"], fm["priority"], fm["status"], origin=fm["origin"],
        brief=sections.get("Brief", ""), sizing=sections.get("Size, persona and model decision", ""),
        outcome=sections.get("Outcome", ""), tags=tags, heading=heading, created_at=fm["created"],
        number=int(m.group(2)), layout=ticket_layout(list(fm.keys()), names),
    )
    # the file carries one date: updated_at takes it (closed_at stays NULL; the file has no close time)
    return {"ticket": t, "fm": fm, "sections": doc["sections"], "rel": rel, "derived": {"updated_at": "created"}}


MEMBER_USAGE_KEYS = ("duration_ms", "tool_uses", "tokens_out", "tokens_in", "tokens_cached")
SQLITE_INTEGER_MAX = 2**63 - 1


def usage_columns(fm, rel):
    """The usage keys a rendered member note carries when known (SPD-010), read back: duration_ms and
    tool_uses into their columns; the three token keys, when all are present, as total_tokens and a
    transcript-shaped usage_json that renders the same keys and Tokens cell again (in stands for
    input plus cache creation, so cache creation is 0).  A present key that is not a non-negative
    integer is refused, naming the file and the key."""
    values = {}
    for key in MEMBER_USAGE_KEYS:
        if key not in fm:
            continue
        value = fm[key]
        if not isinstance(value, str) or not re.fullmatch(r"[0-9]{1,19}", value) or int(value) > SQLITE_INTEGER_MAX:
            raise SpudError(EXIT_ERROR, "%s: %s must be a non-negative integer, not %r" % (rel, key, value))
        values[key] = int(value)
    columns = {key: values[key] for key in ("duration_ms", "tool_uses") if key in values}
    if all(key in values for key in ("tokens_out", "tokens_in", "tokens_cached")):
        total = values["tokens_out"] + values["tokens_in"] + values["tokens_cached"]
        if total > SQLITE_INTEGER_MAX:
            raise SpudError(EXIT_ERROR, "%s: tokens_out, tokens_in and tokens_cached sum past what an integer column holds" % rel)
        columns["total_tokens"] = total
        columns["usage_json"] = json.dumps({"source": "transcript", "imported": True, "usage": {
            "input_tokens": values["tokens_in"], "output_tokens": values["tokens_out"],
            "cache_creation_input_tokens": 0, "cache_read_input_tokens": values["tokens_cached"]}})
    if "cost_usd" in fm:  # SPD-013: the list-price cost the note showed, kept with the imported sum it was computed from
        value = fm["cost_usd"]
        if not isinstance(value, str) or not COST_USD.fullmatch(value):
            raise SpudError(EXIT_ERROR, "%s: cost_usd must be an amount of US dollars with at most two decimals, not %r" % (rel, value))
        if "usage_json" not in columns:
            raise SpudError(EXIT_ERROR, "%s: cost_usd needs tokens_out, tokens_in and tokens_cached beside it" % rel)
        columns["usage_json"] = json.dumps(dict(json.loads(columns["usage_json"]), cost_usd=usd_text(fractions.Fraction(value))))
    return columns


def import_member_file(ctx, con, at, path, rel, team_key):
    doc = split_document(path.read_text(encoding="utf-8"))
    fm = doc["frontmatter"]
    require_keys(fm, ["id", "name", "persona", "model", "parent", "ticket", "status", "spawned", "finished"], rel)
    ticket = con.execute("SELECT * FROM tickets WHERE team_key = ?", (team_key,)).fetchone()
    if ticket is None:
        raise SpudError(EXIT_ERROR, "%s: no ticket has team key %s (import the tickets first)" % (rel, team_key))
    if parse_link(fm["ticket"]) != ticket["key"]:
        raise SpudError(EXIT_ERROR, "%s: ticket %s does not match folder %s" % (rel, fm["ticket"], team_key))
    lineage = fm["id"]
    if not re.fullmatch(r"\d+(\.\d+)*", lineage):
        raise SpudError(EXIT_ERROR, "%s: id %r is not a lineage" % (rel, lineage))
    if fm["name"] != path.stem:
        raise SpudError(EXIT_ERROR, "%s: name %r does not match the file name" % (rel, fm["name"]))
    if con.execute("SELECT 1 FROM members WHERE ticket_id = ? AND (name = ? OR lineage = ?)", (ticket["id"], fm["name"], lineage)).fetchone():
        raise SpudError(EXIT_ERROR, "%s/%s is already in the ledger (imported before)" % (team_key, fm["name"]))
    parent_link = parse_link(fm["parent"])
    parent = None
    if parent_link and parent_link != "Spud":
        parent = get_member(con, parent_link)
        if parent["ticket_id"] != ticket["id"] or not lineage.startswith(parent["lineage"] + "."):
            raise SpudError(EXIT_ERROR, "%s: parent %s does not fit lineage %s" % (rel, parent_link, lineage))
    elif "." in lineage:
        raise SpudError(EXIT_ERROR, "%s: lineage %s needs a parent member" % (rel, lineage))
    if fm["persona"] not in PERSONAS or fm["model"] not in MODELS or fm["status"] not in MEMBER_STATUSES:
        raise SpudError(EXIT_ERROR, "%s: persona, model or status outside the schema's values" % rel)
    names = [n for n, _ in doc["sections"]]
    if len(set(names)) != len(names):
        raise SpudError(EXIT_ERROR, "%s: a section repeats" % rel)
    sections = dict(doc["sections"])
    spawned = fm["spawned"] or None
    finished = fm["finished"] or None
    derived = {"planned_at": "spawned" if spawned else "ticket.created"}
    blocked = sections.get("Blocked") if "Blocked" in sections else None
    usage = usage_columns(fm, rel)
    cur = con.execute(
        "INSERT INTO members (ticket_id, lineage, depth, parent_id, name, persona, agent_type, model, status, brief,"
        " result, blocked, outcome, layout, planned_at, spawned_at, finished_at, duration_ms, tool_uses, total_tokens, usage_json)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (ticket["id"], lineage, lineage.count(".") + 1, parent["id"] if parent else None, fm["name"], fm["persona"],
         fm.get("agent_type") or "spudagent", fm["model"], fm["status"], sections.get("Brief", ""),
         sections.get("Result") if "Result" in sections else None, blocked,
         sections.get("Outcome") if "Outcome" in sections else None,
         json.dumps(member_layout(names, blocked)) if member_layout(names, blocked) else None,
         spawned or ticket["created_at"], spawned, finished,
         usage.get("duration_ms"), usage.get("tool_uses"), usage.get("total_tokens"), usage.get("usage_json")),
    )
    member_id = cur.lastrowid
    write_event(con, at, "import", "import", "imported %s" % rel, ticket_id=ticket["id"], member_id=member_id, data={"source": rel, "derived": derived})
    for entry_at, body in parse_log_entries(sections.get("Log", "")):
        write_event(con, entry_at, "import", "member.log", body, ticket_id=ticket["id"], member_id=member_id,
                    data={"source": rel, "date_only": "T" not in entry_at})
    return {"member": get_member_by_id(con, member_id), "ticket": ticket, "fm": fm, "sections": doc["sections"], "rel": rel}


def import_handoffs(con, at, ticket, text):
    """Returns the columns whose value had to be derived (an unparsed line has no date of its own)."""
    derived = {}
    for line in text.split("\n"):
        if not line.strip() or line.strip().startswith("<!--"):
            continue
        parsed = parse_handoff_line(line)
        if parsed:
            date, frm, to, what = parsed
            from_id = handoff_party_id(con, ticket, frm)
            to_id = handoff_party_id(con, ticket, to)
            if from_id == "?" or to_id == "?":
                con.execute("INSERT INTO handoffs (ticket_id, at, what) VALUES (?, ?, ?)", (ticket["id"], date, line))
            else:
                con.execute(
                    "INSERT INTO handoffs (ticket_id, at, from_member_id, to_member_id, what) VALUES (?, ?, ?, ?, ?)",
                    (ticket["id"], date, from_id, to_id, what),
                )
        else:
            con.execute("INSERT INTO handoffs (ticket_id, at, what) VALUES (?, ?, ?)", (ticket["id"], ticket["created_at"], line))
            derived["handoffs.at"] = "created"
    return derived


TEAM_LINE = re.compile(r"^\s*- \[\[(?P<ref>[^\]|\\]+)(?:\\?\|[^\]]*)?\]\] \([^()]*(?:\([^()]*\)[^()]*)*\) — (?P<text>.+)$")


def import_team_summaries(con, ticket, text):
    """A tree line's ` — text` in a ticket's ## Team becomes that member's summary, when the member is
    on this ticket and has none (SPD-010: the section is generated, so its prose is never stored).
    Table rows, the embed, lines without the suffix and other teams' members are ignored.  Returns
    the columns whose value was derived."""
    derived = {}
    for line in text.split("\n"):
        m = TEAM_LINE.match(line)
        if not m or not m.group("text").strip():
            continue
        team_key, _, name = m.group("ref").partition("/")
        if team_key != ticket["team_key"]:
            continue
        cur = con.execute("UPDATE members SET summary = ? WHERE ticket_id = ? AND name = ? AND summary IS NULL",
                          (m.group("text").strip(), ticket["id"], name))
        if cur.rowcount:
            derived["members.summary"] = "Team section"
    return derived


def handoff_party_id(con, ticket, label):
    """'Kestrel (01)' -> member id; 'Spud' -> None; anything else -> '?'."""
    if label.strip() == "Spud":
        return None
    m = re.fullmatch(r"(\S+) \((\d+(?:\.\d+)*)\)", label.strip())
    if not m:
        return "?"
    row = con.execute("SELECT id FROM members WHERE ticket_id = ? AND name = ? AND lineage = ?", (ticket["id"], m.group(1), m.group(2))).fetchone()
    return row["id"] if row else "?"


def link_proposal(con, at, t, fm):
    """origin: proposal + proposed_by -> a proposals row on the ticket it arose on, decided
    `create` by Spud.  The file carries one date, so filed_at and the decision's at take it."""
    link = parse_link(fm.get("proposed_by", "")) if fm.get("proposed_by") else None
    if t["origin"] != "proposal":
        return {}
    if not link:
        raise SpudError(EXIT_ERROR, "%s has origin proposal but no proposed_by link" % t["key"])
    origin_member = get_member(con, link)
    cur = con.execute(
        "INSERT INTO proposals (ticket_id, origin_member_id, holder_member_id, title, filed_at, status, created_ticket_id)"
        " VALUES (?, ?, NULL, ?, ?, 'created', ?)",
        (origin_member["ticket_id"], origin_member["id"], t["title"], t["created_at"], t["id"]),
    )
    proposal_id = cur.lastrowid
    con.execute(
        "INSERT INTO proposal_decisions (proposal_id, at, by_member_id, decision, reason, created_ticket_id)"
        " VALUES (?, ?, NULL, 'create', '', ?)",
        (proposal_id, t["created_at"], t["id"]),
    )
    con.execute("UPDATE tickets SET proposal_id = ? WHERE id = ?", (proposal_id, t["id"]))
    return {"proposal.filed_at": "created", "proposal_decisions.at": "created"}


def bulk_import(ctx, con, paths):
    """Import markdown-v0 trees: each path is a root with ledger/ and reports/, a
    ledger/ dir (tickets/ and teams/), or a reports/ dir."""
    ledger_dirs = []
    report_dirs = []
    for p in paths:
        p = Path(p).resolve()
        if not p.is_dir():
            raise SpudError(EXIT_ERROR, "%s is not a directory" % p)
        if (p / "tickets").is_dir() or (p / "teams").is_dir():
            ledger_dirs.append((p, p.parent))
        elif p.name == "reports":
            report_dirs.append((p, p.parent))
        elif (p / "ledger").is_dir() or (p / "reports").is_dir():
            if (p / "ledger").is_dir():
                ledger_dirs.append((p / "ledger", p))
            if (p / "reports").is_dir():
                report_dirs.append((p / "reports", p))
        else:
            raise SpudError(EXIT_ERROR, "%s holds no ledger/ or reports/ tree" % p)
    counts = {"tickets": 0, "members": 0, "reports": 0, "report_entries": 0, "prose_sections": 0}
    at = now()
    with write_txn(con):
        imported_tickets = []
        imported_members = []
        for ledger, base in ledger_dirs:
            for path in sorted((ledger / "tickets").glob("*.md")) if (ledger / "tickets").is_dir() else []:
                rel = path.relative_to(base).as_posix()
                imported_tickets.append(import_ticket_file(ctx, con, at, path, rel))
                counts["tickets"] += 1
        for ledger, base in ledger_dirs:
            files = []
            if (ledger / "teams").is_dir():
                for folder in sorted(p for p in (ledger / "teams").iterdir() if p.is_dir() and not p.name.startswith("_")):
                    for path in folder.glob("*.md"):
                        doc_fm = split_document(path.read_text(encoding="utf-8"))["frontmatter"]
                        files.append((folder.name, str(doc_fm.get("id", "")).count("."), path))
            for team_key, _, path in sorted(files, key=lambda f: (f[0], f[1], f[2].name)):
                rel = path.relative_to(base).as_posix()
                imported_members.append(import_member_file(ctx, con, at, path, rel, team_key))
                counts["members"] += 1
        # second pass: leads, proposals, handoffs, then the prose the rows cannot regenerate
        for item in imported_tickets:
            t, fm = item["ticket"], item["fm"]
            lead = parse_link(fm.get("lead", "")) if fm.get("lead") else None
            if lead:
                lead_row = get_member(con, lead)
                if lead_row["ticket_id"] != t["id"]:
                    raise SpudError(EXIT_ERROR, "%s: lead %s is on another ticket" % (item["rel"], lead))
                con.execute("UPDATE tickets SET lead_id = ? WHERE id = ?", (lead_row["id"], t["id"]))
        for item in imported_tickets:
            item["derived"].update(link_proposal(con, at, item["ticket"], item["fm"]))
        for item in imported_tickets:
            sections = dict(item["sections"])
            if "Handoffs" in sections:
                item["derived"].update(import_handoffs(con, at, item["ticket"], sections["Handoffs"]))
            if "Team" in sections:
                item["derived"].update(import_team_summaries(con, item["ticket"], sections["Team"]))
        for item in imported_tickets:
            write_event(con, at, "import", "import", "imported %s" % item["rel"], ticket_id=item["ticket"]["id"],
                        data={"source": item["rel"], "derived": item["derived"]})
        for item in imported_tickets:
            t = get_ticket_by_id(con, item["ticket"]["id"])
            for name, text in item["sections"]:
                if name in TICKET_COLUMN_SECTIONS or name == "Team":  # generated from members; its suffixes gave the summaries
                    continue
                rendered = ticket_section_text(con, t, name)
                if store_prose_if_needed(con, "ticket", t["id"], name, text, rendered):
                    counts["prose_sections"] += 1
        for item in imported_members:
            m = get_member_by_id(con, item["member"]["id"])
            ticket = item["ticket"]
            for name, text in item["sections"]:
                if name in MEMBER_COLUMN_SECTIONS:
                    continue
                rendered = member_section_text(con, m, ticket, name)
                if store_prose_if_needed(con, "member", m["id"], name, text, rendered):
                    counts["prose_sections"] += 1
        for reports, base in report_dirs:
            for path in sorted(reports.glob("*.md")):
                if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", path.stem):
                    continue
                rel = path.relative_to(base).as_posix()
                day = path.stem
                if con.execute("SELECT 1 FROM events WHERE kind = 'report.entry' AND at LIKE ?", (day + "%",)).fetchone():
                    raise SpudError(EXIT_ERROR, "%s already has entries in the ledger (imported before)" % rel)
                entries = parse_report_entries(path.read_text(encoding="utf-8"))
                for time, title, body in entries:
                    write_event(con, "%sT%s" % (day, time), "import", "report.entry", body, data={"title": title, "source": rel})
                    counts["report_entries"] += 1
                write_event(con, at, "import", "import", "imported %s" % rel, data={"source": rel, "entries": len(entries)})
                counts["reports"] += 1
    return counts


def classify_path(ctx, path):
    """Which generated file a path is: ('ticket', KEY) | ('member', TEAM, NAME) | ('report', DAY), and its home-relative path."""
    path = Path(path).resolve()
    parts = path.parts
    try:
        rel = path.relative_to(ctx.home).as_posix()
    except ValueError:
        rel = None
    if len(parts) >= 3 and parts[-3] == "ledger" and parts[-2] == "tickets" and path.suffix == ".md":
        return ("ticket", path.stem), rel or "ledger/tickets/%s" % path.name
    if len(parts) >= 4 and parts[-4] == "ledger" and parts[-3] == "teams" and path.suffix == ".md":
        return ("member", parts[-2], path.stem), rel or "ledger/teams/%s/%s" % (parts[-2], path.name)
    if len(parts) >= 2 and parts[-2] == "reports" and re.fullmatch(r"\d{4}-\d{2}-\d{2}", path.stem):
        return ("report", path.stem), rel or "reports/%s" % path.name
    raise SpudError(EXIT_ERROR, "%s is not a generated ledger file (ledger/tickets/*.md, ledger/teams/*/*.md, reports/*.md)" % path)


def heading_tail(heading, title):
    """'SPD-003 — Protocol fixes' -> the tail; None when it equals the title."""
    if not heading:
        return None
    parts = heading.split(" — ", 1)
    tail = parts[1] if len(parts) == 2 else heading
    return None if tail == title else tail


def edited_keys(base, current):
    return [k for k in list(current.keys()) + [k for k in base if k not in current] if base.get(k) != current.get(k)]


def refuse(rel, message):
    raise SpudError(EXIT_ERROR, "%s: %s" % (rel, message))


def check_section_layout(rel, base, doc):
    base_names = [n for n, _ in base["sections"]]
    names = [n for n, _ in doc["sections"]]
    if names != base_names:
        missing = [n for n in base_names if n not in names]
        added = [n for n in names if n not in base_names]
        what = "; ".join(
            p for p in (
                ("deleted: " + ", ".join(missing)) if missing else "",
                ("added: " + ", ".join(added)) if added else "",
                "reordered" if not missing and not added else "",
            ) if p
        )
        refuse(rel, "the note's sections are fixed (empty a section rather than deleting it; %s)" % what)


TICKET_SECTION_COMMANDS = {
    "Team": "spud member new|start|finish",
    "Handoffs": "spud handoff add",
    "Proposals received": "spud proposal decide",
}
MEMBER_OWN_SECTIONS = {"Log": "spud member log", "Result": "spud member result", "Blocked": "spud member block"}
MEMBER_SECTION_COMMANDS = {"Sub-agents": "spud member new", "Ticket proposals": "spud proposal file"}


def accept_ticket_edit(ctx, con, at, t, base, doc, rel):
    """Accepted by hand: title, priority, tags, status (through the state machine),
    Brief, Size, Outcome.  Everything else is refused with the way to change it."""
    fm, base_fm = doc["frontmatter"], base["frontmatter"]
    keys = edited_keys(base_fm, fm)
    for key in keys:
        if key not in TICKET_FM_KEYS:
            refuse(rel, "property %r has no column; the ledger keeps only %s" % (key, ", ".join(TICKET_FM_KEYS)))
        if key in ("id", "origin", "proposed_by"):
            refuse(rel, "%s is not editable by hand" % key)
        if key == "lead":
            refuse(rel, "lead is not editable by hand; the first member planned with `spud member new` is the lead")
        if key == "created":
            refuse(rel, "created is not editable by hand; timestamps come from the clock")
    if list(fm.keys()) != list(base_fm.keys()):
        refuse(rel, "the order of the properties is generated; put them back as rendered")
    title_changed = "title" in keys
    if doc["heading"] != base["heading"] and not title_changed:
        refuse(rel, "the heading is generated from the title; use `spud ticket edit --heading`")
    check_section_layout(rel, base, doc)
    updates = {}
    if title_changed:
        updates["title"] = fm["title"]
        if doc["heading"] != base["heading"]:
            updates["heading"] = heading_tail(doc["heading"], fm["title"])
    if "priority" in keys:
        if fm.get("priority") not in PRIORITIES:
            refuse(rel, "priority %r is not one of %s" % (fm.get("priority"), ", ".join(PRIORITIES)))
        updates["priority"] = fm["priority"]
    if "tags" in keys:
        tags = fm["tags"] if isinstance(fm["tags"], list) else [fm["tags"]]
        updates["tags"] = json.dumps(tags)
    status_change = None
    if "status" in keys:
        if fm.get("status") not in TICKET_STATUSES:
            refuse(rel, "status %r is not one of %s" % (fm.get("status"), ", ".join(TICKET_STATUSES)))
        check_transition("tickets", t["status"], fm["status"], t["key"])
        status_change = (t["status"], fm["status"])
    base_sections = dict(base["sections"])
    for name, body in doc["sections"]:
        if base_sections[name] == body:
            continue
        if name in TICKET_COLUMN_SECTIONS:
            updates[TICKET_COLUMN_SECTIONS[name]] = body
        elif name in TICKET_SECTION_COMMANDS:
            refuse(rel, "## %s is generated from the ledger; it changes through `%s`" % (name, TICKET_SECTION_COMMANDS[name]))
        else:
            refuse(rel, "## %s is kept verbatim from markdown-v0; not editable by hand" % name)
    changed = list(updates)
    if status_change:
        updates["status"] = status_change[1]
        updates["closed_at"] = at if status_change[1] in ("done", "declined") else None
        changed.append("status")
    if updates:
        updates["updated_at"] = at
        con.execute("UPDATE tickets SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), t["id"]))
    if "priority" in updates:
        write_event(con, at, "eric", "ticket.priority", "%s %s -> %s (hand edit)" % (t["key"], t["priority"], updates["priority"]),
                    ticket_id=t["id"], data={"from": t["priority"], "to": updates["priority"]})
    if status_change:
        write_event(con, at, "eric", "ticket.status", "%s %s -> %s (hand edit)" % (t["key"], status_change[0], status_change[1]),
                    ticket_id=t["id"], data={"from": status_change[0], "to": status_change[1]})
    write_event(con, at, "eric", "import", "accepted hand edit of %s" % rel, ticket_id=t["id"], data={"source": rel, "accepted": True, "changed": changed})
    return changed


def accept_member_edit(ctx, con, at, m, ticket, base, doc, rel):
    """Accepted by hand: status (through the state machine), Brief, Outcome (parent-owned;
    Spud is every member's ancestor).  The member's own sections and everything
    the CLI derives are refused with the command that changes them."""
    fm, base_fm = doc["frontmatter"], base["frontmatter"]
    keys = edited_keys(base_fm, fm)
    for key in keys:
        if key == "model":
            refuse(rel, "model is not editable by hand; use `spud member edit --model` with `--tier-reason`")
        if key in ("spawned", "finished"):
            refuse(rel, "%s is not editable by hand; timestamps come from the clock" % key)
        if key in ("id", "name", "parent", "ticket", "persona", "agent_type", "tags"):
            refuse(rel, "%s is not editable by hand" % key)
        if key in ("duration_ms", "tool_uses"):
            refuse(rel, "%s is not editable by hand; the hooks record it, and `spud member resum` recomputes it" % key)
        if key in ("tokens_out", "tokens_in", "tokens_cached"):
            refuse(rel, "%s is not editable by hand; it is derived from the transcript sum the hooks record, and "
                        "`spud member resum` recomputes it" % key)
        if key == "cost_usd":
            refuse(rel, "cost_usd is not editable by hand; it is computed when the note renders, from the transcript sum's "
                        "per-model breakdown and the price table in spud.config.json")
        if key != "status":
            refuse(rel, "property %r has no column" % key)
    if list(fm.keys()) != list(base_fm.keys()):
        refuse(rel, "the order of the properties is generated; put them back as rendered")
    if doc["heading"] != base["heading"]:
        refuse(rel, "the heading is generated")
    check_section_layout(rel, base, doc)
    updates = {}
    base_sections = dict(base["sections"])
    for name, body in doc["sections"]:
        if base_sections[name] == body:
            continue
        if name in ("Brief", "Outcome"):
            updates[MEMBER_COLUMN_SECTIONS[name]] = body
        elif name in MEMBER_OWN_SECTIONS:
            refuse(rel, "## %s is the member's own; the member writes it through the CLI (`%s`)" % (name, MEMBER_OWN_SECTIONS[name]))
        elif name in MEMBER_SECTION_COMMANDS:
            refuse(rel, "## %s is generated from the ledger; it changes through `%s`" % (name, MEMBER_SECTION_COMMANDS[name]))
        else:
            refuse(rel, "## %s is kept verbatim from markdown-v0; not editable by hand" % name)
    changed = list(updates)
    if "status" in keys:
        if fm.get("status") not in MEMBER_STATUSES:
            refuse(rel, "status %r is not one of %s" % (fm.get("status"), ", ".join(MEMBER_STATUSES)))
        member_status_change(con, at, "eric", m, fm["status"], updates)
        changed.append("status")
    elif updates:
        con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), m["id"]))
    write_event(con, at, "eric", "import", "accepted hand edit of %s" % rel, ticket_id=ticket["id"], member_id=m["id"], data={"source": rel, "accepted": True, "changed": changed})
    return changed


def accept_report_edit(con, at, day, text, rel):
    """An appended entry is accepted; a changed or deleted entry is refused: report
    entries are append-only events."""
    entries = parse_report_entries(text)
    existing = con.execute("SELECT at, body, data FROM events WHERE kind = 'report.entry' AND at LIKE ? ORDER BY id", (day + "%",)).fetchall()
    have = {}
    for e in existing:
        title = (json.loads(e["data"]) if e["data"] else {}).get("title", "")
        have.setdefault((e["at"][11:16], title), []).append(normalize_markdown(e["body"]))
    seen = {}
    for time, title, body in entries:
        seen[(time, title)] = seen.get((time, title), 0) + 1
    for key, bodies in have.items():
        if seen.get(key, 0) < len(bodies):
            refuse(rel, "the entry '%s — %s' was deleted; report entries are append-only events (`spud render --discard` restores the file)" % key)
    added = 0
    for time, title, body in entries:
        bodies = have.get((time, title))
        if bodies is None:
            write_event(con, "%sT%s" % (day, time), "eric", "report.entry", body, data={"title": title, "source": rel})
            added += 1
        elif normalize_markdown(body) not in bodies:
            refuse(rel, "the entry '%s — %s' changed; report entries are append-only events" % (time, title))
    changed = ["entries:%d" % added]
    write_event(con, at, "eric", "import", "accepted hand edit of %s" % rel, data={"source": rel, "accepted": True, "changed": changed})
    return changed


def accept_file(ctx, con, actor, path):
    """import --file: accept a hand edit of a rendered file.  The edit is the
    difference between the file and what the renderer last wrote (renders.content;
    the current render when the file was never rendered); fields the file leaves
    as rendered do not overwrite changes the CLI made since."""
    path = Path(path).resolve()
    if not path.is_file():
        raise SpudError(EXIT_ERROR, "no such file: %s" % path)
    kind, rel = classify_path(ctx, path)
    raw = path.read_bytes()
    text = raw.decode("utf-8")
    at = now()
    with write_txn(con):
        record = con.execute("SELECT content FROM renders WHERE path = ?", (rel,)).fetchone()
        baseline = record["content"] if record and record["content"] else None
        if kind[0] == "ticket":
            t = get_ticket(con, kind[1])
            base = split_document(baseline or render_ticket(con, t, ctx.pricing))
            doc = split_document(text)
            if doc["frontmatter"].get("id") != t["key"]:
                raise SpudError(EXIT_ERROR, "%s: id is not editable by hand" % rel)
            changed = accept_ticket_edit(ctx, con, at, t, base, doc, rel)
        elif kind[0] == "member":
            m = get_member(con, "%s/%s" % (kind[1], kind[2]))
            ticket = get_ticket_by_id(con, m["ticket_id"])
            base = split_document(baseline or render_member(con, m, ctx.pricing))
            doc = split_document(text)
            fm = doc["frontmatter"]
            expected_parent = "Spud" if m["parent_id"] is None else member_ref(con, m["parent_id"])
            parent_link = parse_link(fm["parent"]) if fm.get("parent") else None
            if fm.get("id") != m["lineage"] or fm.get("name") != m["name"] or parent_link != expected_parent or parse_link(fm.get("ticket") or "") != ticket["key"]:
                raise SpudError(EXIT_ERROR, "%s: id, name, parent and ticket are not editable by hand" % rel)
            changed = accept_member_edit(ctx, con, at, m, ticket, base, doc, rel)
        else:
            changed = accept_report_edit(con, at, kind[1], text, rel)
        con.execute(
            "INSERT INTO renders (path, sha256, content, rendered_at, through_event_id) VALUES (?, ?, ?, ?, (SELECT COALESCE(MAX(id), 0) FROM events))"
            " ON CONFLICT(path) DO UPDATE SET sha256 = excluded.sha256, content = excluded.content, rendered_at = excluded.rendered_at, through_event_id = excluded.through_event_id",
            (rel, sha256_bytes(raw), text, at),
        )
    return {"path": rel, "changed": changed}


# ----------------------------------------------------------------------------
# Commands
# ----------------------------------------------------------------------------


class Result:
    """A command's answer.  `raw` (hooks) is printed verbatim on stdout with the given
    exit code, whatever --json says; everything else prints `text` or `data` as JSON, then
    `stderr` as a `spud:` line, and exits with `exit_code` (member resum: 1 with its table)."""

    def __init__(self, data, text="", raw=None, exit_code=EXIT_OK, stderr=""):
        self.data = data
        self.text = text
        self.raw = raw
        self.exit_code = exit_code
        self.stderr = stderr


def table(rows, columns):
    """A plain text table: columns is [(header, key)]."""
    if not rows:
        return "(none)"
    widths = [max(len(h), *(len(str(r.get(k, "") if r.get(k) is not None else "")) for r in rows)) for h, k in columns]
    lines = ["  ".join(h.ljust(w) for (h, _), w in zip(columns, widths)).rstrip()]
    for r in rows:
        lines.append("  ".join(str(r.get(k, "") if r.get(k) is not None else "").ljust(w) for (_, k), w in zip(columns, widths)).rstrip())
    return "\n".join(lines)


def cmd_init(ctx, args):
    created = not ctx.db_path.exists()
    ctx.config  # the config must exist before a ledger is created
    ctx.db_path.parent.mkdir(parents=True, exist_ok=True)
    con = open_connection(ctx.db_path)
    try:
        if created:
            con.execute("PRAGMA journal_mode = WAL")
        applied, backups = apply_migrations(ctx, con, created)
        at = now()
        with write_txn(con):
            sync_config_rows(ctx, con, at)
        version = con.execute("PRAGMA user_version").fetchone()[0]
    finally:
        con.close()
    data = {"database": str(ctx.db_path), "created": created, "user_version": version, "applied": applied, "backups": backups}
    if created:
        text = "created %s (user_version %d)" % (ctx.db_path, version)
    elif applied:
        text = "migrated %s to user_version %d (%s)" % (ctx.db_path, version, ", ".join(applied))
    else:
        text = "%s is up to date (user_version %d)" % (ctx.db_path, version)
    return Result(data, text)


def cmd_migrate(ctx, args):
    if not ctx.db_path.is_file():
        raise SpudError(EXIT_ERROR, "no ledger at %s; run `spud init`" % ctx.db_path)
    con = open_connection(ctx.db_path)
    try:
        applied, backups = apply_migrations(ctx, con, False)
        version = con.execute("PRAGMA user_version").fetchone()[0]
    finally:
        con.close()
    text = ("migrated to user_version %d (%s)" % (version, ", ".join(applied))) if applied else ("up to date (user_version %d)" % version)
    return Result({"database": str(ctx.db_path), "user_version": version, "applied": applied, "backups": backups}, text)


def cmd_backup(ctx, args):
    if args.keep is not None and not args.daily:
        raise SpudError(EXIT_USAGE, "--keep is how many daily copies `spud backup --daily` keeps; plain `spud backup` prunes nothing")
    keep = DAILY_KEEP if args.keep is None else args.keep
    if args.daily and keep < 1:
        raise SpudError(EXIT_USAGE, "backup --daily keeps at least one daily copy (--keep %d)" % keep)
    con = connect(ctx)
    try:
        if args.daily:
            return daily_backup(ctx, con, keep)
        path = do_backup(ctx, con)
    finally:
        con.close()
    return Result({"path": str(path)}, "backup written to %s" % path)


def daily_backup(ctx, con, keep):
    """backup --daily: today's copy unless one exists, quick_check-ed, then the newest `keep` daily copies kept.
    Nothing is pruned unless this run wrote a copy that checked ok."""
    directory = backups_dir(ctx)
    stamp = backup_stamp()
    daily, _ = backup_listing(directory)
    today = [name for name in daily if name.startswith("ledger-%sT" % stamp[:8])]
    if today:
        path = directory / today[-1]
        return Result({"path": str(path), "written": False, "pruned": [], "kept": len(daily)},
                      "today's daily backup already exists: %s\nnothing written, nothing pruned; %d daily %s kept"
                      % (path, len(daily), "copy" if len(daily) == 1 else "copies"))
    target = directory / ("ledger-%s-%s.db" % (stamp, DAILY_LABEL))
    not_written = {"path": str(target), "written": False, "pruned": [], "kept": len(daily)}
    in_the_way = os.path.lexists(target)
    try:
        path = do_backup(ctx, con, DAILY_LABEL, stamp=stamp)
    except BaseException as e:
        # A write that failed part way can leave a partial copy behind: remove it, when this run made it.
        if not in_the_way and target.is_file() and not target.is_symlink():
            with contextlib.suppress(OSError):
                target.unlink()
        if isinstance(e, (SpudError, sqlite3.Error, OSError)):
            raise SpudError(EXIT_ERROR, "daily backup %s not written, nothing pruned: %s" % (target, e.message if isinstance(e, SpudError) else e),
                            data=not_written)
        raise
    check = backup_quick_check(path)
    if check != ["ok"]:
        try:
            path.unlink()
            removed = "the copy was removed"
        except FileNotFoundError:
            removed = "the copy is gone"
        except OSError as e:
            removed = "the copy could not be removed (%s)" % e
        raise SpudError(EXIT_ERROR, "quick_check of the daily backup %s did not return ok (%s); %s, nothing pruned" % (path, "; ".join(check)[:1000], removed),
                        data=dict(not_written, quick_check=check))
    pruned = []
    try:
        kept = prune_daily_backups(directory, keep, path.name, pruned)
    except OSError as e:
        raise SpudError(EXIT_ERROR, "daily backup written to %s (quick_check ok), but the prune stopped: %s" % (path, e),
                        data={"path": str(path), "written": True, "pruned": pruned, "kept": len(backup_listing(directory)[0])})
    text = "daily backup written to %s (quick_check ok)\npruned %d daily %s%s; %d kept" % (
        path, len(pruned), "copy" if len(pruned) == 1 else "copies", (": " + ", ".join(pruned)) if pruned else "", kept)
    return Result({"path": str(path), "written": True, "pruned": pruned, "kept": kept}, text)


# schedule (SPD-012): the macOS LaunchAgent that runs `spud backup --daily`.  Eric chose launchd over a Claude
# scheduled task: the CLI runs alone, with the app closed, and a run missed during sleep fires at wake.
SCHEDULE_LABEL = "local.spud.backup"
SCHEDULE_AT = "03:00"
SCHEDULE_LOG = "~/Library/Logs/spud-backup.log"
# Seconds slept before each bootstrap retry: launchd can refuse a bootstrap while the job it has just booted
# out is still going away, so five attempts over about two seconds.
BOOTSTRAP_RETRY_DELAYS = (0.25, 0.5, 0.5, 0.75)


def at_arg(value):
    """--at HH:MM, local time from 00:00 to 23:59: (hour, minute)."""
    m = re.fullmatch(r"([01]?[0-9]|2[0-3]):([0-5][0-9])", value)
    if not m:
        raise argparse.ArgumentTypeError("expected HH:MM from 00:00 to 23:59, got %r" % value)
    return int(m.group(1)), int(m.group(2))


def require_spud_flag(args, what):
    """A Spud-only command that reads and writes no ledger row: --as must name Spud himself."""
    if args.actor is None:
        raise SpudError(EXIT_ERROR, "`%s` is Spud's and needs --as spud" % what)
    if args.actor != "spud":
        raise SpudError(EXIT_OWNERSHIP, "`%s` is Spud's; %s may not (use --as spud)" % (what, args.actor))


def schedule_plist_path():
    """$SPUD_LAUNCH_AGENTS_DIR/local.spud.backup.plist, default ~/Library/LaunchAgents."""
    agents = os.environ.get("SPUD_LAUNCH_AGENTS_DIR") or "~/Library/LaunchAgents"
    return Path(os.path.abspath(os.path.expanduser(agents))) / (SCHEDULE_LABEL + ".plist")


def schedule_plist(ctx, at):
    """The LaunchAgent as a dict: the home's bin/spud (never a worktree's copy) run by this interpreter as
    given, symlinks unresolved so a Homebrew upgrade keeps the path valid; SPUD_HOME set, because launchd's
    environment is minimal; at load and daily at `at` (hour, minute)."""
    if not sys.executable:
        raise SpudError(EXIT_ERROR, "cannot tell which Python runs spud: sys.executable is empty")
    log = os.path.abspath(os.path.expanduser(SCHEDULE_LOG))
    return {
        "Label": SCHEDULE_LABEL,
        "ProgramArguments": [sys.executable, "-I", "-S", str(ctx.home / "bin" / "spud"), "--as", "spud", "backup", "--daily"],
        "EnvironmentVariables": {"SPUD_HOME": str(ctx.home)},
        "RunAtLoad": True,
        "StartCalendarInterval": {"Hour": at[0], "Minute": at[1]},
        "StandardOutPath": log,
        "StandardErrorPath": log,
        "ProcessType": "Background",
    }


def launchctl(*args):
    """Run launchctl ($SPUD_LAUNCHCTL, default /bin/launchctl): (exit code, stdout, stderr)."""
    exe = os.environ.get("SPUD_LAUNCHCTL") or "/bin/launchctl"
    try:
        proc = subprocess.run([exe, *args], capture_output=True, text=True, errors="replace", timeout=60)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise SpudError(EXIT_ERROR, "cannot run %s %s: %s" % (exe, " ".join(args), e))
    return proc.returncode, proc.stdout, proc.stderr


def write_plist(path, data):
    """Write through a temporary file in the same directory, then os.replace; mode 0644."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix="." + path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp)
        raise


def cmd_schedule_show(ctx, args):
    require_spud_flag(args, "spud schedule show")
    import plistlib  # imported here, not at the top: the hooks run on every tool call and never need it

    plist = schedule_plist(ctx, args.at)
    xml = plistlib.dumps(plist).decode("utf-8")
    path = schedule_plist_path()
    exists = path.is_file()
    matches = False
    if exists:
        try:
            matches = plistlib.loads(path.read_bytes()) == plist
        except Exception:  # unreadable, or not a plist: it does not match
            matches = False
    service = "gui/%d/%s" % (os.getuid(), SCHEDULE_LABEL)
    loaded = launchctl("print", service)[0] == 0
    at = "%02d:%02d" % args.at
    data = {"label": SCHEDULE_LABEL, "path": str(path), "at": at, "exists": exists, "matches": matches, "loaded": loaded, "plist": xml}
    state = ("installed, matches" if matches else "installed, differs from the plist below") if exists else "not installed"
    lines = [
        "label       %s" % SCHEDULE_LABEL,
        "plist       %s (%s)" % (path, state),
        "loaded      %s (launchctl print %s)" % ("yes" if loaded else "no", service),
        "runs        %s" % shlex.join(plist["ProgramArguments"]),
        "when        at load, and daily at %s (a run missed during sleep fires at wake)" % at,
        "log         %s" % plist["StandardOutPath"],
        "",
        xml.rstrip("\n"),
    ]
    return Result(data, "\n".join(lines))


def cmd_schedule_install(ctx, args):
    require_spud_flag(args, "spud schedule install")
    import plistlib  # see cmd_schedule_show

    plist = schedule_plist(ctx, args.at)
    path = schedule_plist_path()
    at = "%02d:%02d" % args.at
    replaced = os.path.lexists(path)
    try:
        write_plist(path, plistlib.dumps(plist))
    except OSError as e:
        raise SpudError(EXIT_ERROR, "cannot write %s: %s" % (path, e))
    domain = "gui/%d" % os.getuid()
    service = "%s/%s" % (domain, SCHEDULE_LABEL)
    booted_out = launchctl("bootout", service)[0] == 0  # a job that was not loaded is fine
    attempts = 0
    for delay in (0,) + BOOTSTRAP_RETRY_DELAYS:
        if delay:
            time.sleep(delay)
        attempts += 1
        code, stdout, stderr = launchctl("bootstrap", domain, str(path))
        if code == 0:
            break
    else:
        said = (stderr or stdout).strip() or "no output"
        raise SpudError(EXIT_ERROR, "launchctl bootstrap %s %s failed %d times, the last with exit %d: %s; the plist stays at %s (spud schedule uninstall removes it)"
                        % (domain, path, attempts, code, said, path),
                        data={"label": SCHEDULE_LABEL, "path": str(path), "at": at, "replaced": replaced, "booted_out": booted_out, "attempts": attempts, "stderr": stderr})
    data = {"label": SCHEDULE_LABEL, "path": str(path), "at": at, "replaced": replaced, "booted_out": booted_out, "attempts": attempts}
    lines = [
        "wrote %s%s" % (path, " (replacing the plist that was there)" if replaced else ""),
        "launchctl bootout %s: %s" % (service, "booted out the loaded job" if booted_out else "no job was loaded"),
        "launchctl bootstrap %s %s: loaded%s" % (domain, path, "" if attempts == 1 else " on attempt %d" % attempts),
        "%s runs `spud backup --daily` at load and daily at %s; its output goes to %s" % (SCHEDULE_LABEL, at, plist["StandardOutPath"]),
    ]
    return Result(data, "\n".join(lines))


def cmd_schedule_uninstall(ctx, args):
    require_spud_flag(args, "spud schedule uninstall")
    path = schedule_plist_path()
    service = "gui/%d/%s" % (os.getuid(), SCHEDULE_LABEL)
    booted_out = launchctl("bootout", service)[0] == 0  # a job that was not loaded is fine
    removed = False
    if os.path.lexists(path):
        try:
            path.unlink()
        except OSError as e:
            raise SpudError(EXIT_ERROR, "cannot remove %s: %s" % (path, e), data={"label": SCHEDULE_LABEL, "path": str(path), "booted_out": booted_out, "removed": False})
        removed = True
    data = {"label": SCHEDULE_LABEL, "path": str(path), "booted_out": booted_out, "removed": removed}
    if not booted_out and not removed:
        return Result(data, "%s is not installed: no plist at %s and no job loaded (launchctl bootout %s); nothing to do" % (SCHEDULE_LABEL, path, service))
    return Result(data, "launchctl bootout %s: %s\n%s" % (
        service, "booted out the loaded job" if booted_out else "no job was loaded", ("removed %s" % path) if removed else ("no plist at %s" % path)))


def cmd_config_sync(ctx, args):
    con = connect(ctx)
    try:
        at = now()
        with write_txn(con):
            synced = sync_config_rows(ctx, con, at)
            write_event(con, at, "spud", "config.synced", "config synced", data=synced)
    finally:
        con.close()
    return Result({"project": {"ticket_prefix": synced["ticket_prefix"], "team_prefix": synced["team_prefix"]}, "pool": synced["pool"]},
                  "name_pool: %d names; home project prefixes %s / %s" % (synced["pool"], synced["ticket_prefix"], synced["team_prefix"]))


# The hook table of the spike's Enforcement plan (SPD-006), installed by `spud settings sync`.
HOOK_TABLE = (
    ("PreToolUse", "Agent"),
    ("PreToolUse", "Bash"),
    ("PreToolUse", "Write|Edit|MultiEdit|NotebookEdit"),
    ("PostToolUse", "Agent"),
    ("SubagentStart", None),
    ("SubagentStop", None),
    ("SessionStart", "startup|resume|clear|compact"),  # clear since SPD-011: a /clear gets the board too
    ("Stop", None),
)
HOOK_TIMEOUT = 30  # seconds; a hook is one Python start and one short transaction (busy_timeout 5 s)
HOOK_MARK = "bin/spud hook"  # what marks a hook entry as the ledger's, whatever home it was generated for
ALLOW_RULE_MARK = re.compile(r"^Bash\(.*bin/spud(?: \*|:\*)\)$")


def hook_command(ctx, event):
    """`SPUD_HOME=<home> <interpreter> -I -S <home>/bin/spud hook <event>`, absolute, resolved at sync time."""
    home = str(ctx.home)
    return "SPUD_HOME=%s %s -I -S %s hook %s" % (shlex.quote(home), shlex.quote(sys.executable), shlex.quote(str(ctx.home / "bin" / "spud")), event)


def cli_allow_rules(ctx):
    """The permission rules for the CLI in the forms spudagents type: the documented
    interpreter name, the absolute interpreter, and the script alone (#! line)."""
    script = str(ctx.home / "bin" / "spud")
    rules = ["Bash(python3.14 -I -S %s *)" % script, "Bash(%s -I -S %s *)" % (sys.executable, script), "Bash(%s *)" % script]
    out = []
    for r in rules:
        if r not in out:
            out.append(r)
    return out


def is_ledger_hook(entry):
    return isinstance(entry, dict) and HOOK_MARK in str(entry.get("command", ""))


def merge_hooks(ctx, settings):
    """Keep every hook that is not the ledger's, replace the ledger's own entries, one
    group per row of the hook table, appended in table order."""
    hooks = settings.get("hooks")
    if not isinstance(hooks, dict):
        hooks = {}
        settings["hooks"] = hooks
    for event in dict.fromkeys(e for e, _ in HOOK_TABLE):
        kept = []
        groups = hooks.get(event)
        for group in (groups if isinstance(groups, list) else []):
            if not isinstance(group, dict) or not isinstance(group.get("hooks"), list):
                continue  # malformed in, nothing out (Rooster's LOW-6)
            entries = [h for h in group["hooks"] if isinstance(h, dict) and isinstance(h.get("command", ""), str) and not is_ledger_hook(h)]
            if entries:
                g2 = dict(group)
                g2["hooks"] = entries
                kept.append(g2)
        for ev, matcher in HOOK_TABLE:
            if ev != event:
                continue
            entry = {"type": "command", "command": hook_command(ctx, event), "timeout": HOOK_TIMEOUT}
            kept.append({"matcher": matcher, "hooks": [entry]} if matcher else {"hooks": [entry]})
        hooks[event] = kept
    return sum(len(v) for e, v in hooks.items() if e in dict(HOOK_TABLE))


def merge_allow_rules(ctx, settings):
    permissions = settings.get("permissions")
    if not isinstance(permissions, dict):
        permissions = {}
        settings["permissions"] = permissions
    allow = permissions.get("allow")
    if not isinstance(allow, list):
        allow = []
    allow = [a for a in allow if isinstance(a, str) and not ALLOW_RULE_MARK.match(a)]
    for rule in cli_allow_rules(ctx):
        if rule not in allow:
            allow.append(rule)
    permissions["allow"] = allow
    return allow


# Law 3 in the permission system itself (SPD-016), so it holds when the PreToolUse(Agent) hook is removed or does not
# run.  These are the parameter rules of the Claude Code permissions docs ("Match by input parameter": Tool(param:value),
# deny and ask rules only, `*` a wildcard): any explicit isolation, and the inherit model.  A parameter rule never
# matches a parameter the call leaves out, so a spawn without `model` is still the hook's to refuse.
AGENT_DENY_RULES = ("Agent(isolation:*)", "Agent(model:inherit)")


def merge_deny_rules(settings):
    """Keep every other deny rule where it is, drop non-strings and repeats of ours, append ours when missing."""
    permissions = settings.get("permissions")
    if not isinstance(permissions, dict):
        permissions = {}
        settings["permissions"] = permissions
    deny = permissions.get("deny")
    kept = []
    for rule in (deny if isinstance(deny, list) else []):
        if isinstance(rule, str) and not (rule in AGENT_DENY_RULES and rule in kept):
            kept.append(rule)
    for rule in AGENT_DENY_RULES:
        if rule not in kept:
            kept.append(rule)
    permissions["deny"] = kept
    return kept


def cmd_settings_sync(ctx, args):
    limits = ctx.limits
    path = Path(args.path).expanduser().resolve() if args.path else (ctx.home / ".claude" / "settings.json")
    if path.is_file():
        try:
            settings = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            raise SpudError(EXIT_ERROR, "%s is not valid JSON: %s" % (path, e))
        if not isinstance(settings, dict):
            raise SpudError(EXIT_ERROR, "%s is not a JSON object" % path)
    else:
        settings = {}
    env = settings.get("env")
    if not isinstance(env, dict):
        env = {}
        settings["env"] = env
    env["CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH"] = str(limits["max_depth"])
    env["CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS"] = str(limits["max_concurrent_total"])
    allow = merge_allow_rules(ctx, settings)
    deny = merge_deny_rules(settings)
    hook_count = merge_hooks(ctx, settings)
    rendered = json.dumps(settings, indent=2) + "\n"
    current = path.read_text(encoding="utf-8") if path.is_file() else None
    written = False
    if not args.dry_run and rendered != current:
        write_whole(path, rendered)
        written = True
    if not args.dry_run and ctx.db_path.is_file():
        con = connect(ctx)
        try:
            at = now()
            with write_txn(con):
                write_event(con, at, "spud", "config.synced", "settings synced to %s (%s)" % (path, "written" if written else "unchanged"),
                            data={"path": str(path), "written": written, "env": dict(env), "hooks": hook_count, "allow": allow, "deny": deny})
        finally:
            con.close()
    text = "%s%s\n%s" % (path, " (dry run)" if args.dry_run else (" written" if written else " unchanged"), rendered.rstrip("\n"))
    return Result({"path": str(path), "written": written, "dry_run": bool(args.dry_run), "settings": settings, "hooks": hook_count}, text)


READ_ONLY_FIRST_WORDS = ("SELECT", "WITH", "VALUES", "EXPLAIN", "PRAGMA")


def cmd_sql(ctx, args):
    """spud sql --readonly '<statement>': one read statement against the database opened
    read-only (mode=ro, query_only); any actor, no writes possible."""
    if not args.readonly:
        raise SpudError(EXIT_USAGE, "spud sql runs read-only statements only; the syntax is: spud sql --readonly '<statement>'")
    if not ctx.db_path.is_file():
        raise SpudError(EXIT_ERROR, "no ledger at %s; run `spud init`" % ctx.db_path)
    statement = args.statement.strip().rstrip(";").strip()
    first = (re.match(r"[A-Za-z]+", statement) or re.match(r"", statement)).group(0).upper()
    if first not in READ_ONLY_FIRST_WORDS or (first == "PRAGMA" and "=" in statement):
        raise SpudError(EXIT_ERROR, "sql: only SELECT, WITH, VALUES, EXPLAIN and read-only PRAGMA statements run here; the syntax is: spud sql --readonly '<statement>' (got %r)" % statement[:60])
    uri = "file:%s?mode=ro" % str(ctx.db_path).replace("%", "%25").replace("?", "%3F").replace("#", "%23")
    try:
        con = sqlite3.connect(uri, uri=True, timeout=5.0, autocommit=True)
    except sqlite3.Error as e:
        raise SpudError(EXIT_ERROR, "sql: cannot open %s read-only: %s" % (ctx.db_path, e))
    try:
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA query_only = ON")
        con.execute("PRAGMA busy_timeout = 5000")
        try:
            cur = con.execute(statement)
            rows = [dict(r) for r in cur.fetchall()]
            columns = [d[0] for d in cur.description] if cur.description else []
        except (sqlite3.Error, sqlite3.Warning) as e:
            raise SpudError(EXIT_ERROR, "sql: %s" % e)
    finally:
        con.close()
    for r in rows:
        for k, v in r.items():
            if isinstance(v, bytes):
                r[k] = v.hex()
    text = table(rows, [(c, c) for c in columns]) if columns else "(no columns)"
    return Result({"columns": columns, "rows": rows, "count": len(rows)}, text)


def cmd_import(ctx, args):
    con = connect(ctx)
    try:
        if args.file:
            if args.paths:
                raise SpudError(EXIT_USAGE, "--file takes one file; directories are the bulk import")
            actor = resolve_actor(con, args.actor)
            require_spud(con, actor, "accepting a hand edit")
            out = accept_file(ctx, con, actor, args.file)
            return Result(out, "accepted %s (%s)" % (out["path"], ", ".join(out["changed"]) or "no changes"))
        paths = args.paths or [str(ctx.home)]
        counts = bulk_import(ctx, con, paths)
    finally:
        con.close()
    return Result(counts, "imported %d tickets, %d members, %d report files (%d entries); %d sections kept as prose"
                  % (counts["tickets"], counts["members"], counts["reports"], counts["report_entries"], counts["prose_sections"]))


def cmd_render(ctx, args):
    con = connect(ctx)
    try:
        out_root = Path(args.out).expanduser().resolve() if args.out else ctx.home
        targets = render_targets(con, ctx.pricing)
        written, unchanged, conflicts, discarded = [], [], [], []
        if args.discard:
            if args.out:
                raise SpudError(EXIT_USAGE, "--discard applies to the files under SPUD_HOME, not to --out")
            actor = resolve_actor(con, args.actor)
            require_spud(con, actor, "discarding a hand edit")
            kind, rel = classify_path(ctx, args.discard)
            path = ctx.home / rel
            content = dict(targets).get(rel)
            if content is None:
                raise SpudError(EXIT_ERROR, "%s is not a file this ledger generates" % rel)
            if not path.is_file():
                raise SpudError(EXIT_ERROR, "no such file: %s" % path)
            old_text = path.read_text(encoding="utf-8")
            write_whole(path, content)
            discarded.append(rel)
            at = now()
            with write_txn(con):
                con.execute(
                    "INSERT INTO renders (path, sha256, content, rendered_at, through_event_id) VALUES (?, ?, ?, ?, (SELECT COALESCE(MAX(id), 0) FROM events))"
                    " ON CONFLICT(path) DO UPDATE SET sha256 = excluded.sha256, content = excluded.content, rendered_at = excluded.rendered_at, through_event_id = excluded.through_event_id",
                    (rel, sha256_bytes(content.encode("utf-8")), content, at),
                )
                write_event(con, at, actor.label, "render", "discarded the hand edit of %s" % rel, data={"discarded": True, "path": rel, "text": old_text})
        records = {r["path"]: r["sha256"] for r in con.execute("SELECT path, sha256 FROM renders").fetchall()} if not args.out else {}
        to_record = []
        restyled, unreadable = [], {}  # [(path, the text the render went over)], {path: why it could not be read}
        for rel, content in targets:
            path = out_root / rel
            data = content.encode("utf-8")
            new_hash = sha256_bytes(data)
            raw = path.read_bytes() if path.is_file() else None
            on_disk = sha256_bytes(raw) if raw is not None else None
            if not args.out:
                recorded = records.get(rel)
                if recorded is not None and on_disk is not None and on_disk not in (recorded, new_hash):
                    # Neither the last render nor the new one, byte for byte.  A note may still be one
                    # of them with its frontmatter restyled (Obsidian rewrites the YAML of the notes it
                    # has open): that is no hand edit, so the render goes over it and the event keeps
                    # what it replaced.  A report has no frontmatter: any change to it is the conflict.
                    style_only, why = False, None
                    if content.startswith("---\n"):
                        last = con.execute("SELECT content FROM renders WHERE path = ?", (rel,)).fetchone()["content"]
                        style_only, why = restyled_render(raw, (last, content))
                    if not style_only:
                        conflicts.append(rel)
                        if why:
                            unreadable[rel] = why
                        continue
                    restyled.append((rel, raw.decode("utf-8")))
                if on_disk == new_hash:
                    unchanged.append(rel)
                    if recorded != new_hash:
                        to_record.append((rel, new_hash, content))
                    continue
                write_whole(path, content)
                written.append(rel)
                to_record.append((rel, new_hash, content))
            else:
                if on_disk == new_hash:
                    unchanged.append(rel)
                else:
                    write_whole(path, content)
                    written.append(rel)
        if not args.out:
            at = now()
            with write_txn(con):
                through = con.execute("SELECT COALESCE(MAX(id), 0) FROM events").fetchone()[0]
                for rel, new_hash, content in to_record:
                    con.execute(
                        "INSERT INTO renders (path, sha256, content, rendered_at, through_event_id) VALUES (?, ?, ?, ?, ?)"
                        " ON CONFLICT(path) DO UPDATE SET sha256 = excluded.sha256, content = excluded.content,"
                        " rendered_at = excluded.rendered_at, through_event_id = excluded.through_event_id",
                        (rel, new_hash, content, at, through),
                    )
                for rel, text in restyled:
                    write_event(con, at, "spud", "render", "re-rendered %s over a style-only frontmatter rewrite" % rel,
                                data={"style_only": True, "path": rel, "text": text})
                for rel in conflicts:
                    conflict = {"conflict": True, "path": rel}
                    if rel in unreadable:
                        conflict["unreadable"] = unreadable[rel]
                    write_event(con, at, "spud", "render", "refused to overwrite hand-edited %s" % rel, data=conflict)
                write_event(con, at, "spud", "render", "rendered %d files, %d unchanged, %d conflicts" % (len(written), len(unchanged), len(conflicts)),
                            data={"written": written, "unchanged": len(unchanged), "conflicts": conflicts,
                                  "restyled": [rel for rel, _ in restyled], "through_event_id": through})
    finally:
        con.close()
    data = {"out": str(out_root), "written": written, "unchanged": unchanged, "conflicts": conflicts, "discarded": discarded,
            "restyled": [rel for rel, _ in restyled]}
    lines = ["rendered into %s: %d written, %d unchanged%s%s" % (
        out_root, len(written), len(unchanged),
        (", %d hand edit discarded" % len(discarded)) if discarded else "",
        (", %d style-only rewrite re-rendered" % len(restyled)) if restyled else "",
    )]
    lines += ["  discarded the hand edit of %s" % rel for rel in discarded]
    lines += ["  re-rendered %s over a style-only frontmatter rewrite" % rel for rel, _ in restyled]
    lines += ["  wrote %s" % rel for rel in written]
    if conflicts:
        raise SpudError(
            EXIT_CONFLICT,
            "hand-edited, not overwritten (accept with `spud import --file <path>`): " + ", ".join(conflicts),
            data=data,
        )
    return Result(data, "\n".join(lines))


# Report entries (SPD-011).  Spud's recording commands write their own report.entry in the transaction of
# the record they make: ticket new, ticket move, ticket edit when --priority changes the priority, member
# finish of a root member, and proposal decide.  The title is generated and the body is `- ` lines; Spud
# types only the Next line, with --next.  `report add` stays for what no command records (a merge, an install).
TICKET_MOVE_VERBS = {"active": "started", "done": "done", "queued": "queued", "declined": "declined"}


def check_next(con, actor, args):
    """--next on a command that writes a report entry: Spud's alone (exit 3), and never empty (exit 2).
    Checked before anything is written; a command that turns out to write no entry refuses --next itself."""
    if args.next is None:
        return
    require_spud(con, actor, "the Next line of a report entry (--next)")
    if not args.next.strip():
        raise SpudError(EXIT_USAGE, "--next is empty: give the Next line, or leave --next out")


def no_entry_for_next(why):
    """The usage error of --next given to a command that writes no report entry; raised before it writes."""
    return SpudError(EXIT_USAGE, "--next has no report entry to go on: %s (leave --next out, or use `spud report add`)" % why)


def write_report_entry(con, at, title, generated, ticket_id, member_id=None, lines=(), next_line=None):
    """A generated report.entry, Spud's, in the caller's transaction: its body is `- ` lines, the Next line last."""
    body = "\n".join(["- " + line for line in lines] + ([] if next_line is None else ["- Next: " + next_line]))
    event_id = write_event(con, at, "spud", "report.entry", body, ticket_id=ticket_id, member_id=member_id,
                           data={"title": title, "generated": generated})
    return {"id": event_id, "at": at, "title": title, "body": body}


def report_entry_line(entry):
    """The line `report add` prints, and every command that writes an entry prints after its own."""
    return "report entry %s — %s added to reports/%s.md" % (entry["at"][11:16], entry["title"], entry["at"][:10])


def with_report_entry(data, text, entry):
    """A command's Result with the report entry it wrote, if it wrote one: `report_entry` in --json, its line in the text."""
    if entry is None:
        return Result(data, text)
    return Result(dict(data, report_entry=entry), text + "\n" + report_entry_line(entry))


def cmd_ticket_new(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_spud(con, actor, "creating a ticket (Law 6)")
        check_next(con, actor, args)
        project = con.execute("SELECT * FROM projects WHERE key = ?", (args.project or "spud",)).fetchone()
        if project is None:
            raise SpudError(EXIT_ERROR, "no project %r" % args.project)
        tags = ["ticket"] + [t for t in (args.tag or []) if t != "ticket"]
        at = now()
        with write_txn(con):
            t = insert_ticket(con, at, actor.label, project, args.title, args.priority, args.status,
                              brief=args.brief or "", sizing=args.sizing or "", outcome=args.outcome or "", tags=tags, heading=args.heading)
            write_event(con, at, actor.label, "ticket.created", "%s created: %s" % (t["key"], t["title"]), ticket_id=t["id"],
                        data={"origin": "eric", "priority": t["priority"], "status": t["status"]})
            entry = write_report_entry(con, at, "%s created (%s, %s): %s" % (t["key"], t["status"], t["priority"], t["title"]),
                                       "ticket new", t["id"], next_line=args.next)
        d = ticket_dict(con, t)
    finally:
        con.close()
    return with_report_entry({"ticket": d}, "%s (%s) created: %s [%s]" % (d["key"], d["team_key"], d["title"], d["status"]), entry)


def cmd_ticket_move(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_spud(con, actor, "moving a ticket")
        check_next(con, actor, args)
        at = now()
        with write_txn(con):
            t = get_ticket(con, args.key)
            check_transition("tickets", t["status"], args.status, t["key"])
            closed = at if args.status in ("done", "declined") else None
            con.execute("UPDATE tickets SET status = ?, updated_at = ?, closed_at = ? WHERE id = ?", (args.status, at, closed, t["id"]))
            write_event(con, at, actor.label, "ticket.status", "%s %s -> %s%s" % (t["key"], t["status"], args.status, (": " + args.reason) if args.reason else ""),
                        ticket_id=t["id"], data={"from": t["status"], "to": args.status})
            entry = write_report_entry(con, at, "%s %s: %s" % (t["key"], TICKET_MOVE_VERBS[args.status], t["title"]),
                                       "ticket move", t["id"], next_line=args.next)
            t = get_ticket_by_id(con, t["id"])
        d = ticket_dict(con, t)
    finally:
        con.close()
    return with_report_entry({"ticket": d}, "%s is now %s" % (d["key"], d["status"]), entry)


def cmd_ticket_edit(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_spud(con, actor, "editing a ticket")
        check_next(con, actor, args)
        at = now()
        entry = None
        with write_txn(con):
            t = get_ticket(con, args.key)
            updates = {}
            for field in ("title", "heading", "brief", "sizing", "outcome"):
                value = getattr(args, field)
                if value is not None and value != (t[field] or ""):
                    updates[field] = value
            if args.tag is not None:
                tags = ["ticket"] + [x for x in args.tag if x != "ticket"]
                if json.dumps(tags) != t["tags"]:
                    updates["tags"] = json.dumps(tags)
            old_priority = t["priority"]
            priority_change = args.priority is not None and args.priority != old_priority
            if args.next is not None and not priority_change:
                raise no_entry_for_next("ticket edit writes one only when --priority changes the priority, and %s stays %s" % (t["key"], old_priority))
            if priority_change:
                con.execute("UPDATE tickets SET priority = ?, updated_at = ? WHERE id = ?", (args.priority, at, t["id"]))
                write_event(con, at, actor.label, "ticket.priority", "%s %s -> %s" % (t["key"], t["priority"], args.priority),
                            ticket_id=t["id"], data={"from": t["priority"], "to": args.priority})
            if updates:
                con.execute("UPDATE tickets SET %s, updated_at = ? WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), at, t["id"]))
                write_event(con, at, actor.label, "ticket.edited", "%s edited: %s" % (t["key"], ", ".join(sorted(updates))),
                            ticket_id=t["id"], data={"fields": sorted(updates)})
            t = get_ticket_by_id(con, t["id"])
            if priority_change:  # the entry names the ticket as the edit leaves it
                entry = write_report_entry(con, at, "%s priority %s to %s: %s" % (t["key"], old_priority, t["priority"], t["title"]),
                                           "ticket edit", t["id"], next_line=args.next)
        d = ticket_dict(con, t)
        changed = sorted(updates) + (["priority"] if priority_change else [])
    finally:
        con.close()
    return with_report_entry({"ticket": d, "changed": changed}, "%s edited: %s" % (d["key"], ", ".join(changed) or "nothing to change"), entry)


def format_ticket(d):
    lines = ["%s (%s) %s %s: %s" % (d["key"], d["team_key"], d["status"], d["priority"], d["title"])]
    lines.append("origin: %s%s   lead: %s   created: %s" % (d["origin"], (" by " + d["proposed_by"]) if d["proposed_by"] else "", d["lead"] or "-", d["created_at"]))
    for name, key in (("Brief", "brief"), ("Size, persona and model decision", "sizing"), ("Outcome", "outcome")):
        if d[key]:
            lines.append("")
            lines.append("## " + name)
            lines.append(d[key])
    return "\n".join(lines)


def cmd_ticket_show(ctx, args):
    con = connect(ctx)
    try:
        d = ticket_dict(con, get_ticket(con, args.key))
    finally:
        con.close()
    return Result({"ticket": d}, format_ticket(d))


def planning_session(env):
    """The Claude Code session a command runs in: CLAUDE_CODE_SESSION_ID, which the harness sets in every Bash and
    hook subprocess to the session_id its hook payloads carry, a subagent's Bash included (hooks and env-vars
    references; observed 2026-09-13, SPD-018).  None outside a session."""
    value = env.get("CLAUDE_CODE_SESSION_ID")
    return value.strip() if isinstance(value, str) and value.strip() else None


def cmd_member_new(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        m = plan_member(ctx, con, actor, args.ticket, args.persona, args.model, name=args.name, tier_reason=args.tier_reason,
                        agent_type=args.agent_type, brief=args.brief or "", deliverables=args.deliverable,
                        session_id=planning_session(os.environ))
        d = member_dict(con, m)
    finally:
        con.close()
    return Result({"member": d}, "planned %s (%s, %s, %s) on %s" % (d["ref"], d["lineage"], d["persona"], d["model"], d["ticket"]))


def status_stamps(m, new_status, at):
    """The timestamps a member transition carries: spawned on the first start,
    finished cleared on a resume from blocked, finished stamped on a terminal state."""
    extra = {}
    if new_status == "active":
        if m["spawned_at"] is None:
            extra["spawned_at"] = at
        if m["status"] == "blocked":
            extra["finished_at"] = None
    elif new_status in ("done", "blocked", "failed"):
        extra["finished_at"] = at
    return extra


def member_status_change(con, at, actor_label, m, new_status, extra_updates=None, outcome_event=None):
    check_transition("members", m["status"], new_status, member_ref(con, m["id"]))
    updates = status_stamps(m, new_status, at)
    updates.update(extra_updates or {})
    updates["status"] = new_status
    con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), m["id"]))
    if outcome_event:
        write_event(con, at, actor_label, "member.outcome", outcome_event, ticket_id=m["ticket_id"], member_id=m["id"],
                    data={"status": new_status, "summary": updates.get("summary")})
    write_event(con, at, actor_label, "member.status", "%s %s -> %s" % (member_ref(con, m["id"]), m["status"], new_status),
                ticket_id=m["ticket_id"], member_id=m["id"], data={"from": m["status"], "to": new_status})


def cmd_member_start(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        at = now()
        with write_txn(con):
            m = get_member(con, args.ref)
            require_ancestor(con, actor, m, "starting a member (its status)")
            member_status_change(con, at, actor.label, m, "active")
            m = get_member_by_id(con, m["id"])
        d = member_dict(con, m)
    finally:
        con.close()
    return Result({"member": d}, "%s is active (spawned %s)" % (d["ref"], fm_minute(d["spawned_at"])))


def cmd_member_finish(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        check_next(con, actor, args)
        at = now()
        entry = None
        with write_txn(con):
            m = get_member(con, args.ref)
            require_ancestor(con, actor, m, "finishing a member (status, outcome, finished)")
            if args.next is not None and m["parent_id"] is not None:
                raise no_entry_for_next("member finish writes one only for a root member, and %s is %s's child" % (member_ref(con, m["id"]), member_ref(con, m["parent_id"])))
            extra = {"outcome": args.outcome}
            if args.summary is not None:
                extra["summary"] = args.summary
            member_status_change(con, at, actor.label, m, args.status, extra, outcome_event=args.outcome)
            m = get_member_by_id(con, m["id"])
            if actor.kind == "spud" and m["parent_id"] is None:  # report entries are Spud's: his own children's verdicts
                ticket = get_ticket_by_id(con, m["ticket_id"])
                summary = m["summary"] if m["summary"] and m["summary"].strip() else None
                entry = write_report_entry(con, at, "%s: %s (%s, %s, %s) %s" % (ticket["key"], m["name"], m["lineage"], m["persona"], m["model"], m["status"]),
                                           "member finish", ticket["id"], member_id=m["id"], lines=[summary] if summary else [], next_line=args.next)
        d = member_dict(con, m)
    finally:
        con.close()
    return with_report_entry({"member": d}, "%s is %s (finished %s)" % (d["ref"], d["status"], d["finished_at"]), entry)


def cmd_member_edit(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        at = now()
        with write_txn(con):
            m = get_member(con, args.ref)
            require_ancestor(con, actor, m, "editing a member's brief, deliverables, model or summary")
            updates = {}
            if args.brief is not None and args.brief != m["brief"]:
                updates["brief"] = args.brief
            if args.deliverable is not None and json.dumps(normalize_deliverables(args.deliverable)) != m["deliverables"]:
                updates["deliverables"] = json.dumps(normalize_deliverables(args.deliverable))
            if args.summary is not None and args.summary != m["summary"]:
                updates["summary"] = args.summary
            if args.agent_type is not None and args.agent_type != m["agent_type"]:
                updates["agent_type"] = args.agent_type
            if args.model is not None and args.model != m["model"]:
                default_tier = ctx.persona_tier(m["persona"])
                if default_tier and args.model != default_tier and not args.tier_reason:
                    raise SpudError(EXIT_ERROR, "%s defaults to %s; model %s needs --tier-reason" % (m["persona"], default_tier, args.model))
                updates["model"] = args.model
            if args.tier_reason is not None and args.tier_reason != m["tier_reason"]:
                updates["tier_reason"] = args.tier_reason
            if updates:
                con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), m["id"]))
                write_event(con, at, actor.label, "member.edited", "%s edited: %s" % (member_ref(con, m["id"]), ", ".join(sorted(updates))),
                            ticket_id=m["ticket_id"], member_id=m["id"], data={"fields": sorted(updates)})
            m = get_member_by_id(con, m["id"])
        d = member_dict(con, m)
        changed = sorted(updates)
    finally:
        con.close()
    return Result({"member": d, "changed": changed}, "%s edited: %s" % (d["ref"], ", ".join(changed) or "nothing to change"))


def cmd_member_own(ctx, args, kind):
    """member log|result|block: the member's own sections."""
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        what = {"log": "the Log", "result": "the Result", "block": "the Blocked section"}[kind]
        require_member(con, actor, what)
        at = now()
        with write_txn(con):
            m = get_member_by_id(con, actor.member["id"])
            if kind == "log":
                write_event(con, at, actor.label, "member.log", args.text, ticket_id=m["ticket_id"], member_id=m["id"])
            elif kind == "result":
                con.execute("UPDATE members SET result = ? WHERE id = ?", (args.text, m["id"]))
                write_event(con, at, actor.label, "member.result", args.text, ticket_id=m["ticket_id"], member_id=m["id"])
            else:
                con.execute("UPDATE members SET blocked = ? WHERE id = ?", (args.text, m["id"]))
                write_event(con, at, actor.label, "member.blocked", args.text, ticket_id=m["ticket_id"], member_id=m["id"])
            m = get_member_by_id(con, m["id"])
        d = member_dict(con, m)
    finally:
        con.close()
    verb = {"log": "logged", "result": "recorded the Result of", "block": "recorded the Blocked section of"}[kind]
    return Result({"member": d}, "%s %s" % (verb, d["ref"]))


def format_member(d):
    lines = ["%s (%s, %s, %s) %s on %s" % (d["ref"], d["lineage"], d["persona"], d["model"], d["status"], d["ticket"])]
    lines.append("parent: %s   planned: %s   spawned: %s   finished: %s" % (d["parent"] or "Spud", d["planned_at"], d["spawned_at"] or "-", d["finished_at"] or "-"))
    if d["tier_reason"]:
        lines.append("tier reason: " + d["tier_reason"])
    if d["deliverables"]:
        lines.append("deliverables: " + ", ".join(d["deliverables"]))
    for name, key in (("Brief", "brief"), ("Result", "result"), ("Blocked", "blocked"), ("Outcome", "outcome"), ("Summary", "summary")):
        if d[key]:
            lines.append("")
            lines.append("## " + name)
            lines.append(d[key])
    return "\n".join(lines)


def cmd_member_show(ctx, args):
    con = connect(ctx)
    try:
        d = member_dict(con, get_member(con, args.ref))
    finally:
        con.close()
    return Result({"member": d}, format_member(d))


# member resum (SPD-023): a transcript sum stored before SPD-023 added every transcript entry; it is re-summed
# once per API request from the member's transcript, merged through run_totals, its old figures kept in a
# member.edited event.  The events table's kinds are fixed by its CHECK constraint, so the re-sum is recorded
# as the member edit it is rather than as a kind that would take a migration of the append-only table.
RESUM_FIGURES = ("total_tokens", "tool_uses", "duration_ms")
RESUM_KEPT = {None: "no sum", "imported": "imported", "breakdown": "counted"}  # stored_counting -> the action: nothing to do
RESUM_LEFT = ("not found", "ambiguous", "unreadable", "no usage")  # a sum without its breakdown left as it is: exit 1


def stored_counting(usage_json):
    """How a member's stored transcript sum was counted: "breakdown" (once per API request, with the per-model
    breakdown, since SPD-013), "request" (once per request without it, from SPD-023 to SPD-013), "entry"
    (before SPD-023, every transcript entry added) or "imported" (read back from a rendered note by the
    importer, with no transcript behind it); None when usage_json holds no transcript sum.  member resum
    re-sums "entry" and "request"."""
    stored, _ = usage_parts(usage_json)
    if stored is None:
        return None
    if stored.get("imported") is True:
        return "imported"
    if stored.get("counting") != REQUEST_COUNTING:
        return "entry"
    return "breakdown" if isinstance(stored.get("breakdown"), list) else "request"


def find_transcript(recorded):
    """(path, how, note) for a member's transcript: the recorded transcript_path when it is a file ("recorded");
    else the one file with the same session directory and file name, <session>/subagents/agent-<id>.jsonl,
    under any project directory beside the recorded one ("moved": the harness moves a worktree session's
    transcripts into another project directory when the session leaves the worktree); else None with
    "not found" or "ambiguous" and a note saying where it looked."""
    if not recorded:
        return None, "not found", "no transcript path recorded"
    path = Path(recorded)
    if path.is_file():
        return path, "recorded", None
    if path.parent.name != "subagents" or len(path.parts) < 5:
        return None, "not found", "no file at %s" % path
    project = path.parents[2]
    tail = Path(path.parents[1].name, "subagents", path.name)
    try:
        siblings = sorted(project.parent.iterdir())
    except OSError:
        siblings = []
    matches = [d / tail for d in siblings if (d / tail).is_file()]
    if len(matches) == 1:
        return matches[0], "moved", None
    if not matches:
        return None, "not found", "no file at %s, nor at <project>/%s under %s" % (path, tail, project.parent)
    return None, "ambiguous", "%d files: %s" % (len(matches), ", ".join(str(m) for m in matches))


def resum_row(member, ref):
    """What `member resum` does with one member: (its row for the table and --json, the new transcript sum
    when there is one to write).  The row's action is "re-sum", "counted" (already by request), "imported"
    or "no sum" (left, nothing to do), or one of RESUM_LEFT."""
    row = {"ref": ref, "action": None, "found": None, "transcript": None, "note": None, "requests": None,
           "old": {k: member[k] for k in RESUM_FIGURES}, "new": None}
    counting = stored_counting(member["usage_json"])
    if counting in RESUM_KEPT:
        row["action"] = RESUM_KEPT[counting]
        return row, None
    path, how, note = find_transcript(member["transcript_path"])
    if path is None:
        row.update(action=how, transcript=member["transcript_path"], note=note)
        return row, None
    row.update(found=how, transcript=str(path))
    try:
        summed = transcript_usage(path)
    except OSError as e:
        row.update(action="unreadable", note="%s: %s" % (path, e.strerror or e))
        return row, None
    if summed is None:
        row.update(action="no usage", note="%s holds no assistant usage" % path)
        return row, None
    totals = run_totals(member, summed=summed)
    row.update(action="re-sum", requests=summed["usage_json"]["messages"], new={k: totals[k] for k in RESUM_FIGURES})
    return row, summed


def resum_table(data):
    """member resum's text: the table, one line per member with its old -> new figures, then one line saying
    what was written."""
    lines = []
    for r in data["members"]:
        line = {"ref": r["ref"], "action": r["action"], "requests": "-" if r["requests"] is None else r["requests"]}
        for k in RESUM_FIGURES:
            old = "-" if r["old"][k] is None else str(r["old"][k])
            line[k] = old if r["new"] is None else "%s -> %s" % (old, "-" if r["new"][k] is None else r["new"][k])
        line["transcript"] = ("%s: %s" % (r["found"], r["transcript"])) if r["action"] == "re-sum" else (r["note"] or "-")
        lines.append(line)
    text = table(lines, [("member", "ref"), ("action", "action"), ("requests", "requests"), ("total_tokens", "total_tokens"),
                         ("tool_uses", "tool_uses"), ("duration_ms", "duration_ms"), ("transcript", "transcript")])
    total = len(data["members"])
    resum = sum(1 for r in data["members"] if r["action"] == "re-sum")
    left = sum(1 for r in data["members"] if r["action"] in RESUM_LEFT)
    return text + "\n" + "%s %d of %d member%s once per API request, with the per-model breakdown; %d left with a sum that added every entry or lacks the breakdown; %d already counted with the breakdown, imported, or without a transcript sum" % (
        "dry run, nothing written: would re-sum" if data["dry_run"] else "re-summed", resum, total, "" if total == 1 else "s", left, total - resum - left)


def cmd_member_resum(ctx, args):
    """member resum: stored transcript sums counted per entry, re-summed once per API request (Spud's)."""
    if bool(args.refs) == bool(args.all):
        raise SpudError(EXIT_USAGE, "member resum takes the members to re-sum (SPUD-nnn/<Name> ...) or --all, one of the two")
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_spud(con, actor, "re-summing members' stored run totals (member resum)")
        if args.all:
            members = con.execute("SELECT * FROM members WHERE json_extract(usage_json, '$.source') = 'transcript' ORDER BY ticket_id, lineage").fetchall()
        else:
            members, seen = [], set()
            for ref in args.refs:
                m = get_member(con, ref)
                if m["id"] not in seen:
                    seen.add(m["id"])
                    members.append(m)
        # Transcripts are read before the write lock is taken; the write re-reads each row and merges the sum into it.
        plans = [resum_row(m, member_ref(con, m["id"])) for m in members]
        resummed = []
        if not args.dry_run and any(summed for _, summed in plans):
            at = now()
            with write_txn(con):
                for (row, summed), member in zip(plans, members):
                    if summed is None:
                        continue
                    fresh = get_member_by_id(con, member["id"])
                    counting = stored_counting(fresh["usage_json"])
                    if counting in RESUM_KEPT:  # changed since it was read (a concurrent re-sum): nothing left to do
                        row.update(action=RESUM_KEPT[counting], requests=None, old={k: fresh[k] for k in RESUM_FIGURES}, new=None)
                        continue
                    totals = run_totals(fresh, summed=summed)
                    new = {k: totals[k] for k in RESUM_FIGURES}
                    new.update(transcript_path=row["transcript"], usage_json=totals["usage_json"])
                    old = {k: fresh[k] for k in new}
                    con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in new), (*new.values(), fresh["id"]))
                    row.update(old={k: old[k] for k in RESUM_FIGURES}, new={k: new[k] for k in RESUM_FIGURES})
                    write_event(con, at, actor.label, "member.edited",
                                "%s re-summed once per API request, with the per-model breakdown, from its transcript: total_tokens %s -> %s, tool_uses %s -> %s, duration_ms %s -> %s"
                                % (row["ref"], old["total_tokens"], new["total_tokens"], old["tool_uses"], new["tool_uses"], old["duration_ms"], new["duration_ms"]),
                                ticket_id=fresh["ticket_id"], member_id=fresh["id"],
                                data={"fields": sorted(k for k in new if new[k] != old[k]), "counting": REQUEST_COUNTING, "breakdown": True, "found": row["found"],
                                      "transcript": row["transcript"], "requests": row["requests"], "old": old, "new": new})
                    resummed.append(row["ref"])
    finally:
        con.close()
    rows = [row for row, _ in plans]
    left = [r for r in rows if r["action"] in RESUM_LEFT]
    data = {"dry_run": bool(args.dry_run), "members": rows, "resummed": resummed, "left": [r["ref"] for r in left]}
    if left:
        return Result(data, resum_table(data), exit_code=EXIT_ERROR, stderr="%d sum%s without the per-model breakdown left as %s: %s" % (
            len(left), "" if len(left) == 1 else "s", "it is" if len(left) == 1 else "they are",
            "; ".join("%s (%s)" % (r["ref"], r["action"]) for r in left)))
    return Result(data, resum_table(data))


def cmd_proposal_file(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_member(con, actor, "filing a proposal")
        at = now()
        with write_txn(con):
            m = get_member_by_id(con, actor.member["id"])
            cur = con.execute(
                "INSERT INTO proposals (ticket_id, origin_member_id, holder_member_id, title, why, evidence, suggested_priority, filed_at, status)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'open')",
                (m["ticket_id"], m["id"], m["parent_id"], args.title, args.why or "", args.evidence or "", args.priority, at),
            )
            proposal_id = cur.lastrowid
            write_event(con, at, actor.label, "proposal.filed", args.title, ticket_id=m["ticket_id"], member_id=m["id"],
                        data={"proposal_id": proposal_id, "suggested_priority": args.priority})
        d = proposal_dict(con, con.execute("SELECT * FROM proposals WHERE id = ?", (proposal_id,)).fetchone())
    finally:
        con.close()
    return Result({"proposal": d}, "proposal %d filed: %s (held by %s)" % (d["id"], d["title"], d["holder"] or "Spud"))


def cmd_proposal_decide(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        check_next(con, actor, args)
        at = now()
        created = None
        entry = None
        with write_txn(con):
            p = con.execute("SELECT * FROM proposals WHERE id = ?", (args.id,)).fetchone()
            if p is None:
                raise SpudError(EXIT_ERROR, "no proposal %d" % args.id)
            if p["status"] != "open":
                raise SpudError(EXIT_ERROR, "proposal %d is already %s" % (p["id"], p["status"]))
            holder = p["holder_member_id"]
            if actor.kind == "spud":
                if holder is not None:
                    raise SpudError(EXIT_OWNERSHIP, "proposal %d is held by %s, not by Spud yet" % (p["id"], member_ref(con, holder)))
                if args.decision == "escalate":
                    raise SpudError(EXIT_ERROR, "Spud has nobody to escalate to; create or decline")
                if args.decision == "absorb":
                    raise SpudError(EXIT_ERROR, "Spud does not absorb work (Law 1); create a ticket or decline")
            else:
                if holder != actor.member["id"]:
                    raise SpudError(EXIT_OWNERSHIP, "proposal %d is held by %s, not by %s" % (p["id"], "Spud" if holder is None else member_ref(con, holder), actor.ref(con)))
                if args.decision == "create":
                    raise SpudError(EXIT_OWNERSHIP, "only Spud creates tickets (Law 6); escalate instead")
            updates = {}
            if args.decision == "escalate":
                updates["holder_member_id"] = actor.member["parent_id"]
            elif args.decision == "absorb":
                updates["status"] = "absorbed"
            elif args.decision == "decline":
                updates["status"] = "declined"
            else:
                priority = args.priority or p["suggested_priority"] or "P2"
                created = create_ticket_for_proposal(con, at, actor, p, args.title, priority)
                updates["status"] = "created"
                updates["created_ticket_id"] = created["id"]
            con.execute("UPDATE proposals SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), p["id"]))
            con.execute(
                "INSERT INTO proposal_decisions (proposal_id, at, by_member_id, decision, reason, created_ticket_id) VALUES (?, ?, ?, ?, ?, ?)",
                (p["id"], at, None if actor.kind == "spud" else actor.member["id"], args.decision, args.reason or "", created["id"] if created else None),
            )
            write_event(con, at, actor.label, "proposal.decided", "%s: %s%s" % (args.decision, p["title"], (" (" + args.reason + ")") if args.reason else ""),
                        ticket_id=p["ticket_id"], member_id=p["origin_member_id"],
                        data={"proposal_id": p["id"], "decision": args.decision, "created_ticket": created["key"] if created else None})
            if actor.kind == "spud":  # Spud creates or declines, and either decision is one report entry
                proposer = member_ref(con, p["origin_member_id"])
                if created is not None:
                    entry = write_report_entry(con, at, "%s created from a proposal by %s (%s, %s): %s" % (created["key"], proposer, created["status"], created["priority"], created["title"]),
                                               "proposal decide", created["id"], next_line=args.next)
                else:
                    reason = args.reason if args.reason and args.reason.strip() else None
                    entry = write_report_entry(con, at, "Proposal declined: %s (from %s)" % (p["title"], proposer),
                                               "proposal decide", p["ticket_id"], lines=["Reason: " + reason] if reason else [], next_line=args.next)
            p = con.execute("SELECT * FROM proposals WHERE id = ?", (p["id"],)).fetchone()
        d = proposal_dict(con, p)
        data = {"proposal": d}
        if created:
            data["ticket"] = ticket_dict(con, get_ticket_by_id(con, created["id"]))
    finally:
        con.close()
    text = "proposal %d %s" % (d["id"], {"escalate": "escalated to %s" % (d["holder"] or "Spud"), "absorb": "absorbed", "decline": "declined", "create": "created as %s" % d["created_ticket"]}[args.decision])
    return with_report_entry(data, text, entry)


def cmd_proposal_list(ctx, args):
    con = connect(ctx)
    try:
        sql = "SELECT p.* FROM proposals p"
        params = []
        clauses = []
        if args.ticket:
            clauses.append("p.ticket_id = ?")
            params.append(get_ticket(con, args.ticket)["id"])
        if args.open:
            clauses.append("p.status = 'open'")
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        rows = [proposal_dict(con, p) for p in con.execute(sql + " ORDER BY p.id", params).fetchall()]
    finally:
        con.close()
    return Result({"proposals": rows}, table(rows, [("id", "id"), ("ticket", "ticket"), ("status", "status"), ("origin", "origin"), ("holder", "holder"), ("P", "suggested_priority"), ("title", "title")]))


def cmd_handoff_add(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        at = now()
        with write_txn(con):
            t = get_ticket(con, args.ticket)
            if actor.kind == "member" and actor.member["ticket_id"] != t["id"]:
                raise SpudError(EXIT_OWNERSHIP, "%s is not on %s's team; a member records handoffs only on its own ticket" % (actor.ref(con), t["key"]))
            parties = []
            for label in (args.frm, args.to):
                if label == "spud":
                    parties.append(None)
                else:
                    m = get_member(con, label)
                    if m["ticket_id"] != t["id"]:
                        raise SpudError(EXIT_ERROR, "%s is not on %s's team" % (label, t["key"]))
                    parties.append(m["id"])
            if parties == [None, None]:
                raise SpudError(EXIT_ERROR, "a handoff needs a member on at least one side")
            if actor.kind == "member" and actor.member["id"] not in parties:
                raise SpudError(EXIT_OWNERSHIP, "a handoff is recorded by Spud or by one of its parties; %s is neither" % actor.ref(con))
            cur = con.execute(
                "INSERT INTO handoffs (ticket_id, at, from_member_id, to_member_id, what, path) VALUES (?, ?, ?, ?, ?, ?)",
                (t["id"], at, parties[0], parties[1], args.what, args.path),
            )
            write_event(con, at, actor.label, "handoff", "%s → %s: %s" % (handoff_party(con, parties[0]), handoff_party(con, parties[1]), args.what),
                        ticket_id=t["id"], member_id=parties[0], data={"handoff_id": cur.lastrowid, "to": parties[1], "path": args.path})
    finally:
        con.close()
    return Result({"handoff": {"id": cur.lastrowid, "ticket": args.ticket, "from": args.frm, "to": args.to, "what": args.what, "path": args.path}},
                  "handoff recorded on %s" % args.ticket)


def cmd_report_add(ctx, args):
    con = connect(ctx)
    try:
        actor = resolve_actor(con, args.actor)
        require_spud(con, actor, "a report entry")
        at = now()
        body = "- Next: " + args.next
        with write_txn(con):
            event_id = write_event(con, at, actor.label, "report.entry", body, data={"title": args.title})
    finally:
        con.close()
    entry = {"id": event_id, "at": at, "title": args.title, "body": body}
    return Result({"entry": entry}, report_entry_line(entry))


def cmd_events(ctx, args):
    con = connect(ctx)
    try:
        clauses, params = [], []
        if args.ticket:
            clauses.append("ticket_id = ?")
            params.append(get_ticket(con, args.ticket)["id"])
        if args.member:
            clauses.append("member_id = ?")
            params.append(get_member(con, args.member)["id"])
        if args.kind:
            clauses.append("kind = ?")
            params.append(args.kind)
        sql = "SELECT * FROM events" + ((" WHERE " + " AND ".join(clauses)) if clauses else "") + " ORDER BY id"
        rows = con.execute(sql, params).fetchall()
        if args.limit:
            rows = rows[-args.limit :]
        events = [event_dict(con, e) for e in rows]
    finally:
        con.close()
    lines = ["%d  %s  %s  %s  %s" % (e["id"], e["at"], e["actor"], e["kind"], e["body"].split("\n")[0]) for e in events]
    return Result({"events": events}, "\n".join(lines) or "(no events)")


def brief_state(m, today=None):
    """A live member's state on the brief board: its status, or `returned HH:MM, unrecorded` for a member that
    returned and has no verdict yet (the date too when it stopped on another day).  A session holds only for its
    own members (SPD-018), so this is how a later or parallel session sees another session's."""
    if m["status"] == "active" and m["stopped_at"] and not (m["outcome"] or "").strip():
        same_day = m["stopped_at"][:10] == (today or now())[:10]
        return "returned %s, unrecorded" % (m["stopped_at"][11:16] if same_day else fm_minute(m["stopped_at"]))
    return m["status"]


def board_brief_text(con, rows=None):
    """Open tickets and their live members, one line each (also the SessionStart context)."""
    if rows is None:
        rows = [dict(r) for r in con.execute("SELECT * FROM v_board").fetchall()]
    lines = []
    today = now()
    for r in rows:
        if r["status"] in ("done", "declined"):
            continue
        lines.append("%s %s %s %s%s" % (r["key"], r["status"], r["priority"], r["title"], (" (lead %s)" % r["lead"]) if r["lead"] else ""))
        if r["status"] == "active":
            for m in con.execute(
                "SELECT m.* FROM members m JOIN tickets t ON t.id = m.ticket_id WHERE t.key = ? AND m.status IN ('planned','active') ORDER BY m.lineage",
                (r["key"],),
            ).fetchall():
                lines.append("  %s (%s, %s, %s) %s" % (m["name"], m["lineage"], persona_label(m), m["model"], brief_state(m, today)))
    return "\n".join(lines) or "(no open tickets)"


def cmd_board(ctx, args):
    con = connect(ctx)
    try:
        rows = [dict(r) for r in con.execute("SELECT * FROM v_board").fetchall()]
        if args.brief:
            text = board_brief_text(con, rows)
        else:
            for r in rows:
                r["created"] = fm_date(r["created_at"])
            text = table(rows, [("ticket", "key"), ("status", "status"), ("P", "priority"), ("title", "title"), ("lead", "lead"), ("origin", "origin"), ("proposed by", "proposed_by"), ("created", "created")])
    finally:
        con.close()
    return Result({"tickets": rows}, text)


def cmd_fleet(ctx, args):
    con = connect(ctx)
    try:
        rows = [dict(r) for r in con.execute("SELECT * FROM v_fleet").fetchall()]
    finally:
        con.close()
    for r in rows:
        r["spawned"] = fm_minute(r["spawned_at"])
        r["finished"] = fm_minute(r["finished_at"])
    return Result({"members": rows}, table(rows, [("ticket", "ticket"), ("id", "id"), ("name", "name"), ("persona", "persona"), ("model", "model"), ("status", "status"), ("parent", "parent"), ("spawned", "spawned"), ("finished", "finished")]))


def team_tree(con, ticket, pricing=None):
    rows = con.execute("SELECT * FROM members WHERE ticket_id = ? ORDER BY lineage", (ticket["id"],)).fetchall()
    nodes = {}
    roots = []
    for m in rows:
        node = member_dict(con, m)
        cost, reasons = run_cost(m["usage_json"], pricing)  # SPD-013: the run's tokens and its cost at the API list price
        node.update(tokens=token_counts(m["usage_json"]), cost_usd=usd_text(cost) if cost is not None else None, not_priced=reasons)
        node["children"] = []
        nodes[m["id"]] = node
        if m["parent_id"] in nodes:
            nodes[m["parent_id"]]["children"].append(node)
        else:
            roots.append(node)
    return roots


def flatten_team(nodes):
    """team_tree()'s roots flattened in the depth-first order `card` prints (format_tree's order:
    each root, then its children recursively), each member dict without its "children" key."""
    flat = []
    for n in nodes:
        flat.append({k: v for k, v in n.items() if k != "children"})
        flat.extend(flatten_team(n["children"]))
    return flat


def format_tree(nodes, depth=0):
    lines = []
    for n in nodes:
        run = "spawned %s, finished %s" % (fm_minute(n["spawned_at"]) or "-", fm_minute(n["finished_at"]) or "-")
        line = "%s- %s (%s, %s, %s) %s; %s" % ("  " * depth, n["name"], n["lineage"], n["persona"] if n["persona"] != "contractor" else "contractor on %s" % n["agent_type"], n["model"], n["status"], run)
        if n.get("tokens"):
            line += "; %s · %s" % (tokens_text(n["tokens"]), "$" + n["cost_usd"] if n.get("cost_usd") else "— (%s)" % "; ".join(n.get("not_priced") or ["not priced"]))
        lines.append(line)
        if n["summary"]:
            lines.append("%s  %s" % ("  " * depth, n["summary"]))
        lines.extend(format_tree(n["children"], depth + 1))
    return lines


def card_total_line(totals, not_priced, pricing):
    """The card's last line (SPD-013): the ticket's tokens and its cost at the API list price, with the table's date,
    partial when a member's transcript sum has no cost, naming each such member and why."""
    if totals["tokens"] is None:
        return "total: no tokens recorded"
    tokens = tokens_text(totals["tokens"])
    if pricing is None:
        return "total: %s · — (%s)" % (tokens, NO_TABLE)
    cost = "—" if totals["cost"] is None else money(totals["cost"]) + (" (partial)" if not_priced else "")
    line = "total: %s · %s at API list price (USD, prices as of %s)" % (tokens, cost, pricing["as_of"])
    if not_priced:
        line += "; not priced: " + ", ".join("%s (%s)" % (p["ref"], "; ".join(p["reasons"])) for p in not_priced)
    return line


def cmd_card(ctx, args):
    con = connect(ctx)
    try:
        t = get_ticket(con, args.key)
        d = ticket_dict(con, t)
        pricing = ctx.pricing
        tree = team_tree(con, t, pricing)
        totals = team_totals(con.execute("SELECT * FROM members WHERE ticket_id = ? ORDER BY lineage", (t["id"],)).fetchall(), pricing)
        not_priced = [{"ref": member_ref(con, m["id"]), "reasons": reasons} for m, reasons in totals["not_priced"]]
    finally:
        con.close()
    total = {"tokens": totals["tokens"], "cost_usd": usd_text(totals["cost"]) if totals["cost"] is not None else None,
             "partial": totals["cost"] is not None and bool(not_priced), "not_priced": not_priced, "tool_uses": totals["tools"],
             "pricing": {k: pricing[k] for k in ("as_of", "source", "currency")} if pricing else None}
    lines = ["%s — %s  [%s, %s]  lead: %s" % (d["key"], d["title"], d["status"], d["priority"], d["lead"] or "-")]
    lines.extend(format_tree(tree) or ["(no team yet)"])
    if tree:
        lines.append(card_total_line(totals, not_priced, pricing))
    return Result({"ticket": d, "team": tree, "total": total}, "\n".join(lines))


def cmd_member_list(ctx, args):
    """member list [--ticket]: what `card`'s team shows for one ticket, in its order, or what
    `fleet` shows for every member, in its order; read-only, for any actor or none."""
    con = connect(ctx)
    try:
        if args.ticket:
            t = get_ticket(con, args.ticket)
            members = flatten_team(team_tree(con, t, ctx.pricing))  # SPD-013: match card's team, cost included
        else:
            rows = con.execute("SELECT m.* FROM members m JOIN tickets t ON t.id = m.ticket_id ORDER BY t.id DESC, m.lineage").fetchall()
            members = [member_dict(con, m) for m in rows]
    finally:
        con.close()
    lines = ["%s (%s, %s, %s) %s" % (d["ref"], d["lineage"], d["persona"], d["model"], d["status"]) for d in members]
    return Result({"members": members}, "\n".join(lines) or "(no members)")


def cmd_doctor(ctx, args):
    problems = []
    report = {
        "interpreter": {"path": sys.executable, "version": "%d.%d.%d" % sys.version_info[:3], "flags": {"isolated": bool(sys.flags.isolated), "no_site": bool(sys.flags.no_site)}},
        "sqlite": {"library": sqlite3.sqlite_version, "module": sqlite3.version if hasattr(sqlite3, "version") else None},
        "spud_home": {"path": str(ctx.home), "resolved_by": ctx.resolved_by, "config": str(ctx.config_path), "config_exists": ctx.config_path.is_file()},
        "database": {"path": str(ctx.db_path), "exists": ctx.db_path.is_file()},
        "schema_version": SCHEMA_VERSION,
    }
    if sys.version_info[:2] != (3, 14):
        problems.append("interpreter is Python %s, not 3.14" % report["interpreter"]["version"])
    if not ctx.config_path.is_file():
        problems.append("no spud.config.json in %s" % ctx.home)
        config = None
    else:
        try:
            config = ctx.config
        except SpudError as e:
            problems.append(e.message)
            config = None
    if config is not None:
        cfg_problems = config_problems(config)
        problems.extend("config: " + p for p in cfg_problems)
        report["config"] = {"problems": cfg_problems, "limits": config.get("limits"), "pool": len(config.get("naming", {}).get("pool", []))}
    pricing = price_table(config)[0] if config is not None else None  # SPD-013: the price table, and below what it cannot price
    report["pricing"] = None if pricing is None else {"as_of": pricing["as_of"], "source": pricing["source"], "currency": "USD",
                                                      "models": sorted(pricing["models"]), "not_priced": []}
    db = report["database"]
    if db["exists"]:
        con = open_connection(ctx.db_path)
        try:
            db["user_version"] = con.execute("PRAGMA user_version").fetchone()[0]
            db["journal_mode"] = con.execute("PRAGMA journal_mode").fetchone()[0]
            db["foreign_keys"] = con.execute("PRAGMA foreign_keys").fetchone()[0]
            db["busy_timeout"] = con.execute("PRAGMA busy_timeout").fetchone()[0]
            db["synchronous"] = con.execute("PRAGMA synchronous").fetchone()[0]
            if db["user_version"] != SCHEMA_VERSION:
                problems.append("database user_version %d, CLI schema %d" % (db["user_version"], SCHEMA_VERSION))
            if db["journal_mode"] != "wal":
                problems.append("journal_mode is %s, not wal" % db["journal_mode"])
            if db["user_version"] >= 1 and config is not None:
                home = con.execute("SELECT ticket_prefix, team_prefix FROM projects WHERE id = 1").fetchone()
                if home is None:
                    problems.append("no home project row; run `spud config sync`")
                elif (home["ticket_prefix"], home["team_prefix"]) != (config.get("tickets", {}).get("prefix"), config.get("teams", {}).get("prefix")):
                    problems.append("home project prefixes differ from spud.config.json; run `spud config sync`")
                db["live_members"] = con.execute("SELECT live FROM v_live").fetchone()[0]
                db["tickets"] = con.execute("SELECT count(*) FROM tickets").fetchone()[0]
                db["events"] = con.execute("SELECT count(*) FROM events").fetchone()[0]
                if report["pricing"] is not None:
                    for m in con.execute("SELECT m.* FROM members m JOIN tickets t ON t.id = m.ticket_id WHERE m.usage_json IS NOT NULL ORDER BY t.id, m.lineage").fetchall():
                        cost, reasons = run_cost(m["usage_json"], pricing)
                        if cost is None and reasons:
                            report["pricing"]["not_priced"].append({"ref": member_ref(con, m["id"]), "reasons": reasons})
        finally:
            con.close()
    else:
        problems.append("no database at %s; run `spud init`" % ctx.db_path)
    # The backup copies, read from the directory listing alone (SPD-012).  No backup state is ever a problem:
    # a Mac switched off for a weekend misses its daily copies and is not at fault.
    daily, other = backup_listing(backups_dir(ctx))
    report["backups"] = {"dir": str(backups_dir(ctx)), "daily": {"count": len(daily), "newest": daily[-1] if daily else None, "oldest": daily[0] if daily else None}, "other": other}
    report["problems"] = problems
    lines = [
        "python      %s (%s; isolated=%s, no_site=%s)" % (report["interpreter"]["path"], report["interpreter"]["version"], report["interpreter"]["flags"]["isolated"], report["interpreter"]["flags"]["no_site"]),
        "SQLite      %s" % report["sqlite"]["library"],
        "SPUD_HOME   %s (via %s)" % (report["spud_home"]["path"], report["spud_home"]["resolved_by"]),
        "config      %s%s" % (report["spud_home"]["config"], "" if report["spud_home"]["config_exists"] else " (missing)"),
        "database    %s%s" % (db["path"], "" if db["exists"] else " (missing)"),
    ]
    if db["exists"]:
        lines.append("            user_version %s, journal_mode %s, foreign_keys %s, busy_timeout %s, synchronous %s" % (db.get("user_version"), db.get("journal_mode"), db.get("foreign_keys"), db.get("busy_timeout"), db.get("synchronous")))
        if "tickets" in db:
            lines.append("            %d tickets, %d events, %d members alive" % (db["tickets"], db["events"], db["live_members"]))
    if daily:
        lines.append("backups     %d daily (newest %s, oldest %s), %d other" % (len(daily), daily[-1], daily[0], other))
    else:
        lines.append("backups     0 daily, %d other" % other)
    if report["pricing"] is not None:
        p = report["pricing"]
        lines.append("pricing     API list price in USD as of %s from %s: %d model%s" % (
            p["as_of"], p["source"] or "an unnamed source", len(p["models"]), "" if len(p["models"]) == 1 else "s"))
        lines.extend("            not priced: %s (%s)" % (x["ref"], "; ".join(x["reasons"])) for x in p["not_priced"])
    elif config is not None:
        lines.append("pricing     %s" % ("%s: every cost shows —" % NO_TABLE if not price_table(config)[1] else "no usable price table: see problems"))
    lines.append("problems    %s" % (("\n            ".join(problems)) if problems else "none"))
    result = Result(report, "\n".join(lines))
    if problems:
        raise SpudError(EXIT_ERROR, "doctor found %d problem(s): %s" % (len(problems), "; ".join(problems)), data=report)
    return result


# ----------------------------------------------------------------------------
# Hooks (SPD-008): the harness's events, the laws as refusals
# ----------------------------------------------------------------------------
#
# `spud hook <event>` reads the harness payload on stdin and answers the documented way:
# JSON on stdout with exit 0, or exit 2 with the reason on stderr.  Enforcing hooks
# (PreToolUse for Agent, Bash and the edit tools; Stop) fail closed: a planned refusal is
# `permissionDecision: deny` with the reason (so the model reads why), anything unexpected
# is exit 2.  Recording hooks (PostToolUse for Agent, SubagentStart, SubagentStop,
# SessionStart) fail open: exit 0 whatever happens, the gap written to the spool
# <SPUD_HOME>/.spud/hook-errors.jsonl and drained into `hook.error` events by the next
# successful hook or CLI command.  One short BEGIN IMMEDIATE transaction per hook.

HOOK_EVENTS = ("PreToolUse", "PostToolUse", "SubagentStart", "SubagentStop", "SessionStart", "Stop")
