class HookError(Exception):
    """A hook could not do its job (malformed payload, mismatched event)."""


class HookOutput:
    def __init__(self, obj=None, exit_code=EXIT_OK):
        self.obj = obj
        self.exit_code = exit_code


SILENT = HookOutput()


def pre_decision(decision, reason):
    return HookOutput({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": decision, "permissionDecisionReason": reason}})


# -- the spool: a recording hook's gap, written later as a hook.error event ----------


def spool_path(ctx):
    return ctx.home / ".spud" / "hook-errors.jsonl"


@contextlib.contextmanager
def spool_lock(ctx):
    fd = os.open(str(ctx.home / ".spud" / "hook-errors.lock"), os.O_RDWR | os.O_CREAT, 0o644)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def spool_write(ctx, record):
    """Append one gap; only when .spud/ exists (before `spud init` there is nothing to drain into)."""
    if not (ctx.home / ".spud").is_dir():
        return False
    with spool_lock(ctx):
        with open(spool_path(ctx), "a", encoding="utf-8") as f:
            f.write(json.dumps(record) + "\n")
    return True


def spool_drain(ctx):
    """Move every spooled gap into a hook.error event.  Returns the count."""
    path = spool_path(ctx)
    if not ctx.db_path.is_file() or not path.is_file() or path.stat().st_size == 0:
        return 0
    with spool_lock(ctx):
        lines = [l for l in path.read_text(encoding="utf-8").splitlines() if l.strip()]
        with open(path, "w", encoding="utf-8"):
            pass
    if not lines:
        return 0
    records = []
    for line in lines:
        try:
            record = json.loads(line)
            records.append(record if isinstance(record, dict) else {"error": "spool record is not an object: %r" % line[:200]})
        except ValueError:
            records.append({"error": "unreadable spool line: %r" % line[:200]})
    try:
        con = connect(ctx)
        try:
            with write_txn(con):
                for r in records:
                    agent_id = r.get("agent_id") if isinstance(r.get("agent_id"), str) and r.get("agent_id") else None
                    member = con.execute("SELECT * FROM members WHERE agent_id = ?", (agent_id,)).fetchone() if agent_id else None
                    write_event(con, r.get("at") or now(), "hook:%s" % (r.get("event") or "unknown"), "hook.error", str(r.get("error", "")),
                                ticket_id=member["ticket_id"] if member else None, member_id=member["id"] if member else None,
                                agent_id=agent_id, data=r)
        finally:
            con.close()
    except Exception:
        with spool_lock(ctx):
            with open(path, "a", encoding="utf-8") as f:
                for line in lines:
                    f.write(line + "\n")
        raise
    return len(records)


# -- paths: the rule of Law 5 (deliverables) and Law 1 (Spud's own set) ---------------


def glob_to_regex(glob):
    """Repository-relative globs: `*` and `?` stay inside a path segment, `**` crosses segments."""
    i, n, out = 0, len(glob), []
    while i < n:
        c = glob[i]
        if c == "*":
            if glob.startswith("**/", i):
                out.append("(?:.*/)?")
                i += 3
            elif glob.startswith("**", i):
                out.append(".*")
                i += 2
            else:
                out.append("[^/]*")
                i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            j = glob.find("]", i + 1)
            if j == -1:
                out.append("\\[")
                i += 1
            else:
                inner = glob[i + 1 : j]
                if inner.startswith("!"):
                    inner = "^" + inner[1:]
                out.append("[" + inner.replace("\\", "\\\\") + "]")
                i = j + 1
        else:
            out.append(re.escape(c))
            i += 1
    return "^" + "".join(out) + "$"


def path_matches_glob(rel, glob, fold=False):
    if glob.endswith("/"):
        glob += "**"
    return re.fullmatch(glob_to_regex(glob), rel, re.IGNORECASE if fold else 0) is not None


_CASE_CACHE = {}


def case_insensitive_fs(path):
    """True when the filesystem holding `path` ignores case (macOS by default): then
    `Ledger/x` is `ledger/x` and the path rule must fold case (Rooster's HIGH-2)."""
    key = str(path)
    if key not in _CASE_CACHE:
        swapped = key.swapcase()
        try:
            _CASE_CACHE[key] = swapped != key and os.path.exists(swapped) and os.path.samefile(key, swapped)
        except OSError:
            _CASE_CACHE[key] = False
    return _CASE_CACHE[key]


def folds_case(root):
    """case_insensitive_fs for a project root, asked per root (a worktree elsewhere may sit on a case-sensitive volume)
    of the root itself or, when it does not exist yet, of its nearest existing ancestor, whose filesystem it will be on."""
    cur = str(root)
    while not os.path.isdir(cur):
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    return case_insensitive_fs(cur)


HARNESS_FILES_RE = re.compile(r"/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/subagents/", re.IGNORECASE)


def harness_file(path):
    """The harness's subagent transcripts and meta files (<project>/<session>/subagents/...):
    the ledger binds identities from them, so nobody but Claude Code writes them."""
    p = path.replace("\\", "/")
    return HARNESS_FILES_RE.search(p) is not None or re.search(r"/agent-[0-9a-f]+\.(?:meta\.json|jsonl)$", p, re.IGNORECASE) is not None


# -- worktrees: every checkout of the home repository, wherever `git worktree add` put it (SPD-016) -----------------

GIT_REDIRECTS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE")  # what could point a git call away from the home
_WORKTREES = {}  # home -> its worktree list, once per process


def worktrees_fingerprint(home):
    """What changes when a worktree of the home is added, moved, repaired or removed, read without running git: the
    stat of <home>/.git/worktrees and of each worktrees/<id>/gitdir, the file gitrepository-layout(5) documents as
    the path back to that worktree.  None when <home>/.git is not a directory (a gitfile), where only git can say."""
    git_dir = os.path.join(str(home), ".git")
    if not os.path.isdir(git_dir):
        return None
    admin = os.path.join(git_dir, "worktrees")
    try:
        names = sorted(os.listdir(admin))
        stamp = os.stat(admin).st_mtime_ns
    except FileNotFoundError:
        return ["no linked worktrees"]
    out = [stamp]
    for name in names:
        try:
            st = os.stat(os.path.join(admin, name, "gitdir"))
            out.append([name, st.st_mtime_ns, st.st_size])
        except FileNotFoundError:
            out.append([name, None, None])
    return out


def git_worktree_list(home):
    """The paths `git worktree list --porcelain` names for the home, the main checkout first.  Raises HookError when
    git cannot give them, which fails an enforcing hook closed."""
    env = {k: v for k, v in os.environ.items() if k not in GIT_REDIRECTS}
    try:
        proc = subprocess.run(["git", "-C", str(home), "worktree", "list", "--porcelain", "-z"], capture_output=True, env=env, timeout=10)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise HookError("cannot list the worktrees of %s, so no path can be checked against them: %s" % (home, e))
    if proc.returncode != 0:
        raise HookError("cannot list the worktrees of %s, so no path can be checked against them: git worktree list exited %d: %s"
                        % (home, proc.returncode, os.fsdecode(proc.stderr).strip()))
    return [os.fsdecode(field[len(b"worktree "):]) for field in proc.stdout.split(b"\0") if field.startswith(b"worktree ")]


def home_worktrees(home):
    """Every worktree git names for the home ([] when the home has no .git of its own), kept in <home>/.spud/worktrees.json
    under the fingerprint it was listed at, so a hook runs git only after the worktrees change (about 8 ms with the
    subprocess import).  A cache that is missing, unreadable or stale is listed anew; one that cannot be written is
    left unwritten."""
    key = str(home)
    if key in _WORKTREES:
        return _WORKTREES[key]
    if not os.path.lexists(os.path.join(key, ".git")):
        _WORKTREES[key] = []
        return []
    fingerprint = worktrees_fingerprint(home)
    cache = os.path.join(key, ".spud", "worktrees.json")
    listed = None
    if fingerprint is not None:
        with contextlib.suppress(OSError, ValueError):
            with open(cache, encoding="utf-8") as f:
                stored = json.load(f)
            if isinstance(stored, dict) and stored.get("fingerprint") == fingerprint and isinstance(stored.get("worktrees"), list) \
                    and all(isinstance(w, str) for w in stored["worktrees"]):
                listed = stored["worktrees"]
    if listed is None:
        listed = git_worktree_list(home)
        if fingerprint is not None and os.path.isdir(os.path.dirname(cache)):
            tmp = "%s.%d.tmp" % (cache, os.getpid())
            with contextlib.suppress(OSError):
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump({"fingerprint": fingerprint, "worktrees": listed}, f)
                os.replace(tmp, cache)
            with contextlib.suppress(OSError):
                os.unlink(tmp)
    _WORKTREES[key] = listed
    return listed


def file_identity(path):
    """(st_dev, st_ino) of what `path` names, symlinks followed; None when there is nothing to stat.  Every spelling the
    filesystem resolves to one directory has its identity: a case variant or an NFD spelling on APFS, a simple case
    fold (U+017F for s, U+212A for k), the /System/Volumes/Data firmlink prefix on macOS, a symlink (SPD-029)."""
    try:
        st = os.stat(path)
    except (OSError, ValueError):
        return None
    return st.st_dev, st.st_ino


def same_entry(base, spelled, canonical):
    """True when the components `spelled` under `base` name the directory the components `canonical` do: the same
    strings, the same file, or, where that directory does not exist yet on a case-insensitive filesystem, the same
    strings case-folded."""
    if spelled == canonical:
        return True
    ident = file_identity(os.path.join(base, *canonical))
    if ident is not None:
        return file_identity(os.path.join(base, *spelled)) == ident
    return case_insensitive_fs(base) and [s.casefold() for s in spelled] == [c.casefold() for c in canonical]


def map_into_repository(home, path, worktrees=()):
    """(root, repository-relative path) when `path` (absolute, normalized) lies in Spud's home or in one of its
    worktrees: one git names (SPD-016), wherever it is, or a directory under .claude/worktrees/<name>/; None when
    outside.  The root nearest the path wins, so a worktree inside the home maps to itself, not to the home.

    A root is found by file identity, not by spelling (SPD-029): the nearest existing ancestor of the path whose
    (st_dev, st_ino) is a root's, the components below it being the repository-relative path, so any spelling of the
    root the filesystem honours is the root.  A root with nothing to stat (a worktree git still lists after its
    directory went) is matched by spelling as before.  A generated root spelled another way (Ledger, reportſ) is
    named ledger or reports when it is the same directory."""
    roots, spelled = {}, []
    for root in (str(home), *worktrees):
        ident = file_identity(root)
        if ident is not None:
            roots.setdefault(ident, root)
        else:
            for b in (root, os.path.realpath(root)):
                if b not in spelled:
                    spelled.append(b)
    best = None
    below, cur = [], path
    while True:
        ident = file_identity(cur)
        if ident is not None and ident in roots:
            best = (roots[ident], below[::-1])
            break
        parent, name = os.path.split(cur)
        if parent == cur:
            break
        below.append(name)
        cur = parent
    for base in spelled:
        rel = os.path.relpath(path, base)
        if rel == ".." or rel.startswith(".." + os.sep):
            continue
        parts = [] if rel == "." else rel.split(os.sep)
        if best is None or len(parts) < len(best[1]):
            best = (base, parts)
    if best is None:
        return None
    base, parts = best
    if len(parts) > 3 and same_entry(base, parts[:2], [".claude", "worktrees"]):
        base, parts = os.path.join(base, ".claude", "worktrees", parts[2]), parts[3:]
    named = GENERATED_ROOTS + (STATE_DIR,)
    if parts and parts[0] not in named:
        for canonical in named:
            if same_entry(base, parts[:1], [canonical]):
                parts = [canonical] + parts[1:]
                break
    return base, "/".join(parts)


def repository_paths(ctx, path, cwd):
    """Every reading of `path` that lands inside the repository: the lexical path and, when
    a symlink changes it, the real one.  Relative paths resolve against the payload's cwd.
    The real path is taken of the path as given too, since the kernel resolves a symlink
    before a `..` after it (tests/link/.. is the link target's parent) where normpath drops
    the pair (SPD-029)."""
    p = os.path.expanduser(path) if path.startswith("~") else path
    if not os.path.isabs(p):
        p = os.path.join(cwd or os.getcwd(), p)
    lexical = os.path.normpath(p)
    candidates = [lexical]
    for real in (os.path.realpath(lexical), os.path.realpath(p)):
        if real not in candidates:
            candidates.append(real)
    worktrees = home_worktrees(ctx.home)
    out = []
    for c in candidates:
        mapped = map_into_repository(ctx.home, c, worktrees)
        if mapped and mapped not in out:
            out.append(mapped)
    return out


def path_reason(rel, member, ref, fold=False):
    """None when the actor may write the repository path `rel`, else the reason.  The
    generated roots are matched whatever the case (a case variant is refused on every
    filesystem), case-folded rather than lower-cased so that the simple folds APFS honours
    (reportſ is reports) count too (SPD-029); globs fold case only where the filesystem does."""
    generated = rel.split("/")[0].casefold() in GENERATED_ROOTS
    if member is None:
        if any(path_matches_glob(rel, g, fold) for g in SPUD_PATHS):
            return None
        if generated:
            return ("Law 5: %s is generated from the ledger database (ledger/** and reports/** are rendered by `spud render`);"
                    " Spud's hand-written set is %s; use the spud CLI for everything else" % (rel, ", ".join(SPUD_PATHS)))
        return ("Law 1: Spud never produces a deliverable; %s is inside the repository and outside Spud's own paths (%s),"
                " so a spudagent writes it" % (rel, ", ".join(SPUD_PATHS)))
    if generated:
        return ("Law 5: %s is outside every member's deliverables; ledger/** and reports/** are generated from the ledger database"
                " (rendered by `spud render`), so record through the CLI: spud member log | result | block, spud proposal file" % rel)
    globs = json.loads(member["deliverables"]) if member["deliverables"] else []
    if any(path_matches_glob(rel, g, fold) for g in globs):
        return None
    return "Law 5: %s is not among %s's deliverables (%s); write only there, or ask your parent to extend them" % (rel, ref, ", ".join(globs) or "none")


def in_state_dir(rel):
    """True when the repository path lies in the ledger state directory at its root (or is that directory).  The first
    component is case-folded, like a generated root's, so a case variant or a simple fold (U+017F for s) is refused on
    every filesystem; map_into_repository has already named a same-file spelling of it canonically (SPD-031).  A state
    directory deeper in the tree is no ledger's (bin/spud keeps its state at the root of its home) and stays under the globs."""
    return rel.split("/", 1)[0].casefold() == STATE_DIR


def state_dir_reason(rel):
    return DB_REASON % ("%s is in the ledger state directory at a project root, which holds the database, its WAL and shm files, the worktree"
                        " list cache, the backups and the launcher's cached bytecode; only the CLI writes there, whatever the deliverables" % rel)


def edit_reason(ctx, con, caller_agent_id, caller_member, path, cwd):
    """The path rule for a Write/Edit target (and for a shell redirection target).  A path in the ledger state directory
    at any project root, by any reading of it, is refused to everyone before the binding, Law 1 and glob checks (SPD-031)."""
    p = os.path.expanduser(path) if path.startswith("~") else path
    if not os.path.isabs(p):
        p = os.path.join(cwd or os.getcwd(), p)
    for candidate in (os.path.normpath(p), os.path.realpath(p)):
        if harness_file(candidate):
            return ("%s is one of the harness's subagent files (<project>/<session>/subagents/...): the ledger binds identities from them,"
                    " so nothing but Claude Code writes them" % candidate), None
    inside = repository_paths(ctx, path, cwd)
    if not inside:
        return None, None
    for _root, rel in inside:
        if in_state_dir(rel):
            return state_dir_reason(rel), rel
    if caller_agent_id and caller_member is None:
        return ("your agent_id %s is not bound to a member yet (the PostToolUse(Agent) hook binds a background spawn right after launch;"
                " a foreground spawn is bound at its first tool call or at its stop), so %s cannot be checked against your deliverables" % (caller_agent_id, inside[0][1])), inside[0][1]
    ref = member_ref(con, caller_member["id"]) if caller_member else "Spud"
    for root, rel in inside:
        reason = path_reason(rel, caller_member, ref, folds_case(root))
        if reason:
            return reason, rel
    return None, inside[0][1]


# -- shell analysis for PreToolUse(Bash) ---------------------------------------------


class ShellAnalysis:
    """What a command line would run: (kind, detail) findings per simple command, the output
    redirection targets with the working directory in force, and whether every simple
    command is a spud call."""

    def __init__(self, cwd=None):
        self.findings = []
        self.kinds = []
        self.redirects = []
        self.vars = {}
        self.cwd = cwd
        self.unparseable = False

    @property
    def all_spud(self):
        """Every simple command is a spud call (a `cd` beside it changes nothing that matters)."""
        return "spud" in self.kinds and all(k in ("spud", "cd") for k in self.kinds) and not self.unparseable


def strip_heredocs(command):
    """Remove here-document bodies from the command text; return (text, bodies) in order."""
    lines = command.split("\n")
    out, bodies = [], []
    i = 0
    while i < len(lines):
        line = lines[i]
        out.append(line)
        words = [(m.group(1) if m.group(1) is not None else (m.group(2) if m.group(2) is not None else m.group(3).lstrip("\\"))) for m in HEREDOC_RE.finditer(line)]
        i += 1
        for word in words:
            body = []
            while i < len(lines) and lines[i].lstrip("\t") != word:
                body.append(lines[i])
                i += 1
            bodies.append("\n".join(body))
            i += 1
    return "\n".join(out), bodies


def split_substitutions(command):
    """Lift `$(...)` and backtick bodies (outside single quotes) out of the command; each
    becomes its own command to analyse and a placeholder word in the outer text."""
    out, inner = [], []
    i, n = 0, len(command)
    state = None
    while i < n:
        c = command[i]
        if state == "'":
            out.append(c)
            if c == "'":
                state = None
            i += 1
            continue
        if c == "\\" and i + 1 < n:
            out.append(command[i : i + 2])
            i += 2
            continue
        if state is None and c == "'":
            state = "'"
            out.append(c)
            i += 1
            continue
        if c == '"':
            state = None if state == '"' else '"'
            out.append(c)
            i += 1
            continue
        if c == "$" and command.startswith("$(", i) and not command.startswith("$((", i):
            depth, j = 0, i + 1
            while j < n:
                if command[j] == "(":
                    depth += 1
                elif command[j] == ")":
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            inner.append(command[i + 2 : j])
            out.append(SUBST)
            i = j + 1
            continue
        if c == "`":
            j = command.find("`", i + 1)
            if j == -1:
                j = n
            inner.append(command[i + 1 : j])
            out.append(SUBST)
            i = j + 1
            continue
        out.append(c)
        i += 1
    return "".join(out), inner


def shell_tokens(text):
    lx = shlex.shlex(text, posix=True, punctuation_chars=True)
    lx.whitespace_split = True
    try:
        return list(lx)
    except ValueError:
        return None


def split_segments(tokens):
    segments, current = [], []
    for t in tokens:
        if SEPARATOR_RE.match(t):
            if current:
                segments.append(current)
            current = []
        else:
            current.append(t)
    if current:
        segments.append(current)
    return segments


def separate_redirects(tokens):
    """Drop redirection operators and their operands; return (words, output targets)."""
    words, targets = [], []
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if t in OUT_REDIRECTS:
            operand = tokens[i + 1] if i + 1 < len(tokens) else None
            if operand is not None and not re.fullmatch(r"-|\d+", operand) and not operand.startswith("&"):
                targets.append(operand)
            i += 2
            continue
        if t in IN_REDIRECTS:
            i += 2
            continue
        if re.fullmatch(r"\d+", t) and i + 1 < len(tokens) and tokens[i + 1] in (OUT_REDIRECTS | IN_REDIRECTS):
            i += 1
            continue
        words.append(t)
        i += 1
    return words, targets


def strip_wrapper(words):
    """`env`, `nohup`, `xargs`, `timeout 10`, `sudo -u x`, ...: drop the wrapper and its options."""
    name = os.path.basename(words[0])
    rest = words[1:]
    if name == "timeout" and rest and re.fullmatch(r"\d+(?:\.\d+)?[smhd]?", rest[0]):
        rest = rest[1:]
    while rest:
        w = rest[0]
        if w.startswith("-"):
            if w in ("-u", "-n", "-I", "-L", "-P", "-s", "-k", "-C", "-d", "-a", "-g", "-i") and len(rest) > 1 and name in ("sudo", "nice", "xargs", "timeout", "doas", "ionice", "stdbuf"):
                rest = rest[2:]
            else:
                rest = rest[1:]
            continue
        if name == "env" and ASSIGNMENT_RE.match(w):
            rest = rest[1:]
            continue
        break
    return rest


def git_verb(words):
    i = 1
    while i < len(words):
        w = words[i]
        if w in GIT_GLOBAL_VALUE_FLAGS:
            i += 2
            continue
        if w.startswith("-"):
            i += 1
            continue
        return w, words[i + 1 :]
    return None, []


def flag_list_refused(verb, args, read_flags, value_flags):
    """`git branch`/`git tag` listing forms are reads; a name or a modifying flag writes."""
    positional_allowed = False
    i = 0
    while i < len(args):
        w = args[i]
        if "=" in w and w.split("=", 1)[0] in value_flags:
            positional_allowed = True
            i += 1
            continue
        if w in value_flags:
            positional_allowed = True
            i += 2
            continue
        if w in read_flags:
            if w in ("--list", "-l"):
                positional_allowed = True
            i += 1
            continue
        if w.startswith("-"):
            return verb
        if not positional_allowed:
            return verb
        i += 1
    return None


def git_refused(verb, args):
    """The verb when Law 7 refuses it for a spudagent, else None."""
    if verb is None:
        return None
    if verb in GIT_WRITE_VERBS:
        return verb
    if verb == "stash":
        return None if (args and args[0] in ("list", "show")) else verb
    if verb == "worktree":
        return None if (args and args[0] == "list") else verb
    if verb == "remote":
        return verb if (args and args[0] in ("add", "remove", "rm", "rename", "set-url", "set-head", "set-branches", "prune", "update")) else None
    if verb == "reflog":
        return verb if (args and args[0] in ("expire", "delete")) else None
    if verb == "branch":
        return flag_list_refused(verb, args, BRANCH_READ_FLAGS, BRANCH_READ_VALUE_FLAGS)
    if verb == "tag":
        return flag_list_refused(verb, args, TAG_READ_FLAGS, TAG_READ_VALUE_FLAGS)
    if verb == "config":
        positionals = 0
        i = 0
        while i < len(args):
            w = args[i]
            if w in CONFIG_WRITE_FLAGS:
                return verb
            if w in CONFIG_VALUE_FLAGS:
                i += 2
                continue
            if w.startswith("-"):
                i += 1
                continue
            positionals += 1
            i += 1
        return verb if positionals >= 2 else None
    return None


def parse_spud_call(words):
    """The global options and the command words of a `spud` invocation."""
    call = {"actor": None, "command": None, "subcommand": None, "rest": [], "help": False}
    i = 0
    while i < len(words):
        w = words[i]
        if w == "--as":
            call["actor"] = words[i + 1] if i + 1 < len(words) else ""
            i += 2
            continue
        if w.startswith("--as="):
            call["actor"] = w[5:]
            i += 1
            continue
        if w in ("--version", "-h", "--help"):
            call["help"] = True
            i += 1
            continue
        if w == "--json":
            i += 1
            continue
        if call["command"] is None:
            call["command"] = w
        elif call["subcommand"] is None and call["command"] in ("config", "settings", "ticket", "member", "proposal", "handoff", "report"):
            call["subcommand"] = w
        else:
            call["rest"].append(w)
        i += 1
    return call


def python_interpreter_args(args):
    """(code, module, stdin_script, script, script_args) for a python command line."""
    i = 0
    while i < len(args):
        w = args[i]
        if w == "-c":
            return args[i + 1] if i + 1 < len(args) else "", None, False, None, []
        if w == "-m":
            return None, args[i + 1] if i + 1 < len(args) else "", False, None, []
        if w == "-":
            return None, None, True, None, []
        if w.startswith("-"):
            i += 2 if w in ("-X", "-W", "-Q") else 1
            continue
        return None, None, False, w, args[i + 1 :]
    return None, None, False, None, []


def spud_launcher(script, cwd):
    """True when running `script` runs a spud launcher however its path is spelled (SPD-029): Law 6's refusals and
    Law 5's `--as` check depend on seeing the call.  Its name case-folded is spud (bin/SPUD and bin/ſpud are bin/spud
    on macOS), or the name its symlinks resolve to is (the launcher finds its program from its own real path, so a
    link by any name runs it).  A relative path resolves against the directory the shell would be in."""
    if os.path.basename(script).casefold() == "spud":
        return True
    if "$" in script or "`" in script or SUBST in script:
        return False
    p = os.path.expanduser(script) if script.startswith("~") else script
    if not os.path.isabs(p):
        if not cwd:
            return False
        p = os.path.join(cwd, p)
    return os.path.basename(os.path.realpath(p)).casefold() == "spud"


def analyse_command(command, analysis=None, depth=0):
    """Walk every simple command the shell would run, recursing into substitutions,
    `sh -c` strings, `eval` and here-documents fed to a shell."""
    a = analysis or ShellAnalysis()
    if depth > 6:
        return a
    text, bodies = strip_heredocs(command)
    outer, inner = split_substitutions(text)
    for sub in inner:
        analyse_command(sub, a, depth + 1)
    tokens = shell_tokens(outer)
    if tokens is None:
        a.unparseable = True
        return a
    body_index = 0
    for seg in split_segments(tokens):
        seg_bodies, cleaned = [], []
        k = 0
        while k < len(seg):
            if seg[k] in ("<<", "<<-"):
                if body_index < len(bodies):
                    seg_bodies.append(bodies[body_index])
                    body_index += 1
                k += 2
                continue
            cleaned.append(seg[k])
            k += 1
        analyse_segment(cleaned, seg_bodies, a, depth)
    return a


def analyse_segment(tokens, bodies, a, depth):
    words, targets = separate_redirects(tokens)
    for t in targets:
        a.redirects.append((t, a.cwd))
    while words:
        w = words[0]
        if w in RESERVED_WORDS:
            words = words[1:]
        elif ASSIGNMENT_RE.match(w):
            name, value = w.split("=", 1)
            a.vars[name] = value
            words = words[1:]
        elif os.path.basename(w) in WRAPPERS and w not in a.vars:
            words = strip_wrapper(words)
        else:
            break
    if not words:
        return
    cmd = words[0]
    if VARREF_RE.match(cmd):
        name = cmd.strip("${}")
        if name in a.vars:
            expanded = shell_tokens(a.vars[name]) or []
            if not expanded:
                return
            words = expanded + words[1:]
            cmd = words[0]
        else:
            a.kinds.append("var")
            a.findings.append(("var", cmd))
            return
    if SUBST in cmd:
        # The command word comes out of `$(...)` or backticks (Rooster's MEDIUM-3): unresolvable, like a bare variable.
        a.kinds.append("var")
        a.findings.append(("var", "$(...)"))
        return
    base = os.path.basename(cmd).casefold()
    if base != "spud" and "/" in cmd and spud_launcher(cmd, a.cwd):
        base = "spud"  # a symlink to bin/spud run by its path, whatever its own name (SPD-029)
    if base == "git":
        verb, args = git_verb(words)
        a.kinds.append("git")
        a.findings.append(("git", (verb, git_refused(verb, args))))
    elif base in SHELLS:
        a.kinds.append("shell")
        i = 1
        while i < len(words):
            w = words[i]
            if w.startswith("-") and "c" in w[1:] and not w.startswith("--"):
                if i + 1 < len(words):
                    analyse_command(words[i + 1], a, depth + 1)
                break
            if not w.startswith("-"):
                break
            i += 1
        for body in bodies:
            analyse_command(body, a, depth + 1)
    elif base == "eval":
        a.kinds.append("eval")
        analyse_command(" ".join(words[1:]), a, depth + 1)
    elif base in ("sqlite3", "sqlite"):
        a.kinds.append("db")
        a.findings.append(("db", cmd))
    elif PYTHON_RE.match(base):
        code, module, stdin_script, script, script_args = python_interpreter_args(words[1:])
        if (code and "sqlite" in code.lower()) or (module and "sqlite" in module.lower()) or (stdin_script and any("sqlite" in b.lower() for b in bodies)):
            a.kinds.append("db")
            a.findings.append(("db", cmd))
        elif script and spud_launcher(script, a.cwd):
            a.kinds.append("spud")
            a.findings.append(("spud", parse_spud_call(script_args)))
        else:
            a.kinds.append("other")
    elif base in JS_RUNTIMES:
        if any("sqlite" in w.lower() for w in words[1:]) or any("sqlite" in b.lower() for b in bodies):
            a.kinds.append("db")
            a.findings.append(("db", cmd))
        else:
            a.kinds.append("other")
    elif base == "spud":
        a.kinds.append("spud")
        a.findings.append(("spud", parse_spud_call(words[1:])))
    elif base == "tee":
        a.kinds.append("tee")
        for w in words[1:]:
            if not w.startswith("-"):
                a.redirects.append((w, a.cwd))
    elif base == "cd":
        a.kinds.append("cd")
        target = words[1] if len(words) > 1 else "~"
        if "$" in target or "`" in target or target == "-":
            a.cwd = None
        elif target.startswith("~"):
            a.cwd = os.path.expanduser(target)
        elif os.path.isabs(target):
            a.cwd = os.path.normpath(target)
        elif a.cwd:
            a.cwd = os.path.normpath(os.path.join(a.cwd, target))
        else:
            a.cwd = None
    else:
        a.kinds.append("other")


def actor_is_self(con, actor, caller_member, caller_agent_id):
    if actor == caller_agent_id:
        return True
    ticket = get_ticket_by_id(con, caller_member["ticket_id"])
    return actor in ("%s/%s" % (ticket["team_key"], caller_member["name"]), "%s/%s" % (ticket["team_key"], caller_member["lineage"]))


def bash_reason(ctx, con, caller_agent_id, caller_member, command, cwd):
    """(reason or None, analysis) for a Bash command line."""
    db_reason = DB_REASON
    if DB_PATH_RE.search(command):
        return db_reason % "the command names ledger.db or .spud/", None
    analysis = analyse_command(command, ShellAnalysis(cwd=cwd))
    if analysis.unparseable:
        return None, analysis
    who = ("%s (agent_id %s)" % (member_ref(con, caller_member["id"]), caller_agent_id)) if caller_member else ("agent_id %s" % caller_agent_id if caller_agent_id else "Spud")
    for kind, detail in analysis.findings:
        if kind == "db":
            return db_reason % ("`%s`" % detail), analysis
        if kind == "spud" and detail["command"] == "hook":
            return "`spud hook` is the harness's: hooks run from .claude/settings.json (spud settings sync), never from Bash", analysis
        if not caller_agent_id:
            if kind == "spud" and detail["actor"] not in (None, "spud") and (detail["command"], detail["subcommand"]) in MEMBER_OWN_COMMANDS:
                return ("Law 5: `--as %s` from Spud's own session would write a member's own sections (log, result, block, proposals) in its name;"
                        " members record themselves (the SubagentStop hold sees to it), Spud records verdicts with `spud --as spud member finish`" % detail["actor"]), analysis
            continue
        if kind == "git":
            verb, refused = detail
            if refused:
                return ("Law 7: spudagents never run `git %s` (commit, add, stash, checkout, switch, rebase, reset, push, merge, cherry-pick,"
                        " worktree, branch, tag, pull, apply, restore, rm, mv, clean ...); Spud commits, after the outcome is recorded" % verb), analysis
        elif kind == "var":
            return "the command word %s comes from a variable or a substitution the hook cannot resolve; spell the command out" % detail, analysis
        elif kind == "spud":
            call = detail
            if call["actor"] == "spud":
                return "Law 6: `--as spud` is Spud's; a spudagent acts as itself (--as %s)" % (caller_agent_id,), analysis
            if call["command"] in SPUD_ONLY_COMMANDS or (call["command"], call["subcommand"]) in SPUD_ONLY_SUBCOMMANDS:
                what = call["command"] + ((" " + call["subcommand"]) if call["subcommand"] and (call["command"], call["subcommand"]) in SPUD_ONLY_SUBCOMMANDS else "")
                return ("Law 6: `spud %s` is Spud's (tickets are created, moved and edited by Spud alone; init, migrate, import, render, backup,"
                        " settings sync, config sync and member resum are ledger-wide, and schedule installs the ledger's daily backup on this Mac);"
                        " file a proposal instead: spud proposal file --as %s" % (what, caller_agent_id)), analysis
            if call["actor"] is not None:
                if caller_member is None:
                    return ("your agent_id %s is not bound to a member yet, so `--as %s` cannot be verified (a background spawn is bound right"
                            " after launch by PostToolUse(Agent); a foreground spawn only at its stop)" % (caller_agent_id, call["actor"])), analysis
                if not actor_is_self(con, call["actor"], caller_member, caller_agent_id):
                    return ("`--as %s` does not resolve to the caller's own member %s; use `--as %s`"
                            % (call["actor"], who, caller_agent_id)), analysis
    for target, target_cwd in analysis.redirects:
        if "$" in target or "`" in target or SUBST in target:
            if caller_agent_id:
                return "the redirection target %s holds a variable or substitution the hook cannot resolve; spell the path out" % target, analysis
            continue
        if target_cwd is None and not os.path.isabs(os.path.expanduser(target)):
            if caller_agent_id:
                return "the redirection target %s is relative to a directory the hook cannot follow (`cd` into a variable); use an absolute path" % target, analysis
            continue
        reason, rel = edit_reason(ctx, con, caller_agent_id, caller_member, target, target_cwd or cwd)
        if reason:
            law_1 = not caller_agent_id and not (rel is not None and in_state_dir(rel))  # the state directory is refused in the database's words, not Law 1's
            return ("Law 1: a redirection or tee into %s: %s" if law_1 else "a redirection or tee into %s: %s") % (target, reason), analysis
    return None, analysis


# -- the PreToolUse handlers ---------------------------------------------------------


def deny_and_record(con, at, payload, reason, caller_agent_id, caller_member, ticket_id=None, extra=None):
    data = {"hook_event_name": "PreToolUse", "tool_name": payload.get("tool_name"), "tool_use_id": payload.get("tool_use_id"), "reason": reason}
    data.update(extra or {})
    write_event(con, at, "hook:PreToolUse", "hook.denied", reason,
                ticket_id=ticket_id if ticket_id is not None else (caller_member["ticket_id"] if caller_member else None),
                member_id=caller_member["id"] if caller_member else None, agent_id=caller_agent_id, data=data)
    return pre_decision("deny", reason)


def hook_agent_spawn(ctx, con, at, payload, tool_input, caller_agent_id, caller_member):
    tool_use_id = payload.get("tool_use_id")
    description = tool_input.get("description") if isinstance(tool_input.get("description"), str) else ""
    model = tool_input.get("model")
    subagent_type = tool_input.get("subagent_type")
    background = tool_input.get("run_in_background")
    extra = {"description": description, "subagent_type": subagent_type, "model": model}
    if not isinstance(tool_use_id, str) or not tool_use_id:
        return deny_and_record(con, at, payload, "malformed PreToolUse(Agent) payload: tool_use_id is missing, so the spawn cannot be recorded", caller_agent_id, caller_member, extra=extra)
    ticket = member = None
    reason = None
    m = DESCRIPTION.match(description)
    if not m:
        reason = "the description must be `SPUD-nnn/<Name> (<lineage>, <persona>)`: the team key, the pool name, the lineage and the persona of a planned member (got %r)" % description
    else:
        team, name, lineage, persona = m.group("team"), m.group("name"), m.group("lineage"), m.group("persona")
        ticket = con.execute("SELECT * FROM tickets WHERE team_key = ?", (team,)).fetchone()
        if ticket is None:
            reason = "no team %s in the ledger (the ticket must exist before a member is planned on it)" % team
        else:
            member = con.execute("SELECT * FROM members WHERE ticket_id = ? AND name = ?", (ticket["id"], name)).fetchone()
            if member is None:
                reason = "no planned member named %s on %s; plan it first with `spud member new` (Law 2: no brief, no spudagent)" % (name, team)
    if reason is None:
        ref = "%s/%s" % (ticket["team_key"], member["name"])
        limits = ctx.limits
        pending = con.execute(
            "SELECT tool_use_id, at FROM spawn_requests WHERE member_id = ? AND decision = 'allow' AND agent_id IS NULL AND tool_use_id != ? ORDER BY at, rowid LIMIT 1",
            (member["id"], tool_use_id),
        ).fetchone()
        if member["status"] != "planned":
            reason = "%s is %s, not planned; a spawned member is never spawned twice, a re-spawn is a new member row (spud member new)" % (ref, member["status"])
        elif pending is not None:
            # The first allow reserves the row (Rooster's HIGH-1): until that spawn binds, a second
            # Agent call for the same member would run a copy the ledger cannot see or count.  The
            # way out names the caller's own actor (SPD-028): a spudagent cannot run `--as spud`
            # (Law 6 refuses it inside a subagent), so only Spud's own root row offers --next.
            fail = ("`spud --as %s member finish %s --status failed --outcome '<why>'`" % (caller_agent_id, ref)) if caller_agent_id else (
                    "`spud --as spud member finish %s --status failed --outcome '<why>' [--next '<what happens next>']`" % ref)
            reason = ("%s was already allowed to spawn at %s (tool_use_id %s) and is not yet bound; a planned member is spawned once."
                      " If that spawn failed in the harness, record it with %s"
                      " and plan a new member: a re-spawn is a new row" % (ref, pending["at"], pending["tool_use_id"], fail))
        elif member["lineage"] != lineage:
            reason = "lineage %s in the description, but %s is planned as %s" % (lineage, ref, member["lineage"])
        elif member["persona"] != persona:
            reason = "persona %s in the description, but %s is planned as a %s" % (persona, ref, member["persona"])
        elif not (member["brief"] or "").strip():
            reason = "Law 2: %s has no brief; no brief, no spudagent" % ref
        elif subagent_type == "fork" or tool_input.get("fork"):
            reason = "Law 3: a fork is refused (it inherits Spud's model and skips the depth cap); spawn subagent_type %s with an explicit model" % member["agent_type"]
        elif tool_input.get("isolation"):
            reason = "Law 3: isolation %r is refused; spudagents share the session's working tree so their ledger writes land in the one ledger" % tool_input.get("isolation")
        elif not model:
            reason = "Law 3: model is missing; every spawn names its model tier explicitly (%s is planned on %s)" % (ref, member["model"])
        elif model == "inherit":
            reason = "Law 3: model inherit is refused; name the tier (%s is planned on %s)" % (ref, member["model"])
        elif model != member["model"]:
            reason = "Law 3: model must equal the planned tier %s, not %s (change the plan with `spud member edit --model` first)" % (member["model"], model)
        elif subagent_type != member["agent_type"]:
            reason = "agent_type: %s is planned as %s, the call asks for subagent_type %s" % (ref, member["agent_type"], subagent_type)
        elif caller_agent_id and caller_member is None:
            reason = "caller agent_id %s is not bound to a member; only a bound member (or Spud, with no agent_id) spawns" % caller_agent_id
        elif (caller_member["id"] if caller_member else None) != member["parent_id"]:
            reason = "parent: %s's parent is %s, the caller is %s; a member is spawned by the parent that planned it" % (
                ref, member_ref(con, member["parent_id"]) or "Spud", member_ref(con, caller_member["id"]) if caller_member else "Spud")
        else:
            depth = member["lineage"].count(".") + 1
            parent_id = member["parent_id"]
            alive = con.execute("SELECT count(*) FROM members WHERE ticket_id = ? AND parent_id IS ? AND status IN ('planned','active')", (member["ticket_id"], parent_id)).fetchone()[0]
            cap_name = "root_fan_out" if parent_id is None else "child_fan_out"
            cap = limits[cap_name]
            total = con.execute("SELECT count(*) FROM members WHERE status IN ('planned','active')").fetchone()[0]
            if depth > limits["max_depth"]:
                reason = "Law 4: depth %d exceeds limits.max_depth %d" % (depth, limits["max_depth"])
            elif alive > cap:
                reason = "Law 4: fan-out: %d children alive under %s (this one included), limits.%s is %d; a child frees its slot when it finishes" % (
                    alive, member_ref(con, parent_id) or "Spud", cap_name, cap)
            elif total > limits["max_concurrent_total"]:
                reason = "Law 4: concurrency: %d members alive across every ticket (this one included), limits.max_concurrent_total is %d" % (total, limits["max_concurrent_total"])
    decision = "deny" if reason else "allow"
    con.execute(
        "INSERT INTO spawn_requests (tool_use_id, session_id, at, caller_agent_id, description, subagent_type, model, run_in_background, member_id, decision, reason)"
        " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        " ON CONFLICT(tool_use_id) DO UPDATE SET session_id = excluded.session_id, at = excluded.at, caller_agent_id = excluded.caller_agent_id,"
        " description = excluded.description, subagent_type = excluded.subagent_type, model = excluded.model, run_in_background = excluded.run_in_background,"
        " member_id = excluded.member_id, decision = excluded.decision, reason = excluded.reason",
        (tool_use_id, str(payload.get("session_id") or ""), at, caller_agent_id, description, subagent_type if isinstance(subagent_type, str) else None,
         model if isinstance(model, str) else None, None if background is None else int(bool(background)), member["id"] if member else None, decision, reason),
    )
    data = {"tool_use_id": tool_use_id, "subagent_type": subagent_type, "model": model, "run_in_background": background,
            "caller": member_ref(con, caller_member["id"]) if caller_member else "spud", "caller_agent_id": caller_agent_id}
    if decision == "allow":
        write_event(con, at, "hook:PreToolUse", "member.spawned", "spawn allowed: %s" % description, ticket_id=member["ticket_id"], member_id=member["id"], data=data)
        return pre_decision("allow", "spawn of %s recorded (%s)" % (description, tool_use_id))
    data["reason"] = reason
    if member is not None:
        write_event(con, at, "hook:PreToolUse", "member.spawn_denied", reason, ticket_id=member["ticket_id"], member_id=member["id"], data=data)
        return pre_decision("deny", reason)
    return deny_and_record(con, at, payload, reason, caller_agent_id, caller_member, ticket_id=ticket["id"] if ticket else None, extra={"description": description})


def hook_bash(ctx, con, at, payload, tool_input, caller_agent_id, caller_member):
    command = tool_input.get("command")
    if not isinstance(command, str) or not command.strip():
        return deny_and_record(con, at, payload, "malformed PreToolUse(Bash) payload: tool_input.command is missing", caller_agent_id, caller_member)
    reason, analysis = bash_reason(ctx, con, caller_agent_id, caller_member, command, payload.get("cwd") or None)
    if reason:
        return deny_and_record(con, at, payload, reason, caller_agent_id, caller_member, extra={"command": command[:2000]})
    if analysis is not None and analysis.all_spud and all(d["command"] in SPUD_COMMANDS or (d["command"] is None and d["help"]) for k, d in analysis.findings if k == "spud"):
        who = member_ref(con, caller_member["id"]) if caller_member else ("agent_id %s" % caller_agent_id if caller_agent_id else "Spud")
        return pre_decision("allow", "a well-formed spud call by %s, checked by the ledger hook" % who)
    return SILENT


def hook_edit(ctx, con, at, payload, tool_input, caller_agent_id, caller_member):
    tool = payload.get("tool_name")
    field = "notebook_path" if tool == "NotebookEdit" else "file_path"
    path = tool_input.get(field)
    if not isinstance(path, str) or not path:
        return deny_and_record(con, at, payload, "malformed PreToolUse(%s) payload: tool_input.%s is missing" % (tool, field), caller_agent_id, caller_member)
    reason, rel = edit_reason(ctx, con, caller_agent_id, caller_member, path, payload.get("cwd") or None)
    if reason:
        return deny_and_record(con, at, payload, reason, caller_agent_id, caller_member, extra={"path": rel if rel is not None else path})
    return SILENT


def request_from_meta(con, meta_path, agent_id):
    """The allowed, still unbound spawn_requests row named by agent-<id>.meta.json's toolUseId
    (the harness writes the file about a second after the spawn; it is an internal file, so
    it is only ever a fallback)."""
    if meta_path is None or not meta_path.is_file():
        return None
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    tid = meta.get("toolUseId") if isinstance(meta, dict) else None
    if not isinstance(tid, str) or not tid:
        return None
    req = con.execute(
        "SELECT * FROM spawn_requests WHERE tool_use_id = ? AND decision = 'allow' AND member_id IS NOT NULL AND (agent_id IS NULL OR agent_id = ?)",
        (tid, agent_id),
    ).fetchone()
    if req is None:
        return None
    # The meta must describe the request it names (Rooster's MEDIUM-4): a forged file pointing at
    # someone else's request carries the wrong description or agent type.
    if "description" in meta and meta.get("description") != req["description"]:
        return None
    if "agentType" in meta and req["subagent_type"] is not None and meta.get("agentType") != req["subagent_type"]:
        return None
    return req


def bind_request(con, at, actor_label, req, agent_id, session_id):
    """Bind the member of an allowed request to agent_id when it is alive and unbound."""
    candidate = get_member_by_id(con, req["member_id"])
    if candidate is None or candidate["status"] not in ALIVE or candidate["agent_id"]:
        return None
    con.execute("UPDATE spawn_requests SET agent_id = ? WHERE tool_use_id = ?", (agent_id, req["tool_use_id"]))
    return bind_member(con, at, actor_label, candidate, agent_id, session_id=session_id, tool_use_id=req["tool_use_id"])


def late_bind(con, at, payload, agent_id):
    """A foreground spawn's first tool call: bind it from the meta.json beside the session's
    subagent transcripts (<project>/<session_id>/subagents/agent-<id>.meta.json)."""
    transcript = payload.get("transcript_path")
    session = payload.get("session_id")
    if not (isinstance(transcript, str) and transcript and isinstance(session, str) and session):
        return None
    meta_path = Path(transcript).parent / session / "subagents" / ("agent-%s.meta.json" % agent_id)
    req = request_from_meta(con, meta_path, agent_id)
    if req is None:
        return None
    return bind_request(con, at, "hook:PreToolUse", req, agent_id, session)


def hook_pre_tool_use(ctx, payload):
    tool = payload.get("tool_name")
    if tool not in ENFORCED_TOOLS:
        return SILENT
    if not ctx.db_path.is_file():
        return pre_decision("deny", "no ledger database at %s; run `spud init` (the enforcing hooks refuse until the ledger exists)" % ctx.db_path)
    con = connect(ctx)
    try:
        at = now()
        caller_agent_id = payload.get("agent_id") if isinstance(payload.get("agent_id"), str) and payload.get("agent_id") else None
        tool_input = payload.get("tool_input")
        with write_txn(con):
            caller_member = con.execute("SELECT * FROM members WHERE agent_id = ?", (caller_agent_id,)).fetchone() if caller_agent_id else None
            if caller_agent_id and caller_member is None:
                caller_member = late_bind(con, at, payload, caller_agent_id)
            if not isinstance(tool_input, dict):
                return deny_and_record(con, at, payload, "malformed PreToolUse(%s) payload: tool_input is not an object" % tool, caller_agent_id, caller_member)
            if tool == "Agent":
                return hook_agent_spawn(ctx, con, at, payload, tool_input, caller_agent_id, caller_member)
            if tool == "Bash":
                return hook_bash(ctx, con, at, payload, tool_input, caller_agent_id, caller_member)
            return hook_edit(ctx, con, at, payload, tool_input, caller_agent_id, caller_member)
    finally:
        con.close()


# -- the recording handlers ------------------------------------------------------------


def bind_member(con, at, actor_label, member, agent_id, session_id=None, tool_use_id=None, resolved_model=None):
    """agent_id -> member: the columns only hooks write, planned -> active through the state
    machine, and the events the child recorded before the binding attached to it."""
    if member["agent_id"] and member["agent_id"] != agent_id:
        write_event(con, at, actor_label, "hook.error", "%s is already bound to agent_id %s; not rebinding to %s" % (member_ref(con, member["id"]), member["agent_id"], agent_id),
                    ticket_id=member["ticket_id"], member_id=member["id"], agent_id=agent_id, data={"tool_use_id": tool_use_id})
        return member
    updates = {"agent_id": agent_id}
    if session_id:
        updates["session_id"] = str(session_id)
    if tool_use_id:
        updates["tool_use_id"] = tool_use_id
    if resolved_model:
        updates["resolved_model"] = str(resolved_model)
    con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), member["id"]))
    member = get_member_by_id(con, member["id"])
    if member["status"] == "planned":
        member_status_change(con, at, actor_label, member, "active")
        member = get_member_by_id(con, member["id"])
    con.execute("UPDATE events SET member_id = ?, ticket_id = COALESCE(ticket_id, ?) WHERE agent_id = ? AND member_id IS NULL", (member["id"], member["ticket_id"], agent_id))
    return member


def as_int(value):
    return int(value) if isinstance(value, (int, float)) and not isinstance(value, bool) else None


# A member's run totals (SPD-021).  A foreground spawn fires SubagentStop and then PostToolUse(Agent,
# completed) (spike, Enforcement plan, fact 8); a background spawn's PostToolUse comes at launch with no
# usage fields, so only its SubagentStop records the run.
# total_tokens and the usage key token_counts reads come only from a transcript sum: the completion's
# totalTokens and usage cover its final API request only (hooks reference, Agent tool telemetry).
# What the completion reports is kept under "completion" in usage_json, beside the sum or alone.  Its
# totalDurationMs and totalToolUseCount, which the reference defines over the whole run (the run's
# wall-clock duration, the count of tool calls the subagent made), win over the transcript's
# first-to-last timestamps and tool_use blocks.  Both hooks merge through run_totals, so either order
# ends in the same row.
COMPLETION_KEYS = ("status", "usage", "totalTokens", "totalDurationMs", "totalToolUseCount", "toolStats", "modelsUsed")


def usage_parts(usage_json):
    """A stored usage_json taken apart: (the transcript sum without its completion when the source is
    transcript, else None; the completion kept beside the sum or alone, else None)."""
    try:
        usage = json.loads(usage_json) if usage_json else None
    except ValueError:
        return None, None
    if not isinstance(usage, dict):
        return None, None
    completion = usage.get("completion") if isinstance(usage.get("completion"), dict) else None
    if usage.get("source") != "transcript":
        return None, completion
    return {k: v for k, v in usage.items() if k != "completion"}, completion


def run_totals(member, summed=None, completion=None):
    """The usage columns once a new transcript sum (transcript_usage's result) or a new completion is
    merged with what the member row holds; the stored sum and the stored completion stay unless a new
    one is given.  total_tokens is the sum's or NULL; duration_ms and tool_uses are the completion's
    whole-run figures when it has them, else the sum's."""
    stored_sum, stored_completion = usage_parts(member["usage_json"])
    if completion is None:
        completion = stored_completion
    if summed is not None:
        tokens, duration, tools, usage = summed["total_tokens"], summed["duration_ms"], summed["tool_uses"], dict(summed["usage_json"])
    elif stored_sum is not None:
        tokens, duration, tools, usage = member["total_tokens"], member["duration_ms"], member["tool_uses"], stored_sum
    else:
        tokens, duration, tools, usage = None, None, None, {"source": "PostToolUse"}
    if completion is not None:
        if as_int(completion.get("totalDurationMs")) is not None:
            duration = as_int(completion["totalDurationMs"])
        if as_int(completion.get("totalToolUseCount")) is not None:
            tools = as_int(completion["totalToolUseCount"])
        usage["completion"] = completion
    return {"total_tokens": tokens, "duration_ms": duration, "tool_uses": tools, "usage_json": json.dumps(usage)}


def record_completion(con, member, resp):
    """A completed foreground Agent call: the child's final text into return_text, and what the
    completion reports merged into the run totals (run_totals)."""
    content = resp.get("content")
    text = None
    if isinstance(content, list):
        text = "\n".join(b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text")
    totals = run_totals(member, completion={key: resp[key] for key in COMPLETION_KEYS if key in resp})
    con.execute(
        "UPDATE members SET return_text = COALESCE(?, return_text), total_tokens = ?, duration_ms = ?, tool_uses = ?, usage_json = ? WHERE id = ?",
        (text if text else None, totals["total_tokens"], totals["duration_ms"], totals["tool_uses"], totals["usage_json"], member["id"]),
    )


def hook_post_tool_use(ctx, payload):
    if payload.get("tool_name") != "Agent" or not ctx.db_path.is_file():
        return SILENT
    con = connect(ctx)
    try:
        at = now()
        resp = payload.get("tool_response")
        resp = resp if isinstance(resp, dict) else {}
        tool_use_id = payload.get("tool_use_id")
        agent_id = resp.get("agentId")
        data = {"tool_use_id": tool_use_id, "agent_id": agent_id, "status": resp.get("status")}
        with write_txn(con):
            req = con.execute("SELECT * FROM spawn_requests WHERE tool_use_id = ?", (tool_use_id,)).fetchone() if isinstance(tool_use_id, str) else None
            gap = None
            if req is None:
                gap = "PostToolUse(Agent) for tool_use_id %s (agentId %s) has no spawn_requests row: the spawn was not seen by PreToolUse" % (tool_use_id, agent_id)
            elif req["decision"] != "allow":
                gap = "PostToolUse(Agent) for tool_use_id %s: the spawn was denied by PreToolUse yet a subagent ran (agentId %s)" % (tool_use_id, agent_id)
            elif req["member_id"] is None:
                gap = "PostToolUse(Agent) for tool_use_id %s matched no member row" % tool_use_id
            elif not isinstance(agent_id, str) or not agent_id:
                gap = "PostToolUse(Agent) for tool_use_id %s carries no agentId; nothing to bind" % tool_use_id
            if gap:
                write_event(con, at, "hook:PostToolUse", "hook.error", gap, agent_id=agent_id if isinstance(agent_id, str) else None, data=data)
                return SILENT
            member = get_member_by_id(con, req["member_id"])
            con.execute("UPDATE spawn_requests SET agent_id = ? WHERE tool_use_id = ?", (agent_id, tool_use_id))
            if member["status"] not in ALIVE:
                write_event(con, at, "hook:PostToolUse", "hook.error", "%s is %s; the binding of agent_id %s was skipped" % (member_ref(con, member["id"]), member["status"], agent_id),
                            ticket_id=member["ticket_id"], member_id=member["id"], agent_id=agent_id, data=data)
                return SILENT
            member = bind_member(con, at, "hook:PostToolUse", member, agent_id, session_id=payload.get("session_id"), tool_use_id=tool_use_id, resolved_model=resp.get("resolvedModel"))
            if resp.get("status") == "completed":
                record_completion(con, member, resp)
    finally:
        con.close()
    return SILENT


def hook_subagent_start(ctx, payload):
    if not ctx.db_path.is_file():
        return SILENT
    agent_id = payload.get("agent_id")
    if not isinstance(agent_id, str) or not agent_id:
        raise HookError("SubagentStart payload carries no agent_id")
    con = connect(ctx)
    try:
        at = now()
        with write_txn(con):
            member = con.execute("SELECT * FROM members WHERE agent_id = ?", (agent_id,)).fetchone()
            write_event(con, at, "hook:SubagentStart", "member.started", "subagent %s started (%s)" % (agent_id, payload.get("agent_type")),
                        ticket_id=member["ticket_id"] if member else None, member_id=member["id"] if member else None, agent_id=agent_id,
                        data={"agent_type": payload.get("agent_type"), "session_id": payload.get("session_id"), "cwd": payload.get("cwd")})
            context = "Ledger: your agent_id is `%s`; every `spud` command you run takes `--as %s`." % (agent_id, agent_id)
            if member:
                ticket = get_ticket_by_id(con, member["ticket_id"])
                context += " You are %s/%s (%s, %s) on %s; your deliverables: %s." % (
                    ticket["team_key"], member["name"], member["lineage"], member["persona"], ticket["key"], ", ".join(json.loads(member["deliverables"])) or "none")
    finally:
        con.close()
    return HookOutput({"hookSpecificOutput": {"hookEventName": "SubagentStart", "additionalContext": context}})


def parse_timestamp(value):
    if not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


# How a transcript sum counts (SPD-023).  The harness writes an API response as one transcript entry per
# content block, each repeating the response's message.id, its requestId and the request's usage, with only
# output_tokens growing to the final count (a read-only survey of five live subagent transcripts on
# 2026-09-13: 177 requests, every entry one block, the last entry of each request the maximum on every key).
# Before SPD-023 every entry was added, so a request counted once per block and the tokens ran four to five
# times too high.  A sum counted once per request carries "counting": "request"; a stored transcript sum
# without it is found and re-summed by `spud member resum`.
REQUEST_COUNTING = "request"
TOKEN_KEYS = ("input_tokens", "output_tokens", "cache_creation_input_tokens", "cache_read_input_tokens")

# The per-model breakdown a transcript sum keeps beside its usage since SPD-013: what a run's list-price cost is computed
# from (run_cost).  A read-only survey of the live transcripts on 2026-09-13 (1,590 requests in 46 files) found every
# request's usage with its model (message.model), a service_tier and an inference_geo, nearly all with a speed; a
# cache_creation split by TTL that sums to cache_creation_input_tokens (one exception, a server-side fallback's request:
# 4,369 split beside a total of 0); server_tool_use counts; and usage.iterations holding one message iteration (the same
# exception held a fallback_message attempt).  The API bills a compaction iteration beside the top-level figures and a
# fallback per attempt, neither of which the top level shows whole.
BREAKDOWN_IDENTITY = ("model", "speed", "service_tier", "inference_geo")
BREAKDOWN_TOKENS = ("input_tokens", "output_tokens", "cache_read_input_tokens")


def usage_count(value):
    """A usage figure as a sum adds it: an int or a float, never a bool, as an int; anything else counts 0."""
    return int(value) if isinstance(value, (int, float)) and not isinstance(value, bool) else 0


def usage_breakdown(requests):
    """[(message.model, usage)] of a transcript's requests, each by its last entry, grouped into buckets by model, speed,
    service tier and inference geography as the transcript writes them (a key left out when the usage has none), sorted
    by those four.  A bucket keeps its requests; its input, output and cache-read tokens; its cache writes by TTL under
    cache_creation when the request's split adds up to cache_creation_input_tokens, as the API documents it, else as
    cache_creation_unsplit_input_tokens; its usage.server_tool_use counts; and, under iterations, the iteration types of
    any request whose usage.iterations holds more than one message iteration (a compaction, a fallback's attempts),
    which the top-level figures do not bill whole.  Its token figures add up to the sum's usage."""
    buckets = {}
    for model, usage in requests:
        identity = tuple(v if isinstance(v, str) and v else None for v in (model,) + tuple(usage.get(k) for k in BREAKDOWN_IDENTITY[1:]))
        bucket = buckets.get(identity)
        if bucket is None:
            bucket = buckets[identity] = {k: v for k, v in zip(BREAKDOWN_IDENTITY, identity) if v is not None}
            bucket.update(requests=0, **dict.fromkeys(BREAKDOWN_TOKENS, 0))
        bucket["requests"] += 1
        for k in BREAKDOWN_TOKENS:
            bucket[k] += usage_count(usage.get(k))
        writes = usage_count(usage.get("cache_creation_input_tokens"))
        split = usage.get("cache_creation")
        split = {k: usage_count(v) for k, v in split.items() if isinstance(v, (int, float)) and not isinstance(v, bool)} if isinstance(split, dict) else None
        if split is not None and sum(split.values()) == writes:
            into = bucket.setdefault("cache_creation", {})
            for k, v in split.items():
                into[k] = into.get(k, 0) + v
        elif writes:
            bucket["cache_creation_unsplit_input_tokens"] = bucket.get("cache_creation_unsplit_input_tokens", 0) + writes
        tools = usage.get("server_tool_use")
        if isinstance(tools, dict):
            into = bucket.setdefault("server_tool_use", {})
            for k, v in tools.items():
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    into[k] = into.get(k, 0) + int(v)
        iterations = usage.get("iterations")
        if isinstance(iterations, list) and iterations and not (
                len(iterations) == 1 and isinstance(iterations[0], dict) and iterations[0].get("type") == "message"):
            into = bucket.setdefault("iterations", {})
            for iteration in iterations:
                kind = iteration.get("type") if isinstance(iteration, dict) and isinstance(iteration.get("type"), str) else "unknown"
                into[kind] = into.get(kind, 0) + 1
    return [buckets[identity] for identity in sorted(buckets, key=lambda identity: tuple(v or "" for v in identity))]


def request_key(entry, index):
    """The API request a transcript's assistant entry belongs to: its message.id with its requestId (None
    when the entry has none).  An entry without a message id is a request of its own, whatever else it
    carries; index is its line in the file."""
    message_id = entry["message"].get("id")
    if not isinstance(message_id, str) or not message_id:
        return ("entry", index)
    request_id = entry.get("requestId")
    return ("request", message_id, request_id if isinstance(request_id, str) and request_id else None)


def transcript_usage(path):
    """A subagent transcript summed once per API request (SPD-023): a member's tokens whatever the spawn
    shape, since a foreground completion's figures cover only its final request (run_totals keeps both,
    SPD-021).  The assistant entries are grouped by request (request_key) and each request counts once,
    by the usage of its last entry; messages counts the requests.  tool_uses counts distinct tool_use
    block ids (a block without an id counts where it appears), the same whether a response's blocks come
    one per entry or together; duration_ms runs from the first timestamp in the file to the last.  The
    sum is marked "counting": "request" and keeps, since SPD-013, the per-model breakdown of its requests
    (usage_breakdown) that a list-price cost is computed from.  None when the file holds no assistant usage;
    OSError when it cannot be read."""
    requests = {}
    tool_ids = set()
    tools_without_id = 0
    first = last = None
    with open(path, encoding="utf-8", errors="replace") as f:
        for index, line in enumerate(f):
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            if not isinstance(entry, dict):
                continue
            ts = parse_timestamp(entry.get("timestamp"))
            if ts is not None:
                first = ts if first is None or ts < first else first
                last = ts if last is None or ts > last else last
            msg = entry.get("message")
            if entry.get("type") != "assistant" or not isinstance(msg, dict):
                continue
            if isinstance(msg.get("usage"), dict):
                requests[request_key(entry, index)] = (msg.get("model"), msg["usage"])  # a later entry of the request replaces an earlier one
            content = msg.get("content")
            if isinstance(content, list):
                for block in content:
                    if isinstance(block, dict) and block.get("type") == "tool_use":
                        if isinstance(block.get("id"), str) and block["id"]:
                            tool_ids.add(block["id"])
                        else:
                            tools_without_id += 1
    if not requests:
        return None
    totals = dict.fromkeys(TOKEN_KEYS, 0)
    for _, usage in requests.values():
        for k in TOKEN_KEYS:
            v = usage.get(k)
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                totals[k] += int(v)
    duration = int((last - first).total_seconds() * 1000) if first is not None and last is not None else None
    return {"total_tokens": sum(totals.values()), "duration_ms": duration, "tool_uses": len(tool_ids) + tools_without_id,
            "usage_json": {"source": "transcript", "counting": REQUEST_COUNTING, "messages": len(requests), "usage": totals,
                           "breakdown": usage_breakdown(requests.values())}}


RESULT_HOLD = ("record your Result with `spud --as %s member result '<what you produced, where, what you verified, what is left>'`"
               " (or Blocked with `spud --as %s member block '<the question and the options>'`) before returning; then return your summary")


def unrecorded_children(con, member):
    """A member's own direct children that have returned (a final stop) and still have no
    verdict: the shape `hook_stop` uses for Spud's children, one level down (SPD-015)."""
    return con.execute(
        "SELECT m.*, t.team_key FROM members m JOIN tickets t ON t.id = m.ticket_id"
        " WHERE m.parent_id = ? AND m.stopped_at IS NOT NULL AND (m.outcome IS NULL OR trim(m.outcome) = '')"
        "   AND m.status = 'active'"
        " ORDER BY m.stopped_at, m.id",
        (member["id"],),
    ).fetchall()


def alive_children(con, member):
    """A member's own direct children that are still alive at its stop: spawned and running (no
    final stop), or planned and never spawned.  Probed 2026-09-12: a background child is not
    killed when its parent returns, its completion notification goes to the main session and its
    row is orphaned, so the block is the only thing that keeps the parent alive to collect it."""
    return con.execute(
        "SELECT m.*, t.team_key FROM members m JOIN tickets t ON t.id = m.ticket_id"
        " WHERE m.parent_id = ? AND m.status IN ('planned','active') AND m.stopped_at IS NULL"
        " ORDER BY COALESCE(m.spawned_at, m.planned_at), m.id",
        (member["id"],),
    ).fetchall()


def finish_commands(agent_id, children):
    return "; ".join("`spud --as %s member finish %s/%s --status done|blocked|failed --outcome '<verdict>'`" % (agent_id, c["team_key"], c["name"])
                     for c in children)


def children_hold_reason(agent_id, children):
    """Law 9 one level down: the children that returned, and the exact command for each."""
    n = len(children)
    items = "; ".join("%s/%s (%s, %s), stopped %s" % (c["team_key"], c["name"], c["lineage"], c["persona"], (c["stopped_at"] or "")[11:16])
                      for c in children)
    return ("%d child%s you spawned returned and %s not recorded: %s. Record %s with %s, and decide the proposals %s filed, if any"
            " (`spud proposal list --open`; `spud --as %s proposal decide <id> --decision absorb|decline|escalate --reason '<why>'`)."
            % (n, "" if n == 1 else "ren", "is" if n == 1 else "are", items, "it" if n == 1 else "each",
               finish_commands(agent_id, children), "it" if n == 1 else "they", agent_id))


def alive_children_reason(con, agent_id, children):
    """The other half of the parent's job: a child still running, planned and never spawned, or
    planned with its spawn allowed and never bound.  The last is not "never spawned": the
    reservation refuses a second spawn of it (hook_agent_spawn), so telling the lead to spawn it
    now would be wrong; its way out is the hook.error check and the lead's own actor, with no
    grace period, since a lead's background child binds at launch and a foreground one cannot
    outlive the lead's own turn (SPD-028; SPD-025 gives the session-level kind, ten minutes on)."""
    reserved = {}
    for c in children:
        if c["status"] != "active":
            waiting = reservations(con, c)
            if waiting:
                reserved[c["id"]] = waiting[0]

    def item(c):
        if c["status"] == "active":
            return "running since " + (c["spawned_at"] or "")[11:16]
        if c["id"] in reserved:
            first = reserved[c["id"]]
            return "spawn allowed %s (tool_use_id %s), never bound" % ((first["at"] or "")[11:16], first["tool_use_id"])
        return "planned " + (c["planned_at"] or "")[11:16] + " and never spawned"

    n = len(children)
    items = "; ".join("%s/%s (%s, %s), %s" % (c["team_key"], c["name"], c["lineage"], c["persona"], item(c)) for c in children)
    text = "%d child%s you planned %s still alive: %s." % (n, "" if n == 1 else "ren", "is" if n == 1 else "are", items)
    running = [c for c in children if c["status"] == "active"]
    unspawned = [c for c in children if c["status"] != "active" and c["id"] not in reserved]
    unbound = [c for c in children if c["id"] in reserved]
    if running:
        one = len(running) == 1
        text += (" Ending your turn ends your run: a background child is not killed with you, its completion notification goes to the main"
                 " session and its row is orphaned. Wait inside this turn (%s until the child's Result is there), then record %s with %s."
                 " If you cannot wait, say so in your summary and return: your parent records %s."
                 % ("; ".join("`spud member show %s/%s`" % (c["team_key"], c["name"]) for c in running),
                    "it" if one else "each", finish_commands(agent_id, running), "it" if one else "them"))
    if unspawned:
        one = len(unspawned) == 1
        text += (" The planned child%s never started: spawn %s now, or record %s with %s so the %s counting against your limits."
                 % ("" if one else "ren", "it" if one else "them", "it" if one else "each",
                    "; ".join("`spud --as %s member finish %s/%s --status failed --outcome '<why>'`" % (agent_id, c["team_key"], c["name"]) for c in unspawned),
                    "row stops" if one else "rows stop"))
    if unbound:
        one = len(unbound) == 1
        refs = ["%s/%s" % (c["team_key"], c["name"]) for c in unbound]
        steps = ["record %s with `spud --as %s member finish %s --status failed --outcome '<why>'` and plan a new member, since the reservation refuses a second spawn of `%s (%s, %s)`"
                 % (ref, agent_id, ref, ref, c["lineage"], c["persona"]) for c, ref in zip(unbound, refs)]
        text += (" The planned %s allowed to spawn and never bound: first look for %s in `spud events --kind hook.error --json`: a gap there means that child may"
                 " still be running, so wait inside this turn (%s until the child's Result is there), then record %s. If the harness failed %s, %s."
                 % ("child was" if one else "children were", "its tool_use_id" if one else "each tool_use_id",
                    "; ".join("`spud member show %s`" % ref for ref in refs),
                    "it" if one else "each",
                    "the spawn" if one else "a spawn", "; ".join(steps)))
    return text


def stop_hold_reason(con, agent_id, recorded, returned, still_alive):
    """One block for the whole finishing rule, children first; with no children of its own it is
    the Result hold, word for word."""
    clauses = []
    if returned:
        clauses.append(children_hold_reason(agent_id, returned))
    if still_alive:
        clauses.append(alive_children_reason(con, agent_id, still_alive))
    if not clauses:
        return RESULT_HOLD % (agent_id, agent_id)
    return "Law 9: " + " ".join(clauses) + (" Then return your summary." if recorded else " Then " + RESULT_HOLD % (agent_id, agent_id))


def hook_subagent_stop(ctx, payload):
    if not ctx.db_path.is_file():
        return SILENT
    agent_id = payload.get("agent_id")
    if not isinstance(agent_id, str) or not agent_id:
        raise HookError("SubagentStop payload carries no agent_id")
    stop_hook_active = bool(payload.get("stop_hook_active"))
    transcript = payload.get("agent_transcript_path") if isinstance(payload.get("agent_transcript_path"), str) else None
    last = payload.get("last_assistant_message")
    agent_type = payload.get("agent_type")
    con = connect(ctx)
    try:
        at = now()
        with write_txn(con):
            member = con.execute("SELECT * FROM members WHERE agent_id = ?", (agent_id,)).fetchone()
            bound_by = None
            if member is None:
                req = None
                if transcript:
                    req = request_from_meta(con, Path(transcript).with_name("agent-%s.meta.json" % agent_id), agent_id)
                    bound_by = "meta.json" if req else None
                if req is None:
                    # The only allowed, still unbound request of this session; with two or more the
                    # hook does not guess (Rooster's MEDIUM-5) and records the gap instead.
                    params = [payload.get("session_id")]
                    narrowing = ""
                    if isinstance(agent_type, str) and agent_type:
                        narrowing = " AND (subagent_type IS NULL OR subagent_type = ?)"
                        params.append(agent_type)
                    candidates = con.execute("SELECT * FROM spawn_requests WHERE session_id = ? AND decision = 'allow' AND member_id IS NOT NULL AND agent_id IS NULL" + narrowing + " ORDER BY at, rowid", params).fetchall()
                    if len(candidates) == 1:
                        req = candidates[0]
                        bound_by = "oldest-unbound"
                    elif len(candidates) > 1:
                        write_event(con, at, "hook:SubagentStop", "hook.error",
                                    "SubagentStop for agent_id %s: no meta.json and %d unbound allowed requests in session %s (%s); not guessing which member it is"
                                    % (agent_id, len(candidates), payload.get("session_id"), ", ".join(c["tool_use_id"] for c in candidates)),
                                    agent_id=agent_id, data={"candidates": [c["tool_use_id"] for c in candidates]})
                if req is not None:
                    member = bind_request(con, at, "hook:SubagentStop", req, agent_id, payload.get("session_id"))
                    if member is None:
                        bound_by = None
            base = {"agent_type": agent_type, "stop_hook_active": stop_hook_active, "bound_by": bound_by}
            if member is None:
                write_event(con, at, "hook:SubagentStop", "member.stopped", "subagent %s stopped unbound (%s)" % (agent_id, agent_type), agent_id=agent_id, data=base)
                return SILENT
            ref = member_ref(con, member["id"])
            recorded = bool((member["result"] or "").strip() or (member["blocked"] or "").strip())
            live = member["status"] in ALIVE
            returned = unrecorded_children(con, member) if live else []
            still_alive = alive_children(con, member) if live else []
            returned_refs = ["%s/%s" % (c["team_key"], c["name"]) for c in returned]
            alive_refs = ["%s/%s" % (c["team_key"], c["name"]) for c in still_alive]
            if live and (not recorded or returned or still_alive) and not stop_hook_active:
                # The finishing rule has two halves: the member's own Result, and the verdict of
                # every child it spawned (Law 9 binds every parent, not only Spud).  One block
                # covers both, children first; `stop_hook_active` lets the second stop through.
                what = []
                if not recorded:
                    what.append("without a Result")
                if returned_refs:
                    what.append("with %d unrecorded child%s (%s)" % (len(returned_refs), "" if len(returned_refs) == 1 else "ren", ", ".join(returned_refs)))
                if alive_refs:
                    what.append("with %d child%s still alive (%s)" % (len(alive_refs), "" if len(alive_refs) == 1 else "ren", ", ".join(alive_refs)))
                data = dict(base, held=True, unrecorded=not recorded)
                if returned_refs:
                    data["unrecorded_children"] = returned_refs
                if alive_refs:
                    data["alive_children"] = alive_refs
                write_event(con, at, "hook:SubagentStop", "member.stopped", "%s returned %s; held once" % (ref, " and ".join(what)),
                            ticket_id=member["ticket_id"], member_id=member["id"], agent_id=agent_id, data=data)
                return HookOutput({"decision": "block", "reason": stop_hold_reason(con, agent_id, recorded, returned, still_alive)})
            updates = {"stopped_at": at}
            if isinstance(last, str) and last.strip():
                updates["return_text"] = last
            if transcript:
                updates["transcript_path"] = transcript
            summed = None
            if usage_parts(member["usage_json"])[0] is None and transcript and os.path.isfile(transcript):
                # a stored transcript sum stays, however it was counted (`member resum` re-sums one that added every
                # entry, SPD-023); a completion recorded before this stop stays beside the new sum (SPD-021)
                summed = transcript_usage(transcript)
                if summed:
                    updates.update(run_totals(member, summed=summed))
            con.execute("UPDATE members SET %s WHERE id = ?" % ", ".join("%s = ?" % k for k in updates), (*updates.values(), member["id"]))
            suffix = "" if recorded else " (returned unrecorded)"
            if returned_refs:
                suffix += " (%d unrecorded child%s: %s)" % (len(returned_refs), "" if len(returned_refs) == 1 else "ren", ", ".join(returned_refs))
            if alive_refs:
                suffix += " (%d child%s still alive: %s)" % (len(alive_refs), "" if len(alive_refs) == 1 else "ren", ", ".join(alive_refs))
            data = dict(base, held=False, unrecorded=not recorded, transcript_usage=bool(summed))
            if returned_refs:
                data["unrecorded_children"] = returned_refs
            if alive_refs:
                data["alive_children"] = alive_refs
            write_event(con, at, "hook:SubagentStop", "member.stopped", "%s stopped%s" % (ref, suffix),
                        ticket_id=member["ticket_id"], member_id=member["id"], agent_id=agent_id, data=data)
    finally:
        con.close()
    return SILENT


def hook_session_start(ctx, payload):
    if not ctx.db_path.is_file():
        return SILENT
    con = connect(ctx)
    try:
        text = board_brief_text(con)
    finally:
        con.close()
    context = "Ledger board (`spud board --brief` at %s, source %s):\n%s" % (now(), payload.get("source"), text)
    return HookOutput({"hookSpecificOutput": {"hookEventName": "SessionStart", "additionalContext": context}})


# Spud's Stop hook, one session at a time (SPD-018).  Eric runs tickets in parallel sessions; before SPD-018 every Stop
# was held, ledger-wide, for any member returned unrecorded, another session's included.  A member's session is the
# session that spawned its tree.  Every hook payload fired inside a subagent carries the main session's session_id (the
# SPD-015 probe captures: a lead's PreToolUse(Agent) for its child and the SubagentStops of lead and child all carry
# it), and so does CLAUDE_CODE_SESSION_ID in any Bash the harness runs, a subagent's included, which `member new`
# records on the row it plans (planning_session).
PLANNED_GRACE_SECONDS = 600  # a planned row no session can claim holds every session only once it has waited this long; a spawn allowed and never bound holds only once its allow is this old (SPD-025)


def member_session(con, member):
    """The session a member belongs to: its latest allowed spawn request's, else the one its row records (bound at
    spawn, or at `member new`), else its parent's, up to the root; None when nothing on the way records one (a row
    from before sessions were recorded)."""
    seen = set()
    while member is not None and member["id"] not in seen:
        seen.add(member["id"])
        req = con.execute("SELECT session_id FROM spawn_requests WHERE member_id = ? AND decision = 'allow' AND session_id != ''"
                          " ORDER BY at DESC, rowid DESC LIMIT 1", (member["id"],)).fetchone()
        if req is not None:
            return req["session_id"]
        if member["session_id"]:
            return member["session_id"]
        member = get_member_by_id(con, member["parent_id"]) if member["parent_id"] is not None else None
    return None


def planned_long_ago(stamp, at):
    """Whether stamp (a row's planned_at, or since SPD-025 a spawn request's allow) is more than PLANNED_GRACE_SECONDS
    before at; a stamp that cannot be read counts as old."""
    try:
        planned, current = datetime.fromisoformat(stamp), datetime.fromisoformat(at)
    except (TypeError, ValueError):
        return True
    planned = planned if planned.tzinfo else planned.astimezone()
    current = current if current.tzinfo else current.astimezone()
    return (current - planned).total_seconds() > PLANNED_GRACE_SECONDS


def told_running(con, session, ref):
    """Whether an earlier Stop block in this session already named ref as still running: the events are the memory."""
    return con.execute(
        "SELECT 1 FROM events e, json_each(e.data, '$.running') j"
        " WHERE e.kind = 'hook.denied' AND e.actor = 'hook:Stop' AND json_extract(e.data, '$.session_id') IS ? AND j.value = ? LIMIT 1",
        (session, ref),
    ).fetchone() is not None


def reservations(con, member):
    """A member's allowed spawn requests still waiting to bind, oldest first: the reservation hook_agent_spawn keeps
    against a second spawn of the member until one binds (SPD-025)."""
    return con.execute("SELECT tool_use_id, at FROM spawn_requests WHERE member_id = ? AND decision = 'allow' AND agent_id IS NULL"
                       " ORDER BY at, rowid", (member["id"],)).fetchall()


def stop_owed(con, session, at):
    """What the stopping session owes, as (returned, planned, unbound, running) lists of member rows.  A member of another
    session is never owed; one with no known session is every session's, as is everything when the payload names
    no session.
    - returned: a final stop, no outcome, status active, at the root or under a finished parent;
    - planned: never spawned and no allowed spawn waiting to bind, at the root or under a finished parent; a row no
      session can claim only once it has waited PLANNED_GRACE_SECONDS, so a row planned a moment ago never holds;
    - unbound: planned the same way, but its spawn was allowed and never bound (SPD-025): the harness failed the spawn,
      or the binding failed open.  Owed only once every such allow is more than PLANNED_GRACE_SECONDS old; until then
      it is a spawn in flight (PostToolUse(Agent) binds a background spawn at launch) and never holds;
    - running: active with no final stop under a finished parent, named once per session (Spud's own children at
      work never hold: ending a turn while they run is the design)."""
    def owes(own):
        return own is None or session is None or own == session

    returned = [r for r in con.execute(
        "SELECT m.*, t.team_key, t.key AS ticket_key FROM members m JOIN tickets t ON t.id = m.ticket_id"
        " LEFT JOIN members p ON p.id = m.parent_id"
        " WHERE m.stopped_at IS NOT NULL AND (m.outcome IS NULL OR trim(m.outcome) = '') AND m.status = 'active'"
        "   AND (m.parent_id IS NULL OR p.status NOT IN ('planned','active'))"
        " ORDER BY m.stopped_at, m.id"
    ).fetchall() if owes(member_session(con, r))]
    planned, unbound = [], []
    for r in con.execute(
        "SELECT m.*, t.team_key, t.key AS ticket_key, p.status AS parent_status FROM members m JOIN tickets t ON t.id = m.ticket_id"
        " LEFT JOIN members p ON p.id = m.parent_id"
        " WHERE m.status = 'planned' AND (m.parent_id IS NULL OR p.status NOT IN ('planned','active'))"
        " ORDER BY m.planned_at, m.id"
    ).fetchall():
        waiting = reservations(con, r)
        if not all(planned_long_ago(w["at"], at) for w in waiting):
            continue  # a spawn in flight
        own = member_session(con, r)
        if (session is not None and own == session) or ((own is None or session is None) and planned_long_ago(r["planned_at"], at)):
            (unbound if waiting else planned).append(r)
    running = [r for r in con.execute(
        "SELECT m.*, t.team_key, t.key AS ticket_key, p.status AS parent_status FROM members m JOIN tickets t ON t.id = m.ticket_id"
        " JOIN members p ON p.id = m.parent_id"
        " WHERE m.status = 'active' AND m.stopped_at IS NULL AND p.status NOT IN ('planned','active')"
        " ORDER BY COALESCE(m.spawned_at, m.planned_at), m.id"
    ).fetchall() if owes(member_session(con, r)) and not told_running(con, session, "%s/%s" % (r["team_key"], r["name"]))]
    return returned, planned, unbound, running


def stop_item(r, what):
    return "%s/%s (%s, %s) on %s, %s" % (r["team_key"], r["name"], r["lineage"], r["persona"], r["ticket_key"], what)


def returned_clause(rows):
    """The returned members, in the words of Spud's Stop since SPD-008, without the ending; when every one is a
    root member the printed command also carries --next, since SPD-027 (a nested one's stays as it was: `member
    finish` writes no report entry, and no Next line, for a child)."""
    next_opt = " [--next '<what happens next>']" if rows and all(r["parent_id"] is None for r in rows) else ""
    return ("%d returned spudagent(s) are not recorded: %s. Record each with `spud --as spud member finish <SPUD-nnn/Name> --status done|blocked|failed"
            " --outcome '<verdict>' [--summary '<one paragraph>']%s`, decide its proposals (spud proposal list --open; spud --as spud proposal decide ...)"
            % (len(rows), "; ".join(stop_item(r, "stopped " + fm_minute(r["stopped_at"])) for r in rows), next_opt))


def planned_clause(con, rows):
    """Planned rows never spawned: Spud spawns its own or records them failed; one under a finished parent nobody
    can spawn.  A root row's failed command also carries --next, since SPD-027; a nested row's does not, the same
    as its unchanged member finish (no report entry for a child)."""
    items, steps = [], []
    for r in rows:
        ref = "%s/%s" % (r["team_key"], r["name"])
        if r["parent_id"] is None:
            fail = "`spud --as spud member finish %s --status failed --outcome '<why>' [--next '<what happens next>']`" % ref
            items.append(stop_item(r, "planned " + fm_minute(r["planned_at"])))
            steps.append("spawn %s now (the Agent tool with subagent_type `%s`, model `%s`, description `%s (%s, %s)`) or record it with %s"
                         % (ref, r["agent_type"], r["model"], ref, r["lineage"], r["persona"], fail))
        else:
            fail = "`spud --as spud member finish %s --status failed --outcome '<why>'`" % ref
            parent = member_ref(con, r["parent_id"])
            items.append(stop_item(r, "planned %s, under %s (%s)" % (fm_minute(r["planned_at"]), parent, r["parent_status"])))
            steps.append("nobody can spawn %s now that %s is %s: record it with %s" % (ref, parent, r["parent_status"], fail))
    steps_text = "; ".join(steps)
    return ("%d planned spudagent(s) were never spawned: %s. %s. A planned row holds a slot against the limits until it is spawned or recorded"
            % (len(rows), "; ".join(items), steps_text[:1].upper() + steps_text[1:]))


def unbound_clause(con, rows):
    """Planned rows whose spawn PreToolUse(Agent) allowed, and so reserved, and which never bound (SPD-025).  They are not
    'never spawned': the harness failed the spawn, or the binding failed open and the child may be running, so the
    binding gap comes first.  A root row that failed is planned anew, because the reservation refuses a second spawn of
    its description; one under a finished parent nobody can spawn again."""
    items, steps = [], []
    for r in rows:
        ref = "%s/%s" % (r["team_key"], r["name"])
        first = reservations(con, r)[0]  # the one hook_agent_spawn's refusal names
        allowed = "spawn allowed %s (tool_use_id %s), never bound" % (fm_minute(first["at"]), first["tool_use_id"])
        if r["parent_id"] is None:
            items.append(stop_item(r, allowed))
            steps.append("record %s with `spud --as spud member finish %s --status failed --outcome '<why>' [--next '<what happens next>']` and plan a new"
                         " member, since the reservation refuses a second spawn of `%s (%s, %s)`" % (ref, ref, ref, r["lineage"], r["persona"]))
        else:
            parent = member_ref(con, r["parent_id"])
            items.append(stop_item(r, "%s, under %s (%s)" % (allowed, parent, r["parent_status"])))
            steps.append("record %s with `spud --as spud member finish %s --status failed --outcome '<why>'`: nobody can spawn it again now that %s is %s"
                         % (ref, ref, parent, r["parent_status"]))
    one = len(rows) == 1
    return ("%d planned spudagent(s) were allowed to spawn and never bound: %s. First look for %s in `spud events --kind hook.error --json`:"
            " a gap there means that child may still be running, so wait for its notification. If the harness failed %s, %s."
            " A reserved row holds a slot against the limits until it is bound or recorded"
            % (len(rows), "; ".join(items), "its tool_use_id" if one else "each tool_use_id", "the spawn" if one else "a spawn", "; ".join(steps)))


def running_clause(con, rows):
    """Children still at work under a finished parent: nobody else will record them, and this is said once per session."""
    items = "; ".join(stop_item(r, "running since %s, under %s (%s)" % (fm_minute(r["spawned_at"] or r["planned_at"]), member_ref(con, r["parent_id"]), r["parent_status"]))
                      for r in rows)
    commands = "; ".join("`spud --as spud member finish %s/%s --status done|blocked|failed --outcome '<verdict>'`" % (r["team_key"], r["name"]) for r in rows)
    return ("%d spudagent(s) are still running under a finished parent: %s. No parent is left to record them: each completion notification"
            " comes to the session that spawned the tree, and when it arrives, record each with %s. This is said once; one that returns"
            " unrecorded is named again as returned" % (len(rows), items, commands))


def stop_reason(con, returned, planned, unbound, running):
    """One block: returned first, then planned, then unbound, then running.  With returned members alone it is the reason Spud's Stop
    has given since SPD-008, with --next added to the printed command when every one is a root member, since SPD-027."""
    if returned and not planned and not unbound and not running:
        return "Law 9: " + returned_clause(returned) + ", then end the turn."
    clauses = ([returned_clause(returned)] if returned else []) + ([planned_clause(con, planned)] if planned else []) + ([unbound_clause(con, unbound)] if unbound else []) + ([running_clause(con, running)] if running else [])
    return "Law 9: " + ". ".join(clauses) + ". Then end the turn."


def hook_stop(ctx, payload):
    if payload.get("agent_id") or payload.get("stop_hook_active") or not ctx.db_path.is_file():
        return SILENT
    session = payload.get("session_id") if isinstance(payload.get("session_id"), str) and payload.get("session_id") else None
    con = connect(ctx)
    try:
        at = now()
        with write_txn(con):
            returned, planned, unbound, running = stop_owed(con, session, at)
            if not (returned or planned or unbound or running):
                return SILENT
            refs = {kind: ["%s/%s" % (r["team_key"], r["name"]) for r in rows] for kind, rows in (("returned", returned), ("planned", planned), ("unbound", unbound), ("running", running))}
            reason = stop_reason(con, returned, planned, unbound, running)
            write_event(con, at, "hook:Stop", "hook.denied", reason,
                        data=dict({"hook_event_name": "Stop", "session_id": session, "members": refs["returned"] + refs["planned"] + refs["unbound"] + refs["running"]}, **refs))
    finally:
        con.close()
    return HookOutput({"decision": "block", "reason": reason})


HOOK_HANDLERS = {
    "PreToolUse": hook_pre_tool_use,
    "PostToolUse": hook_post_tool_use,
    "SubagentStart": hook_subagent_start,
    "SubagentStop": hook_subagent_stop,
    "SessionStart": hook_session_start,
    "Stop": hook_stop,
}


def cmd_hook(ctx, args):
    """The harness's entry point.  Exit codes are 0 or 2 only, whatever happens."""
    event = args.event
    raw = sys.stdin.read()
    payload = None
    try:
        try:
            payload = json.loads(raw) if raw.strip() else None
        except ValueError as e:
            raise HookError("payload is not JSON: %s" % e)
        if not isinstance(payload, dict):
            raise HookError("payload is not a JSON object")
        name = payload.get("hook_event_name")
        if name is not None and name != event:
            raise HookError("hook_event_name %r does not match `spud hook %s`" % (name, event))
        out = HOOK_HANDLERS[event](ctx, payload)
    except Exception as e:
        fields = payload if isinstance(payload, dict) else {}
        record = {"at": now(), "event": event, "tool_name": fields.get("tool_name"), "tool_use_id": fields.get("tool_use_id"),
                  "agent_id": fields.get("agent_id"), "session_id": fields.get("session_id"), "error": "%s: %s" % (type(e).__name__, e)}
        with contextlib.suppress(Exception):
            spool_write(ctx, record)
        enforcing = event == "PreToolUse" or (event == "Stop" and not fields.get("stop_hook_active"))
        if enforcing:
            return Result(None, raw="", exit_code=2, stderr="spud hook %s: %s (failing closed)" % (event, e))
        return Result(None, raw="", exit_code=EXIT_OK)
    with contextlib.suppress(Exception):
        spool_drain(ctx)
    return Result(None, raw=json.dumps(out.obj) if out.obj else "", exit_code=out.exit_code)


# ----------------------------------------------------------------------------
# Argument parsing and main
# ----------------------------------------------------------------------------

EPILOG = """\
actors (--as):
  spud               Spud himself: tickets, report entries, the parent of every lead.
                     Inside a subagent the PreToolUse(Bash) hook refuses this form.
  SPUD-nnn/<Name>    a team member (also SPUD-nnn/<lineage>, e.g. SPUD-007/01.01).
                     Inside a subagent the hook accepts it only for the caller's own member.
  <agent_id>         the 17-hex-character id the harness gives a subagent, bound to its
                     member by the hooks: PostToolUse(Agent) right after a background
                     spawn, SubagentStop for a foreground one.

hooks: `spud hook <event>` is the harness's entry point (payload on stdin, answer on
       stdout); `spud settings sync` installs the six events into .claude/settings.json.
       Enforcing hooks fail closed (exit 2), recording hooks fail open (spool, then
       hook.error events).  Inspect the database with `spud sql --readonly '<statement>'`.

text values: an option value of @path reads the file, @- reads stdin.
exit codes: 0 ok, 1 error, 2 usage, 3 ownership refused, 4 limit refused,
            5 transition refused, 6 render conflict (hand-edited file).
"""

RESUM_DESCRIPTION = """\
Re-sum members' stored transcript sums from their transcripts, once per API request (SPD-023), with the
per-model breakdown a list-price cost is computed from (SPD-013).

The harness writes an API response as one transcript entry per content block, each repeating the
request's message.id, requestId and usage.  A sum stored before SPD-023 added every entry, so its
tokens run four to five times too high.  A sum made since counts each request once, by its last
entry, and carries "counting": "request"; one stored before SPD-013 keeps no per-model breakdown, so
no cost can be priced from it.  Both are re-summed.  A sum with its breakdown is left as it is, so a
second run changes nothing.

The transcript read is the recorded transcript_path when that is a file; else the one file with the
same session directory and file name (<session>/subagents/agent-<id>.jsonl) under a project directory
beside the recorded one, where the harness moves a worktree session's transcripts when the session
leaves the worktree.  The new sum is merged through the run totals, so a foreground completion keeps
its whole-run duration and tool count; transcript_path becomes the file read; and each member
re-summed gets a member.edited event with its old and new figures and its old usage_json whole.
An imported sum (no transcript behind it) and a member without a transcript sum are listed and left.
"""

RESUM_EPILOG = """\
exit codes: 0 every member listed is re-summed, already counted with its breakdown, imported, or holds no
            transcript sum; 1 a sum without its breakdown was left as it is, because its transcript
            was not found, is ambiguous, cannot be read or holds no usage (the other members are
            still written, and --dry-run exits the same); 2 usage; 3 an actor other than Spud.
"""

BACKUP_DESCRIPTION = """\
Back up the ledger: PRAGMA wal_checkpoint(TRUNCATE), then VACUUM INTO .spud/backups/ledger-<stamp>.db.

--daily is the LaunchAgent's run (spud schedule).  It writes ledger-<stamp>-daily.db, unless a daily copy
for today's local date is already there: then it writes nothing and exits 0.  It runs PRAGMA quick_check
on the new copy; anything but ok removes that copy, prunes nothing and exits 1.  Then it keeps the newest
--keep daily copies (default 14): of the regular files in .spud/backups/ whose whole name is
ledger-<YYYYMMDD>T<HHMMSS>-daily.db, it unlinks the older ones, never the copy it has just written.
Nothing else is ever deleted: manual and pre-migration copies, look-alike names, directories, the live
database and its -wal and -shm all stay.  `spud doctor` reports the copies.

--json with --daily: path, written, pruned (the names unlinked) and kept (the daily copies left).
"""

BACKUP_EPILOG = """\
exit codes: 0 a copy written, or today's daily copy already there; 1 the write or its quick_check failed
            (nothing pruned); 2 usage (--keep below 1, or --keep without --daily).
"""

SCHEDULE_DESCRIPTION = """\
The macOS LaunchAgent local.spud.backup runs `spud --as spud backup --daily` at load and daily at the
--at time; launchd fires a run missed during sleep at wake, and backup --daily writes one copy a day
however often it runs.  The plist is $SPUD_LAUNCH_AGENTS_DIR/local.spud.backup.plist (default
~/Library/LaunchAgents), launchctl is $SPUD_LAUNCHCTL (default /bin/launchctl), and the run's output
goes to ~/Library/Logs/spud-backup.log.  Every verb is Spud's (--as spud).
"""


def build_parser():
    parser = argparse.ArgumentParser(prog="spud", description="The one program that writes Spud's ledger.", epilog=EPILOG, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--as", dest="actor", metavar="ACTOR", help="who is writing: spud | SPUD-nnn/<Name> | <agent_id>")
    parser.add_argument("--json", action="store_true", help="print the result as JSON")
    parser.add_argument("--version", action="version", version="spud %s (schema %d)" % (VERSION, SCHEMA_VERSION))
    sub = parser.add_subparsers(dest="command", metavar="<command>")
    sub.required = True

    p = sub.add_parser("init", help="create the database if absent, migrate if behind, refuse if ahead")
    p.set_defaults(func=cmd_init)
    p = sub.add_parser("migrate", help="apply pending migrations (backup first)")
    p.set_defaults(func=cmd_migrate)
    p = sub.add_parser("backup", help="wal_checkpoint(TRUNCATE) then VACUUM INTO .spud/backups/; --daily keeps one checked copy a day, the newest 14 (Spud's)",
                       description=BACKUP_DESCRIPTION, epilog=BACKUP_EPILOG, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--daily", action="store_true", help="write ledger-<stamp>-daily.db unless today's is there, quick_check it, then keep the newest --keep daily copies")
    p.add_argument("--keep", type=int, metavar="N", help="daily copies --daily keeps (default %d, at least 1)" % DAILY_KEEP)
    p.set_defaults(func=cmd_backup)
    p = sub.add_parser("schedule", help="the macOS LaunchAgent %s that runs `spud backup --daily` (Spud's)" % SCHEDULE_LABEL,
                       description=SCHEDULE_DESCRIPTION, formatter_class=argparse.RawDescriptionHelpFormatter)
    ps = p.add_subparsers(dest="subcommand", metavar="<subcommand>")
    ps.required = True
    q = ps.add_parser("show", help="print the plist install would write, where it goes, whether it is installed and matches, whether the job is loaded; writes nothing")
    q.add_argument("--at", type=at_arg, default=SCHEDULE_AT, metavar="HH:MM", help="the daily time of the plist to show and compare (default %s)" % SCHEDULE_AT)
    q.set_defaults(func=cmd_schedule_show)
    q = ps.add_parser("install", help="write the plist atomically, then launchctl bootout and bootstrap it in gui/<uid>; a second install replaces and reloads")
    q.add_argument("--at", type=at_arg, default=SCHEDULE_AT, metavar="HH:MM", help="the daily run, local time (default %s)" % SCHEDULE_AT)
    q.set_defaults(func=cmd_schedule_install)
    q = ps.add_parser("uninstall", help="launchctl bootout, then remove the plist")
    q.set_defaults(func=cmd_schedule_uninstall)
    p = sub.add_parser("doctor", help="interpreter, SQLite, SPUD_HOME, database pragmas, config sanity")
    p.set_defaults(func=cmd_doctor)

    p = sub.add_parser("config", help="spud.config.json mirrors")
    ps = p.add_subparsers(dest="subcommand", metavar="<subcommand>")
    ps.required = True
    q = ps.add_parser("sync", help="mirror naming.pool into name_pool and the home project's prefixes")
    q.set_defaults(func=cmd_config_sync)

    p = sub.add_parser("settings", help=".claude/settings.json generation")
    ps = p.add_subparsers(dest="subcommand", metavar="<subcommand>")
    ps.required = True
    q = ps.add_parser("sync", help="write the two env caps, the six ledger hooks, the CLI allow rules and the Agent deny rules into a settings file, keeping every other key")
    q.add_argument("--path", help="settings file (default <SPUD_HOME>/.claude/settings.json)")
    q.add_argument("--dry-run", action="store_true", help="print the result, write nothing")
    q.set_defaults(func=cmd_settings_sync)

    p = sub.add_parser("hook", help="run one harness hook event: the payload on stdin, the answer on stdout (installed by settings sync)")
    p.add_argument("event", choices=HOOK_EVENTS)
    p.set_defaults(func=cmd_hook)

    p = sub.add_parser("sql", help="run one read-only statement against the database (any actor; the inspection path)")
    p.add_argument("statement", help="SELECT, WITH, VALUES, EXPLAIN or a read-only PRAGMA")
    p.add_argument("--readonly", action="store_true", help="required: the database is opened mode=ro with query_only on")
    p.set_defaults(func=cmd_sql)

    p = sub.add_parser("import", help="import markdown-v0 trees, or accept one hand-edited rendered file with --file (Spud only)")
    p.add_argument("paths", nargs="*", help="roots, ledger/ dirs or reports/ dirs (default: SPUD_HOME)")
    p.add_argument("--file", help="accept a hand edit of this rendered file: title, priority, tags, status through the state machine, Brief/Size/Outcome; a member's Brief, Outcome and status; an appended report entry")
    p.set_defaults(func=cmd_import)

    p = sub.add_parser("render", help="regenerate ledger/ and reports/ from the database; a hand-edited file is left alone (exit 6), a note whose frontmatter only changed YAML style (Obsidian's rewrite) is rendered over and kept in the event")
    p.add_argument("--out", help="render into this directory instead of SPUD_HOME (no hash checks)")
    p.add_argument("--discard", metavar="PATH", help="overwrite this hand-edited file with the current render, keeping the discarded text in the event (Spud only)")
    p.set_defaults(func=cmd_render)

    p = sub.add_parser("ticket", help="tickets (Spud's)")
    ps = p.add_subparsers(dest="subcommand", metavar="<subcommand>")
    ps.required = True
    q = ps.add_parser("new", help="create a ticket in the home project (or --project)")
    q.add_argument("--title", required=True)
    q.add_argument("--priority", choices=PRIORITIES, default="P2")
    q.add_argument("--status", choices=("queued", "active"), default="queued")
    q.add_argument("--brief", type=text_arg)
    q.add_argument("--sizing", type=text_arg, help="the Size, persona and model decision")
    q.add_argument("--outcome", type=text_arg)
    q.add_argument("--heading", help="a shorter H1 than the title")
    q.add_argument("--tag", action="append", help="extra tag (ticket is always first)")
    q.add_argument("--project", help="project key (default spud)")
    q.add_argument("--next", type=text_arg, help="Spud's Next line, last in the report entry this writes: SPD-nnn created (<status>, <priority>): <title>")
    q.set_defaults(func=cmd_ticket_new)
    q = ps.add_parser("move", help="change a ticket's status along the state machine")
    q.add_argument("key")
    q.add_argument("--status", required=True, choices=TICKET_STATUSES)
    q.add_argument("--reason", type=text_arg)
    q.add_argument("--next", type=text_arg, help="Spud's Next line, last in the report entry this writes: SPD-nnn started|done|queued|declined: <title>")
    q.set_defaults(func=cmd_ticket_move)
    q = ps.add_parser("edit", help="edit title, heading, priority, brief, sizing, outcome, tags")
    q.add_argument("key")
    q.add_argument("--title")
    q.add_argument("--heading")
    q.add_argument("--priority", choices=PRIORITIES)
